&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;vertical-align: middle; &quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;In states like&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Assam, West Bengal, and Odisha,&lt;/span&gt;&amp;nbsp;three crops of paddy are grown in a year. These are&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Aus, Aman, and Boro.&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;text-align: justify;&quot;&gt;&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Aman, Aus, and Boro are three rice varieties:&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Aman&lt;/span&gt;:&lt;/p&gt;

&lt;ul&gt;
	&lt;li style=&quot;text-align: justify;&quot;&gt;This variety is sown in the rainy season i.e. July-August and harvested in winter.&lt;/li&gt;
	&lt;li style=&quot;text-align: justify;&quot;&gt;This variety of rice is mainly produced in India.&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Aus&lt;/span&gt;:&lt;/p&gt;

&lt;ul&gt;
	&lt;li style=&quot;text-align: justify;&quot;&gt;This variety of Rice is sown in&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;summe&lt;/span&gt;r along with the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;pre-monsoonal showers&lt;/span&gt;&amp;nbsp;and harvested in autumn.&lt;/li&gt;
	&lt;li style=&quot;text-align: justify;&quot;&gt;The rice grown out of this variety is&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;rough&lt;/span&gt;.&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Boro:&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li style=&quot;text-align: justify;&quot;&gt;This variety of rice is sown in&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;winter&lt;/span&gt;&amp;nbsp;and harvested in&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;summer&lt;/span&gt;.&lt;/li&gt;
	&lt;li style=&quot;text-align: justify;&quot;&gt;This rice is also called&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;spring rice&lt;/span&gt;.&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

