&lt;p style=&quot;&quot;&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;चावल&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;&amp;nbsp;&lt;span style=&quot;text-align: justify;&quot;&gt;है।&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;असम, पश्चिम बंगाल और ओडिशा&lt;/span&gt;&amp;nbsp;जैसे राज्यों में एक वर्ष में धान की तीन फसलें उगाई जाती हैं। ये हैं&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;ऑस, अमन और बोरो।&lt;/span&gt;&lt;/li&gt;
	&lt;li style=&quot;text-align: justify;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;अमन, औस और बोरो चावल की तीन किस्में हैं:&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot; text-align: justify;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;अमन&lt;/span&gt;:&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;यह किस्म बरसात के मौसम में यानी जुलाई-अगस्त में बोई जाती है और सर्दियों में काटी जाती है।&lt;/li&gt;
	&lt;li&gt;चावल की इस किस्म का उत्पादन मुख्य रूप से भारत में किया जाता है।&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot; text-align: justify;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;औस&lt;/span&gt;:&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;चावल की इस किस्म को&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;गर्मियों&amp;nbsp;&lt;/span&gt;में&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;पूर्वमानसून वर्षा&lt;/span&gt;&amp;nbsp;के साथ बोया जाता है और शरद ऋतु में काटा जाता है।&lt;/li&gt;
	&lt;li&gt;इस किस्म से उगाए गए चावल&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;मोटे&lt;/span&gt;&amp;nbsp;होते हैं।&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot; text-align: justify;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;बोरो&lt;/span&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;:&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;धान की इस किस्म को&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;सर्दियों&amp;nbsp;&lt;/span&gt;में बोया जाता है और&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;गर्मियों&lt;/span&gt;&amp;nbsp;में काटा जाता है।&lt;/li&gt;
	&lt;li&gt;इस चावल को&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;स्प्रिंग राइस&lt;/span&gt;&amp;nbsp;भी कहते हैं।&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

