en.value:
&lt;p style=&quot;&quot;&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Economics&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;br /&gt;
&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;Economis&amp;nbsp;&lt;/span&gt;Abhijit Sen received the Padma Bhusan for public service in 2010.&lt;/li&gt;
	&lt;li&gt;Abhijit Sen is one of India&amp;rsquo;s leading authorities on rural economy and a former member of the Planning Commission, taught economics at universities in Oxford, Cambridge, and New Delhi&amp;#39;s Jawaharlal Nehru University over the course of a career spanning more than four decades.&lt;/li&gt;
	&lt;li&gt;Additionally, he served in a variety of important government roles, notably as chair of the Commission on Agricultural Cost and Prices.&lt;/li&gt;
	&lt;li&gt;Besides, he had ties to numerous international research and multilateral institutions, including the OECD Development Centre, Asian Development Bank, UNDP, Food and Agricultural Organization (FAO), and International Fund for Agricultural Development.&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;Economist&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Abhijit Sen&lt;/span&gt;&amp;nbsp;passed away on August 29, 2022 night due to heart attack.&lt;/li&gt;
	&lt;li&gt;He was 72 year old.&lt;/li&gt;
	&lt;li&gt;He was a strong supporter of the public distribution system (PDS) of wheat and rice.&amp;nbsp;He would contend that the cost of food subsidies to the exchequer was frequently overstated and that the nation had enough financial leeway to afford both a universal PDS and a fair price for farmers&amp;#39; produce.&lt;/li&gt;
	&lt;li&gt;He was named to lead a high-level task team to develop a &amp;quot;long term grain policy&amp;quot;&amp;nbsp;in 2014.&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p style=&quot;&quot;&gt;सही उत्&amp;zwj;तर&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;&amp;#39;&lt;/span&gt;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;अर्थशास्त्र&lt;/span&gt;&amp;nbsp;&lt;/strong&gt;&lt;/u&gt;है।&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;br /&gt;
&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;अर्थशास्त्री&amp;nbsp;&lt;/span&gt;अभिजीत सेन को 2010 में सार्वजनिक सेवा के लिए पद्म भूषण मिला।&lt;/li&gt;
	&lt;li&gt;अभिजीत सेन ग्रामीण अर्थव्यवस्था पर भारत के अग्रणी अधिकारियों में से एक हैं और योजना आयोग के पूर्व सदस्य हैं, जिन्होंने चार दशकों से अधिक के करियर के दौरान ऑक्सफोर्ड, कैम्ब्रिज और नई दिल्ली के जवाहरलाल नेहरू विश्वविद्यालय के विश्वविद्यालयों में अर्थशास्त्र पढ़ाया है।&lt;/li&gt;
	&lt;li&gt;इसके अतिरिक्त, उन्होंने कई महत्वपूर्ण सरकारी भूमिकाओं में, विशेष रूप से कृषि लागत और मूल्य आयोग के अध्यक्ष के रूप में कार्य किया है।&lt;/li&gt;
	&lt;li&gt;इसके अलावा, OECD विकास केंद्र, एशियाई विकास बैंक, UNDP, खाद्य और कृषि संगठन (FAO) और कृषि विकास के लिए अंतर्राष्ट्रीय कोष सहित कई अंतरराष्ट्रीय अनुसंधान और बहुपक्षीय संस्थानों से उनके संबंध थे।&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;br /&gt;
&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;-webkit-tap-highlight-color: transparent; text-size-adjust: 100%;&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;अर्थशास्त्री&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;अभिजीत सेन&lt;/span&gt;&amp;nbsp;का 29 अगस्त 2022 की रात दिल का दौरा पड़ने से निधन हो गया।&lt;/li&gt;
	&lt;li&gt;वह 72 साल के थे।&lt;/li&gt;
	&lt;li&gt;वह गेहूं और चावल के सार्वजनिक वितरण प्रणाली (PDS) के प्रबल समर्थक थे। उनका तर्क था कि राजकोष को खाद्य सब्सिडी की लागत को अक्सर बढ़ा-चढ़ा कर बताया गया था और देश के पास एक सार्वभौमिक PDS और किसानों की उपज के लिए उचित मूल्य दोनों को वहन करने के लिए पर्याप्त वित्तीय छूट थी।&lt;/li&gt;
	&lt;li&gt;उन्हें 2014 में &amp;quot;दीर्घकालिक अनाज नीति&amp;quot; विकसित करने के लिए एक उच्च स्तरीय कार्य दल का नेतृत्व करने के लिए नामित किया गया था।&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p style=&quot;&quot;&gt;The correct answer is the&amp;nbsp;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Western Ghats&lt;/span&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;There are&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;4 biodiversity hotspots&lt;/span&gt;:&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;the Himalayas, the Western Ghats, the Indo-Burma region, and the Sundaland&lt;/span&gt;.&lt;/li&gt;
	&lt;li&gt;These&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;hotspots have numerous endemic species.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;The&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;Western Ghats&lt;/span&gt;&amp;nbsp;are present along the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;western edge of peninsular India&lt;/span&gt;&amp;nbsp;and cover most of the deciduous forests and rain forests.
	&lt;ul&gt;
		&lt;li&gt;This region consists of 6000 plant species of which 3000 are endemic.&lt;/li&gt;
		&lt;li&gt;The vegetation in this region was spread over 190,000 km&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;but has been now reduced to 43,000 km&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;.&lt;/li&gt;
		&lt;li&gt;The region is also known for 450 species of birds, 140 mammals, 260 reptiles, and 175 amphibians.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;The&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Sundaland&lt;/span&gt;&amp;nbsp;hotspot is located in&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;South-East India (south of West Bengal, Bangladesh)&lt;/span&gt;.

	&lt;ul&gt;
		&lt;li&gt;In the year 2013, the Sundaland was declared as a World Biosphere Reserve by the United Nations.&lt;/li&gt;
		&lt;li&gt;This region is famous for its rich terrestrial and marine ecosystem.&lt;/li&gt;
		&lt;li&gt;It is one of the biologically richest hotspots in the world which comprises 25,000 species of vascular plants, of which 15,000 are found only in this region.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;The&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Himalayas&amp;nbsp;&lt;/span&gt;comprises&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;North-East India, Bhutan, Central and Eastern parts of Nepal&lt;/span&gt;.
	&lt;ul&gt;
		&lt;li&gt;This region holds a record of having 163 endangered species which includes the Wild Asian Water Buffalo, One-horned Rhino, and as many as 10,000 plant species, of which 3160 are endemic.&lt;/li&gt;
		&lt;li&gt;This mountain range covers nearly 750,000 km&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;The&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;Indo-Burma Region&lt;/span&gt;&amp;nbsp;is stretched over a distance of 2,373,000 km&amp;sup2;, this region spans over the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;North-eastern states, Myanmar, Cambodia, Laos&lt;/span&gt;,&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Thailand, Vietnam, and the southern part of China&lt;/span&gt;.
	&lt;ul&gt;
		&lt;li&gt;In the last 12 years, 6 large mammal species have been discovered in this region: the Large-antlered Muntjac, the Annamite Muntjac, the Grey-shanked Douc, the Annamite Striped Rabbit, the Leaf Deer, and the Saola.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Endangered Animal Species&amp;nbsp;&lt;/span&gt;in India:&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;The Royal Bengal Tiger, The Great Asiatic Lion, The Snow Leopard, The Pig Nosed Frog, The Pink Headed Duck&lt;/span&gt;..&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p style=&quot;&quot;&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;पश्चिमी घाट&lt;/span&gt;&lt;/u&gt;&amp;nbsp;है।&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;4 जैव विविधता वाले हॉटस्पॉट&lt;/span&gt;&amp;nbsp;:&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;हिमालय, पश्चिमी घाट, भारत-बर्मा&lt;/span&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;क्षेत्र और सुंदरवन है&lt;/span&gt;।&lt;/li&gt;
	&lt;li&gt;इन&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;हॉटस्पॉट में कई स्थानिक प्रजातियां हैं।&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;पश्चिमी घाट&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;प्रायद्वीपीय भारत&lt;/span&gt;&amp;nbsp;के&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;पश्चिमी किनारे पर&lt;/span&gt;&amp;nbsp;मौजूद हैं और अधिकांश पर्णपाती जंगलों और वर्षा वनों को आच्छादित&amp;nbsp;करते हैं।
	&lt;ul&gt;
		&lt;li&gt;इस क्षेत्र में 6000 पौधों की प्रजातियाँ हैं जिनमें से 3000 स्थानिक हैं।&lt;/li&gt;
		&lt;li&gt;इस क्षेत्र में वनस्पति 190,000 &lt;span style=&quot;&quot;&gt;km&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;में फैली हुई थी, लेकिन अब यह घटकर 43,000 &lt;span style=&quot;&quot;&gt;km&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;रह गयी है।&amp;nbsp;&lt;/li&gt;
		&lt;li&gt;यह क्षेत्र पक्षियों की 450 प्रजातियों, 140 स्तनधारियों, 260 सरीसृप और 175 उभयचरों के लिए भी जाना जाता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;सुंदरवन&lt;/span&gt;&amp;nbsp;हॉटस्पॉट&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;दक्षिण-पूर्व भारत (पश्चिम बंगाल, बांग्लादेश के दक्षिण) में स्थित है।&amp;nbsp;&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;वर्ष 2013 में, सुंदरवन&amp;nbsp;को संयुक्त राष्ट्र द्वारा विश्व जीवमंडल संरक्षित क्षेत्र&amp;nbsp;के रूप में घोषित किया गया था।&lt;/li&gt;
		&lt;li&gt;यह क्षेत्र अपने समृद्ध स्थलीय और समुद्री पारिस्थितिकी तंत्र के लिए प्रसिद्ध है।&lt;/li&gt;
		&lt;li&gt;यह दुनिया में जैविक रूप से सबसे धनी&amp;nbsp;हॉटस्पॉट में से एक है, जिसमें संवहनी पौधों की 25,000 प्रजातियां शामिल हैं, जिनमें से 15,000 केवल इस क्षेत्र में पाए जाते हैं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;हिमालय&lt;/span&gt;&amp;nbsp;में&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;उत्तर-पूर्व भारत, भूटान, मध्य और&amp;nbsp;पूर्वी नेपाल के&amp;nbsp;हिस्से शामिल हैं।&amp;nbsp;&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;इस क्षेत्र में 163 लुप्तप्राय प्रजातियों के होने का रिकॉर्ड है, जिसमें जंगली एशियाई जल भैंस, एक सींग वाला गेंडा&amp;nbsp;और 10,000 पौधों की प्रजातियां शामिल हैं, जिनमें से 3160 स्थानिक हैं।&lt;/li&gt;
		&lt;li&gt;यह पर्वत श्रृंखला लगभग 750,000 &lt;span style=&quot;&quot;&gt;km&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&lt;/span&gt;&amp;nbsp;को&amp;nbsp;आच्छादित करती है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;इंडो-बर्मा क्षेत्र&lt;/span&gt;&amp;nbsp;2,373,000 &lt;span style=&quot;&quot;&gt;km&lt;/span&gt;&lt;span style=&quot; line-height: 0; position: relative; vertical-align: baseline; top: -0.5em;font-size:10.5px;&quot;&gt;2&amp;nbsp;&lt;/span&gt;की दूरी पर फैला हुआ है, यह क्षेत्र&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;उत्तर-पूर्वी राज्यों, म्यांमार, कंबोडिया, लाओस&lt;/span&gt;,&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;थाईलैंड, वियतनाम और चीन के दक्षिणी भाग में फैला है।&amp;nbsp;&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;पिछले 12 वर्षों में, इस क्षेत्र में 6 बड़ी स्तनपायी प्रजातियों: लार्ज-एंटलर्ड मंटजैक, एनामाइट मंटजेक, ग्रे-शैंकड डॉक, एनामाइट स्ट्राइप्ड रैबिट, लीफ डियर और साओला की खोज की गयी है।&amp;nbsp;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;भारत में&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;लुप्तप्राय पशु प्रजातियाँ&lt;/span&gt;&amp;nbsp;:&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;रॉयल बंगाल टाइगर, ग्रेट एशियाटिक लायन, स्नो लेपर्ड, पिग नोज़्ड फ्रॉग, पिंक हेडेड डक है&lt;/span&gt;।&lt;/li&gt;
&lt;/ul&gt;

