&lt;p style=&quot;&quot;&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;प्रधान मंत्री उज्ज्वला योजना&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;1 मई, 2016 को उत्तर प्रदेश के बलिया जिले में माननीय प्रधान मंत्री श्री नरेंद्र मोदी&amp;nbsp;&lt;/span&gt;द्वारा शुरू की गई थी।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;प्रधान मंत्री उज्ज्वला योजना (PMUY)&lt;/span&gt;&amp;nbsp;का उद्देश्य महिलाओं और बच्चों के स्वास्थ्य को ध्यान में रखते हुए स्वच्छ खाना पकाने के ईंधन &amp;ndash; LPG प्रदान करके उन्हें&amp;nbsp;सुरक्षित रखना है, ताकि उन्हें धुएँ वाली रसोई में अपने स्वास्थ्य से समझौता न करना पड़े या जलाऊ लकड़ी इकट्ठा करने के लिए असुरक्षित क्षेत्रों में भटकना न पड़े।&lt;/li&gt;
	&lt;li&gt;इस योजना के तहत&amp;nbsp;BPL परिवारों&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;को अगले 3 वर्षों में 1600 रुपये प्रति कनेक्शन&lt;/span&gt;&amp;nbsp;की सहायता से&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;5 करोड़ LPG कनेक्शन&lt;/span&gt;&amp;nbsp;प्रदान किए जाने का लक्ष्य रखा गया।&lt;/li&gt;
	&lt;li&gt;महिला सशक्तिकरण को सुनिश्चित करते हुए, विशेष रूप से ग्रामीण भारत में, घरों की महिलाओं के नाम पर कनेक्शन जारी किए गए। योजना के कार्यान्वयन के लिए 8000 करोड़ रुपये आवंटित किए गए हैं।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;सामाजिक आर्थिक और जातिगत&amp;nbsp;जनगणना के आंकड़ों के माध्यम से BPL परिवारों&lt;/span&gt;&amp;nbsp;की पहचान की कर उन्हें एल.पी.जी. कनेक्शन प्रदान करने की घोषणा की गयी।&lt;/li&gt;
&lt;/ul&gt;

