&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;​The&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;2026 Commonwealth Games&lt;/span&gt;&amp;nbsp;are also referred to as&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;Victoria 2026&lt;/span&gt;&amp;nbsp;and&amp;nbsp;the&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;XXIII Commonwealth Games.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;It is a&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;multi-sport event&amp;nbsp;&lt;/span&gt;for members of th&lt;span style=&quot;font-weight: 700;&quot;&gt;e Commonwealth.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;It is scheduled to take place across&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;four regional sites in the Australian&amp;nbsp;&lt;/span&gt;state of Victoria:&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Geelong, Bendigo, Ballarat and Gippsland.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;The&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;opening ceremonies&lt;/span&gt;&amp;nbsp;will take place at the&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;Melbourne Cricket Ground&lt;/span&gt;&amp;nbsp;in the state capital of Melbourne.&lt;/li&gt;
	&lt;li&gt;The&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Kardinia Park in Geelong&lt;/span&gt;&amp;nbsp;will host the&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;closing ceremony.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;The Games will last&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;twelve days,&lt;/span&gt;&amp;nbsp;from&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;March 17 to March 29, 2026.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;The&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;first Commonwealth Games&lt;/span&gt;&amp;nbsp;to be held following&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;Queen Elizabeth II&amp;#39;s demise and King Charles III&amp;#39;s inauguration&lt;/span&gt;&amp;nbsp;as&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Head of the Commonwealth&lt;/span&gt;&amp;nbsp;and reigning monarch of the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Commonwealth Realms on 8 September 2022.​&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;The&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;2022 Commonwealth Games&lt;/span&gt;&amp;nbsp;are also known as the&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;XXII Commonwealth Games&lt;/span&gt;&amp;nbsp;and as&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Birmingham 2022.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;It took place in&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Birmingham, England.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;After&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;Manchester in 2002 and London in 1934&lt;/span&gt;, England hosted the Commonwealth Games for the&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;third time d&lt;/span&gt;uring this event.&lt;/li&gt;
	&lt;li&gt;On&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;July 28, 2022, the opening ceremonies&lt;/span&gt;&amp;nbsp;took place at&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;Alexander Stadium.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;On August 8, 2022, the closing ceremony&lt;/span&gt;&amp;nbsp;took place.&lt;/li&gt;
	&lt;li&gt;India earned&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;61 medals&amp;nbsp;&lt;/span&gt;at the 2022 Commonwealth Games, including&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;22 Gold, 16 Silver, and 23 Bronze&lt;/span&gt;, and placed&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;fourth overall.&lt;/span&gt;​&lt;/li&gt;
&lt;/ul&gt;

