&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;2026 राष्ट्रमंडल खेलों&lt;/span&gt;&amp;nbsp;को&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;विक्टोरिया 2026 और XXIII राष्ट्रमंडल खेलों&lt;/span&gt;&amp;nbsp;के रूप में भी जाना जाता है।&lt;/li&gt;
	&lt;li&gt;यह&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;राष्ट्रमंडल&lt;/span&gt;&amp;nbsp;के सदस्यों के लिए एक&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;बहु-खेल आयोजन&lt;/span&gt;&amp;nbsp;है।&lt;/li&gt;
	&lt;li&gt;यह ऑस्ट्रेलियाई राज्य विक्टोरिया में चार क्षेत्रीय स्थलों पर होने वाला है:&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;जिलॉन्ग, बेंडिगो, बैलरट और गिप्सलैंड&lt;/span&gt;।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;उद्घाटन समारोह&amp;nbsp;&lt;/span&gt;राज्य की राजधानी मेलबर्न में&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;मेलबर्न क्रिकेट ग्राउंड&lt;/span&gt;&amp;nbsp;में होगा।&lt;/li&gt;
	&lt;li&gt;जिलॉन्ग का&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;कार्दिनिया पार्क समापन समारोह की मेजबानी&lt;/span&gt;&amp;nbsp;करेगा।&lt;/li&gt;
	&lt;li&gt;खेल&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;17 मार्च से 29 मार्च, 2026&lt;/span&gt;&amp;nbsp;तक&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;बारह दिनों&lt;/span&gt;&amp;nbsp;तक चलेंगे।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;महारानी एलिजाबेथ द्वितीय के निधन और राष्ट्रमंडल के प्रमुख के रूप में किंग चार्ल्स III के उद्घाटन और 8 सितंबर 2022 को राष्ट्रमंडल&lt;/span&gt;&amp;nbsp;क्षेत्रों के शासक&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;के रूप में&amp;nbsp;&lt;/span&gt;आयोजित होने&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;वाले पहले राष्ट्रमंडल खेल।​&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;2022 राष्ट्रमंडल खेलों को XXII राष्ट्रमंडल खेलों और बर्मिंघम 2022&amp;nbsp;&lt;/span&gt;के रूप में भी जाना जाता है।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;यह इंग्लैंड के बर्मिंघम&amp;nbsp;&lt;/span&gt;में हुआ था।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;2002 में मैनचेस्टर और 1934 में लंदन&lt;/span&gt;&amp;nbsp;के बाद, इंग्लैंड ने इस आयोजन के दौरान तीसरी बार राष्ट्रमंडल खेलों की मेजबानी की।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;28 जुलाई, 2022 को उद्घाटन समारोह सिकंदर स्टेडियम&amp;nbsp;&lt;/span&gt;में हुआ।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;8 अगस्त 2022 को समापन समारोह&amp;nbsp;&lt;/span&gt;हुआ।&lt;/li&gt;
	&lt;li&gt;भारत ने 2022 राष्ट्रमंडल खेलों में&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;22 स्वर्ण, 16 रजत और 23 कांस्य&lt;/span&gt;&amp;nbsp;सहित&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;61 पदक&amp;nbsp;&lt;/span&gt;अर्जित किए और कुल मिलाकर&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;चौथे स्थान पर र&lt;/span&gt;हा।​&lt;span style=&quot;font-weight: 700;&quot;&gt;​&lt;/span&gt;​&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is &lt;strong&gt;&lt;u&gt;Pratap Singh&lt;/u&gt;.&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;Pratap Singh&amp;nbsp;was sent to England as the representative of Marwar in 1887, to attend the Golden Jubilee celebration of Queen Victoria&lt;/strong&gt;&lt;/u&gt;

	&lt;ul&gt;
		&lt;li&gt;In 1887, on the completion of 50 years of Queen Victoria&amp;#39;s reign, the Golden Jubilee celebrations were celebrated in London.&lt;/li&gt;
		&lt;li&gt;On this occasion, Maharaja Jaswant Singh sent Sir Pratap to London as his representative giving him the title of &amp;#39;Maharajadhiraj&amp;#39;.&lt;/li&gt;
		&lt;li&gt;Pratap Singh was the first among the Rajput kings to travel by ship from Mumbai to Europe.&lt;/li&gt;
		&lt;li&gt;On completion of 50 years of Queen Victoria&amp;#39;s reign, Pratap Singh got the Jubilee Cold constructed near Raikabagh railway station.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;Maharaj Gaj Singh of Jodhpur&lt;/strong&gt; had three sons &amp;ndash; &lt;strong&gt;Amar Singh&lt;/strong&gt;, &lt;strong&gt;Jaswant Singh,&lt;/strong&gt; and &lt;strong&gt;Achal Singh.&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;​Maharaja Jaswant Singh -&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;He was the&lt;strong&gt; ruler of Marwar. &lt;/strong&gt;He was a &lt;strong&gt;Rathor Rajput.&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;He was a&lt;strong&gt; good writer&lt;/strong&gt; who composed books named &amp;#39;&lt;strong&gt;Siddhanta-Bodh&lt;/strong&gt;&amp;#39;, &amp;#39;&lt;strong&gt;Anandvilas&amp;#39; &lt;/strong&gt;and &lt;strong&gt;&amp;#39;Bhashabhushan&lt;/strong&gt;&amp;#39;.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Kalyan Singh -&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;He was a famous Indian politician, &lt;strong&gt;former Governor of Rajasthan&lt;/strong&gt;, and former Chief Minister of Uttar Pradesh.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;प्रताप सिंह&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;प्रताप सिंह को महारानी विक्टोरिया के स्वर्ण जयंती&lt;span style=&quot;&quot;&gt;&amp;nbsp;उत्सव&lt;/span&gt;&lt;strong&gt; &lt;/strong&gt;में भाग लेने के लिए 1887 में मारवाड़ के प्रतिनिधि के रूप में इंग्लैंड भेजा गया था।&lt;/strong&gt;&lt;/u&gt;

	&lt;ul&gt;
		&lt;li&gt;1887 में महारानी विक्टोरिया के शासन के 50 वर्ष पूरे होने पर लंदन में स्वर्ण जयंती&lt;span style=&quot;&quot;&gt;&amp;nbsp;&lt;/span&gt;समारोह मनाया गया था।&lt;/li&gt;
		&lt;li&gt;इस अवसर पर महाराजा जसवंत सिंह ने सर प्रताप को &amp;#39;महाराजाधिराज&amp;#39; की उपाधि देकर अपना प्रतिनिधि बनाकर लंदन भेजा।&lt;/li&gt;
		&lt;li&gt;प्रताप सिंह राजपूत राजाओं में पहले थे जिन्होंने मुंबई से यूरोप तक जहाज से यात्रा की।&lt;/li&gt;
		&lt;li&gt;महारानी विक्टोरिया के शासन के 50 साल पूरे होने पर प्रताप सिंह ने रायकाबाग रेलवे स्टेशन के पास जुबली कोल्ड का निर्माण करवाया।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&amp;nbsp;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;जोधपुर के महाराज गज सिंह&lt;/strong&gt; के तीन पुत्र थे- &lt;strong&gt;अमर सिंह, जसवंत सिंह और अचल सिंह।&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;महाराजा जसवंत सिंह&lt;/strong&gt; -
	&lt;ul&gt;
		&lt;li&gt;यह &lt;strong&gt;मारवाड़ का शासक&lt;/strong&gt; था। वह &lt;strong&gt;राठौर राजपूत&lt;/strong&gt; थे।&lt;/li&gt;
		&lt;li&gt;वे एक &lt;strong&gt;अच्छे लेखक&lt;/strong&gt; थे जिन्होंने &amp;#39;&lt;strong&gt;सिद्धांत-बोध&lt;/strong&gt;&amp;#39;, &amp;#39;&lt;strong&gt;आनंदविलास&lt;/strong&gt;&amp;#39; और &amp;#39;&lt;strong&gt;भाषाभूषण&lt;/strong&gt;&amp;#39; नामक ग्रंथों की रचना की।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;कल्याण सिंह &lt;/strong&gt;-
	&lt;ul&gt;
		&lt;li&gt;वह एक प्रसिद्ध भारतीय राजनीतिज्ञ, &lt;strong&gt;राजस्थान के पूर्व राज्यपाल&lt;/strong&gt; और उत्तर प्रदेश के पूर्व मुख्यमंत्री थे।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&lt;strong&gt; Udaipur.&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;The &lt;strong&gt;7th session &lt;/strong&gt;of the All India National State Lok Parishad was&lt;strong&gt; held at Salodia Maidan in Udaipur&lt;/strong&gt;.&lt;/li&gt;
	&lt;li&gt;This session lasted from &lt;strong&gt;31 December 1945 to 1 January 1946.&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;This session was &lt;strong&gt;presided over by Pandit Jawaharlal Nehru.&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;​All India National State Public Council -&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;This council was&lt;strong&gt; established&lt;/strong&gt; to tie the people of the indigenous states in one thread and &lt;strong&gt;give a coordinated form&lt;/strong&gt; to their movements.&lt;/li&gt;
		&lt;li&gt;This council was &lt;strong&gt;established in 1927 AD&lt;/strong&gt; under the &lt;strong&gt;chairmanship of Bahadur Ramchandra Rao&lt;/strong&gt; to establish responsible governance.&lt;/li&gt;
		&lt;li&gt;Its &lt;strong&gt;first session&lt;/strong&gt; was &lt;strong&gt;held in Bombay&lt;/strong&gt; in &lt;strong&gt;December 1927.&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;After 1927, its branches were also established in the native states.&lt;/li&gt;
		&lt;li&gt;And at that time &lt;strong&gt;Jayanarayan&lt;/strong&gt; was made the &lt;strong&gt;minister of its Rajasthan branch&lt;/strong&gt;.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;strong&gt;उदयपुर&lt;/strong&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;अखिल भारतीय राष्ट्रीय राज्य लोक परिषद का &lt;strong&gt;7वां अधिवेशन&lt;/strong&gt; &lt;strong&gt;उदयपुर के सलोदिया मैदान में आयोजित&lt;/strong&gt; हुआ था।&lt;/li&gt;
	&lt;li&gt;यह अधिवेशन &lt;strong&gt;31 दिसम्बर 1945 से 1 जनवरी 1946&lt;/strong&gt; तक चला।&lt;/li&gt;
	&lt;li&gt;इस अधिवेशन की &lt;strong&gt;अध्यक्षता पंडित जवाहरलाल नेहरू ने की&lt;/strong&gt; थी।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;अखिल भारतीय राष्ट्रीय राज्य लोक परिषद -&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;देशी रियासतों की जनता को एक सूत्र में बांधने तथा उनके आंदोलनों को &lt;strong&gt;समन्वित रूप&lt;/strong&gt; देने के लिए इस परिषद की &lt;strong&gt;स्थापना&lt;/strong&gt; की गई थी।&lt;/li&gt;
		&lt;li&gt;इस परिषद् की &lt;strong&gt;स्थापना 1927 ई&lt;/strong&gt;. &lt;strong&gt;में&lt;/strong&gt; &lt;strong&gt;बहादुर रामचंद्र राव की अध्यक्षता&lt;/strong&gt; में उत्तरदायित्वपूर्ण शासन स्थापित करने के लिए की गई थी।&lt;/li&gt;
		&lt;li&gt;इसका &lt;strong&gt;प्रथम अधिवेशन दिसम्बर 1927 में बम्बई में&lt;/strong&gt; हुआ।&lt;/li&gt;
		&lt;li&gt;1927 के बाद देशी रियासतों में भी इसकी शाखाएँ स्थापित की गईं।&lt;/li&gt;
		&lt;li&gt;और उस समय &lt;strong&gt;जयनारायण&lt;/strong&gt; को &lt;strong&gt;इसकी राजस्थान शाखा का मंत्री&lt;/strong&gt; बनाया गया था।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Kishori Devi.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;This &lt;span style=&quot;&quot;&gt;Kisan&amp;nbsp;Andolan&amp;nbsp;&lt;/span&gt;was organized at &lt;strong&gt;Katrathal in Sikar &lt;/strong&gt;on the call of&lt;strong&gt; Kishori Devi ji&lt;/strong&gt;, the &lt;strong&gt;wife of Sardar Harlal Singh ji Kharra.&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;​&lt;span style=&quot;&quot;&gt;Shekhawati Kisan&amp;nbsp;Andolan -&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;​This movement started on&lt;strong&gt; April 25, 1934&lt;/strong&gt;, in protest against the indecency with the Jatanis by &lt;strong&gt;Thakur of &amp;#39;Sihot&amp;#39;.&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;This movement was led by &lt;strong&gt;Sardar Harlal Singh Ji Kharra.&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;This Mahasammelan was organized at &lt;strong&gt;Katrathal in Sikar&lt;/strong&gt; on the call of&lt;strong&gt; Kishori Devi ji,&lt;/strong&gt; the wife of&lt;strong&gt; Sardar Harlal Singh ji &lt;/strong&gt;Kharra.&lt;/li&gt;
		&lt;li&gt;This movement was the &lt;strong&gt;first and last Jat Mahila Sammelan&lt;/strong&gt; in the history of Rajasthan.&lt;/li&gt;
		&lt;li&gt;For the&lt;strong&gt; first time&lt;/strong&gt;, about 10,000 Jatanis registered their presence in the program.&lt;/li&gt;
		&lt;li&gt;The main speaker of this conference was&lt;strong&gt; Utma Devi, the wife of Thakur Deshraj,&lt;/strong&gt; the &lt;strong&gt;first Jat historian.&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;She gave such a wonderful speech that every Jat woman present at the conference supported her wholeheartedly.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Durga Devi Sharma -&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;During this &lt;strong&gt;Salt Satyagraha&lt;/strong&gt;, he burnt expensive clothes till his marriage.&lt;/li&gt;
		&lt;li&gt;Later, Prabhat Pheri, etc. with the women of Ajmer, Beawar got involved in work. She&lt;strong&gt; went to jail &lt;/strong&gt;twice in &lt;strong&gt;1931-32.&lt;/strong&gt;​&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;strong&gt;किशोरी देवी&lt;/strong&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;यह किसान आंदोलन &lt;strong&gt;सरदार हरलाल सिंह जी खर्रा की पत्नी&lt;/strong&gt; &lt;strong&gt;किशोरी देवी जी&lt;/strong&gt; के आह्वान पर &lt;strong&gt;सीकर&lt;/strong&gt; के &lt;strong&gt;कटराथल में&lt;/strong&gt; आयोजित किया गया था।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;शेखावाटी किसान आंदोलन -&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;यह आंदोलन &lt;strong&gt;25 अप्रैल, 1934&lt;/strong&gt; को &lt;strong&gt;&amp;#39;सीहोट&amp;#39; के ठाकुर&lt;/strong&gt; द्वारा जटानियों के साथ की गई अभद्रता के विरोध में शुरू हुआ था।&lt;/li&gt;
		&lt;li&gt;इस आंदोलन का नेतृत्व &lt;strong&gt;सरदार हरलाल सिंह जी खर्रा&lt;/strong&gt; ने किया था।&lt;/li&gt;
		&lt;li&gt;यह महासम्मेलन &lt;strong&gt;सरदार हरलाल सिंह जी&lt;/strong&gt; खर्रा की धर्मपत्नी &lt;strong&gt;किशोरी देवी जी&lt;/strong&gt; के आह्वान पर &lt;strong&gt;सीकर के कटराथल&lt;/strong&gt; में आयोजित किया गया था।&lt;/li&gt;
		&lt;li&gt;यह आंदोलन राजस्थान के इतिहास में &lt;strong&gt;पहला और आखिरी जाट महिला सम्मेलन&lt;/strong&gt; था।&lt;/li&gt;
		&lt;li&gt;कार्यक्रम में &lt;strong&gt;पहली बार&lt;/strong&gt; करीब 10 हजार जटानियों ने अपनी उपस्थिति दर्ज कराई।&lt;/li&gt;
		&lt;li&gt;इस सम्मेलन की मुख्य वक्ता &lt;strong&gt;प्रथम जाट इतिहासकार ठाकुर देशराज की पत्नी उत्तमा देवी&lt;/strong&gt; थीं।&lt;/li&gt;
		&lt;li&gt;उन्होंने ऐसा अद्भुत भाषण दिया कि सम्मेलन में उपस्थित प्रत्येक जाट महिला ने उनका जी भर कर समर्थन किया।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;दुर्गा देवी शर्मा -&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;इस &lt;strong&gt;नमक सत्याग्रह&lt;/strong&gt; के दौरान उन्होंने अपने विवाह तक के महंगे कपड़े जलाए।&lt;/li&gt;
		&lt;li&gt;बाद में अजमेर, ब्यावर की महिलाओं के साथ प्रभात फेरी आदि कार्य में जुट गए। &lt;strong&gt;1931-32&lt;/strong&gt; में वे दो बार &lt;strong&gt;जेल गईं।&lt;/strong&gt;​&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p style=&quot;&quot;&gt;The correct answer is &lt;u&gt;&lt;strong&gt;Agra&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;The observatory was not built in &lt;/span&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Agra&lt;/span&gt;&lt;/strong&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt; by Sawai Jai Singh&lt;/span&gt;&lt;/u&gt;.&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;vertical-align: middle; &quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Observatory&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;Sawai Jai Singh made five observatories at&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Jaipur, Delhi, Ujjain, Mathura, Varanasi&lt;/span&gt;.&lt;/li&gt;
		&lt;li&gt;The biggest of them is Jantar Mantar, Jaipur.&lt;/li&gt;
		&lt;li&gt;Jantar Mantar was built in 1728.&lt;/li&gt;
		&lt;li&gt;It has the largest sun clock in the world.&lt;/li&gt;
		&lt;li&gt;It has been included in UNESCO&amp;#39;s world heritage site in July 2010.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;vertical-align: middle; &quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Sawai Jai Singh II&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;Sawai Jai Singh II was also called Chanakya.&lt;/li&gt;
		&lt;li&gt;He was ambitious to be chairman of the Hurda Conference on 17 July 1734 but could not be.&lt;/li&gt;
		&lt;li&gt;He made an agreement with Peshwa Balaji Rao which is also called the Dhaulpur agreement, 1741.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p style=&quot;&quot;&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;आगरा &lt;/strong&gt;&lt;/u&gt;है।&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;आगरा में सवाई जय सिंह द्वारा वेधशाला नहीं बनाई गई थी।&lt;/span&gt;&lt;/u&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;vertical-align: middle; &quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;वेधशाला&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;सवाई जय सिंह ने&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;जयपुर, दिल्ली, उज्जैन, मथुरा, वाराणसी&amp;nbsp;&lt;/span&gt;में पाँच वेधशालाएँ बनाईं।&lt;/li&gt;
		&lt;li&gt;उनमें से सबसे बड़ी जंतर मंतर,जयपुर है।&lt;/li&gt;
		&lt;li&gt;जंतर मंतर 1728 में बनाया गया था।&lt;/li&gt;
		&lt;li&gt;यह दुनिया में सबसे बड़ी सूर्य घड़ी है।&lt;/li&gt;
		&lt;li&gt;इसे जुलाई 2010 में यूनेस्को की विश्व धरोहर स्थल में सम्मिलित&amp;nbsp;किया गया है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;vertical-align: middle; &quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;सवाई जय सिंह द्वितीय&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;सवाई जय सिंह द्वितीय को चाणक्य भी कहा जाता था।&lt;/li&gt;
		&lt;li&gt;वे 17 जुलाई 1734 को हुरड़ा सम्मलेन के अध्यक्ष होना चाहते थे, लेकिन&amp;nbsp;हो&amp;nbsp;नहीं&amp;nbsp;सके।&lt;/li&gt;
		&lt;li&gt;उन्होंने 1741 में पेशवा बालाजी राव के साथ एक समझौता किया, जिसे धौलपुर समझौता भी कहा जाता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;7.&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;Indira Gandhi Canal&amp;#39;s total&lt;strong&gt; lift canals &lt;/strong&gt;are &lt;strong&gt;&amp;#39;7&amp;#39;.&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;One has been built in the&lt;strong&gt; first phase and six&lt;/strong&gt; in the &lt;strong&gt;second phase.&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;It &lt;strong&gt;provides irrigation&lt;/strong&gt; to &lt;strong&gt;8 districts&lt;/strong&gt; and &lt;strong&gt;drinking water&lt;/strong&gt; to &lt;strong&gt;10 districts.&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;​Indira Gandhi Canal -&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;This canal has become the&lt;strong&gt; lifeline for Rajasthan.&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;This canal starts from the &lt;strong&gt;Harike barrage &lt;/strong&gt;built at the confluence of the &lt;strong&gt;Sutlej and Beas rivers&lt;/strong&gt; near &lt;strong&gt;Firozpur in Punjab.&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;The longest canal&lt;/strong&gt; in the country is &lt;strong&gt;649 km&lt;/strong&gt; long.&lt;/li&gt;
		&lt;li&gt;Out of this, there is a&lt;strong&gt; 204-kilometer&lt;/strong&gt; feeder canal from &lt;strong&gt;Punjab to Rajasthan&lt;/strong&gt;. And the main city is 445 km away.&lt;/li&gt;
		&lt;li&gt;The depth of this canal on the border of Rajasthan is &lt;strong&gt;21 feet&lt;/strong&gt; and the width of the bottom is&lt;strong&gt; 134 feet&lt;/strong&gt; and the surface is &lt;strong&gt;218 feet&lt;/strong&gt; wide.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;Nine branches&lt;/strong&gt; emerge from the main canal extending from Masitawali in Hanumangarh to Mohangarh in Jaisalmer.&lt;/li&gt;
		&lt;li&gt;Its distributaries for irrigation are&lt;strong&gt; 9,245 km &lt;/strong&gt;long.&lt;/li&gt;
		&lt;li&gt;The people of ten desert districts of Rajasthan get the benefit of the water of this canal.&lt;/li&gt;
		&lt;li&gt;Apart from this, the canal here also provides water for &lt;strong&gt;many power projects&lt;/strong&gt;.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर&amp;nbsp;&lt;strong&gt;7&lt;/strong&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;इंदिरा गांधी नहर की कुल &lt;strong&gt;लिफ्ट&amp;nbsp;नहरें &amp;#39;7&amp;#39;&lt;/strong&gt; हैं।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;पहले चरण&lt;/strong&gt; में एक &lt;strong&gt;और&lt;/strong&gt; &lt;strong&gt;दूसरे चरण&lt;/strong&gt; में &lt;strong&gt;छह&lt;/strong&gt; का निर्माण हो चुका है।&lt;/li&gt;
	&lt;li&gt;यह &lt;strong&gt;8 जिलों&lt;/strong&gt; को &lt;strong&gt;सिंचाई&lt;/strong&gt; और 1&lt;strong&gt;0 जिलों&lt;/strong&gt; को &lt;strong&gt;पेयजल प्रदान करता है।&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;इंदिरा गांधी नहर -&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;यह नहर &lt;strong&gt;राजस्थान की जीवन रेखा&lt;/strong&gt; बन गई है।&lt;/li&gt;
		&lt;li&gt;यह नहर &lt;strong&gt;पंजाब में फिरोजपुर&lt;/strong&gt; के पास &lt;strong&gt;सतलुज और ब्यास नदियों&lt;/strong&gt; के संगम पर बने &lt;strong&gt;हरिके बैराज&lt;/strong&gt; से शुरू होती है।&lt;/li&gt;
		&lt;li&gt;देश की &lt;strong&gt;सबसे लंबी नहर 649 किलोमीटर&lt;/strong&gt; लंबी है।&lt;/li&gt;
		&lt;li&gt;इसमें से &lt;strong&gt;पंजाब से राजस्थान&lt;/strong&gt; तक &lt;strong&gt;204 किलोमीटर&lt;/strong&gt; लंबी फीडर नहर है। और मुख्य शहर 445 किलोमीटर दूर है।&lt;/li&gt;
		&lt;li&gt;राजस्थान की सीमा पर स्थित इस नहर की गहराई &lt;strong&gt;21 फुट&lt;/strong&gt; तथा तल की चौड़ाई &lt;strong&gt;134 फुट&lt;/strong&gt; तथा सतह की चौड़ाई &lt;strong&gt;218 फुट&lt;/strong&gt; है।&lt;/li&gt;
		&lt;li&gt;हनुमानगढ़ में मासीतावली से जैसलमेर में मोहनगढ़ तक फैली मुख्य नहर से &lt;strong&gt;नौ शाखाएँ&lt;/strong&gt; निकलती हैं।&lt;/li&gt;
		&lt;li&gt;सिंचाई के लिए इसकी वितरिकाएं &lt;strong&gt;9,245 किलोमीटर&lt;/strong&gt; लंबी हैं।&lt;/li&gt;
		&lt;li&gt;राजस्थान के दस रेगिस्तानी जिलों के लोगों को इस नहर के पानी का लाभ मिलता है।&lt;/li&gt;
