&lt;p&gt;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li style=&quot;&quot;&gt;Barren and Narcondam are the two volcanic islands located in the Indian Territory.&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Barren Island&lt;/span&gt;:&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;It is located in the&amp;nbsp;Andaman Sea.&lt;/li&gt;
	&lt;li&gt;It is dominated by Barren Volcano which is the only confirmed&amp;nbsp;active volcano&amp;nbsp;in&amp;nbsp;South Asia.&lt;/li&gt;
	&lt;li&gt;This volcano is also the only active volcano along a chain of volcanoes from Myanmar to Sumatra.&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Narcondam Island:&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;It is located in the Andaman Sea.&lt;/li&gt;
