&lt;p style=&quot;&quot;&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;अनुच्छेद - 249&lt;/span&gt;&lt;/u&gt;&amp;nbsp;है।&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;भारतीय संविधान का अनुच्छेद 249 राज्य सूची में विषयों के संबंध में&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;संसद की विधायी शक्तियों&lt;/span&gt;&amp;nbsp;से संबंधित है। यह संसद को राज्य सूची में शामिल किसी भी मामले के संबंध में कानून बनाने का अधिकार देता है।&lt;/li&gt;
	&lt;li&gt;राष्ट्रपति तीन प्रकार की आपात स्थितियों की घोषणा कर सकते हैं:
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;राष्ट्रीय आपातकाल&lt;/span&gt;- अनुच्छेद 352&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;राज्य आपातकाल&lt;/span&gt;- अनुच्छेद 356&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;वित्तीय आपातकाल&lt;/span&gt;- अनुच्छेद 360&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;लोकसभा का विघटन-अनुच्छेद 83 (2)&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;अनुच्छेद 253:&lt;/span&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;अंतरराष्ट्रीय समझौतों को लागू करने के लिए&lt;/strong&gt; कानून बनाने के लिए संसद को &lt;strong&gt;शक्तियां&lt;/strong&gt; प्रदान करता है&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;अनुच्छेद 223&lt;/span&gt;&amp;nbsp;उच्च न्यायालय के मुख्य न्यायाधीश का पद रिक्त होने पर&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;कार्यवाहक मुख्य न्यायाधीश की नियुक्ति&lt;/span&gt;&amp;nbsp;से संबंधित है।&lt;/li&gt;
	&lt;li&gt;अनुच्छेद 293-राज्य द्वारा ऋण लेने का उल्लेख करता है।&lt;/li&gt;
&lt;/ul&gt;

