&lt;p&gt;सही उत्तर &lt;strong&gt;चरणदासी&lt;/strong&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;सहजो बाई -&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;वह राजपुताना के एक प्रतिष्ठित धूसर (वैश्य) कबीले से ताल्लुक रखती थीं।&lt;/li&gt;
		&lt;li&gt;उनके पिता का नाम &lt;strong&gt;हरिप्रसाद&lt;/strong&gt; था।&lt;/li&gt;
		&lt;li&gt;वे &lt;strong&gt;संत चरणदास जी&lt;/strong&gt; (चरणदासी संप्रदाय) &lt;strong&gt;की शिष्या&lt;/strong&gt; थीं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;चरणदासी संप्रदाय -&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;इस संप्रदाय के &lt;strong&gt;संस्थापक&lt;/strong&gt; &lt;strong&gt;संत चरणदास&lt;/strong&gt; थे।&lt;/li&gt;
		&lt;li&gt;उनका &lt;strong&gt;जन्म 1703 ई. में&lt;/strong&gt; &lt;strong&gt;मेवात क्षेत्र&lt;/strong&gt; के देहरा नामक ग्राम में हुआ था।&lt;/li&gt;
		&lt;li&gt;1781 ई. में दिल्ली में उनका देहावसान हो गया।&lt;/li&gt;
		&lt;li&gt;इस सम्प्रदाय में &lt;strong&gt;निःस्वार्थ प्रेम और सदाचार&lt;/strong&gt; पर बल देते हुए गुरु भक्ति को ही मोक्ष प्राप्ति का साधन बताया गया है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;रामस्नेही संप्रदाय -&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;इस &lt;strong&gt;संप्रदाय के संस्थापक स्वामी रामचरण जी महाराज&lt;/strong&gt; थे।&lt;/li&gt;
		&lt;li&gt;उनका जन्म &lt;strong&gt;वर्ष 1776&lt;/strong&gt; में हुआ था।&lt;/li&gt;
		&lt;li&gt;इस समुदाय ने लोक भाषा में धर्म का अर्थ समझाकर &lt;strong&gt;आम आदमी को&lt;/strong&gt; &lt;strong&gt;एक करने&lt;/strong&gt; में महत्वपूर्ण &lt;strong&gt;भूमिका निभाई&lt;/strong&gt; है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;अलखदासी&amp;nbsp;संप्रदाय -&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;यह मध्यकालीन भारत का एक &lt;strong&gt;हिंदू संप्रदाय&lt;/strong&gt; है।&lt;/li&gt;
		&lt;li&gt;इसे &lt;strong&gt;बौद्ध धर्म की महायान शाखा&lt;/strong&gt; का भाग माना जाता है।&lt;/li&gt;
		&lt;li&gt;इस संप्रदाय के संत &lt;strong&gt;उड़ीसा&lt;/strong&gt; और उत्तरी भारत के &lt;strong&gt;कई हिस्सों&lt;/strong&gt; में पाए जाते थे।&lt;/li&gt;
		&lt;li&gt;इस संप्रदाय के ऋषि स्वयं को महान रहस्यवादी योगी और &amp;#39;अलख&amp;#39; का लेखक बताते थे।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;लालदासी संप्रदाय -&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;मध्यकाल में &lt;strong&gt;मेवात क्षेत्र&lt;/strong&gt; में &lt;strong&gt;धार्मिक पुनर्जागरण&lt;/strong&gt; का कार्य &lt;strong&gt;प्रसिद्ध संत लालदास जी&lt;/strong&gt; &lt;strong&gt;ने किया&lt;/strong&gt; था।&lt;/li&gt;
		&lt;li&gt;इनका जन्म 1540 ई. में धौली दुव ग्राम (अलवर) में हुआ था।&lt;/li&gt;
		&lt;li&gt;इस समुदाय में वे &lt;strong&gt;राम नाम के जप&lt;/strong&gt; और &lt;strong&gt;कीर्तन को अधिक प्राथमिकता&lt;/strong&gt; देते हैं।&lt;/li&gt;
		&lt;li&gt;मध्यकाल में मेवात क्षेत्र में धार्मिक पुनर्जागरण का कार्य प्रसिद्ध संत लालदास जी ने किया था।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&lt;u&gt;&lt;strong&gt;&amp;nbsp;&lt;span style=&quot;&quot;&gt;Dr. B.R. Ambedkar.&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Dr Ambedkar was independent India&amp;#39;s first Law Minister.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;div aria-level=&quot;3&quot; data-attrid=&quot;wa:/description&quot; data-hveid=&quot;CAsQAA&quot; role=&quot;heading&quot; style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li aria-level=&quot;3&quot; data-attrid=&quot;wa:/description&quot; data-hveid=&quot;CAsQAA&quot; role=&quot;heading&quot;&gt;Dr B.R. Ambedkar, popularly known as&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Baba Saheb&lt;/span&gt;, served as Independent&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;India&amp;#39;s first law minister&lt;/span&gt;.&lt;/li&gt;
	&lt;li aria-level=&quot;3&quot; data-attrid=&quot;wa:/description&quot; data-hveid=&quot;CAsQAA&quot; role=&quot;heading&quot;&gt;He was an Indian jurist, economist, politician, and social reformer.&amp;nbsp;&lt;/li&gt;
	&lt;li aria-level=&quot;3&quot; data-attrid=&quot;wa:/description&quot; data-hveid=&quot;CAsQAA&quot; role=&quot;heading&quot;&gt;He was born on&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;14th April 1891&lt;/span&gt;.&lt;/li&gt;
	&lt;li aria-level=&quot;3&quot; data-attrid=&quot;wa:/description&quot; data-hveid=&quot;CAsQAA&quot; role=&quot;heading&quot;&gt;This year &lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;2023&amp;nbsp;&lt;/span&gt;Dr Ambedkar Jayanti is his &lt;strong&gt;132&lt;/strong&gt; birth anniversary.&lt;/li&gt;
	&lt;li aria-level=&quot;3&quot; data-attrid=&quot;wa:/description&quot; data-hveid=&quot;CAsQAA&quot; role=&quot;heading&quot;&gt;Dr B.R.Ambedkar was the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Chairman of the Drafting Committee&amp;nbsp;&lt;/span&gt;which presented the final draft of the Indian Constitution in 1949.&lt;/li&gt;
	&lt;li aria-level=&quot;3&quot; data-attrid=&quot;wa:/description&quot; data-hveid=&quot;CAsQAA&quot; role=&quot;heading&quot;&gt;He presented the highest civilian honour in India,&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Bharat Ratna&amp;nbsp;&lt;/span&gt;in 1990, posthumously.&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;Thus,&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;the first Law and Justice Minister of independent India was Bhim Rao Ambedkar.&amp;nbsp;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;
	&lt;div data-md=&quot;61&quot;&gt;
	&lt;div aria-level=&quot;3&quot; data-attrid=&quot;wa:/description&quot; data-hveid=&quot;CA8QAA&quot; role=&quot;heading&quot;&gt;&lt;strong&gt;Arjun Ram Meghwal&lt;/strong&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;&lt;/span&gt;is currently the Cabinet Minister of Law and Justice of India.&lt;/div&gt;
	&lt;/div&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;strong&gt;&lt;u&gt;डॉ. बी. आर. अम्बेडकर&lt;/u&gt;&lt;/strong&gt; है।&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;डॉ. अंबेडकर स्वतंत्र भारत के पहले कानून मंत्री थे।&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;डॉ. बी.आर. अंबेडकर, जिन्हें&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;बाबा साहेब&lt;/span&gt;&amp;nbsp;के नाम से जाना जाता है, ने स्वतंत्र&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;भारत के पहले कानून मंत्री&amp;nbsp;&lt;/span&gt;के रूप में कार्य किया।&lt;/li&gt;
	&lt;li&gt;वह एक भारतीय न्यायविद, अर्थशास्त्री, राजनीतिज्ञ और समाज सुधारक थे।&lt;/li&gt;
	&lt;li&gt;उनका जन्म&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;14 अप्रैल, 1891&amp;nbsp;&lt;/span&gt;को हुआ था।&lt;/li&gt;
	&lt;li&gt;इस वर्ष 2023 उनकी 132वीं जयंती पूरे देश में मनाई जा रही है।&lt;/li&gt;
	&lt;li&gt;1949 में भारतीय संविधान का अंतिम&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;प्रारूप&lt;/span&gt;&amp;nbsp;प्रस्तुत करने वाली प्रारूप&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;समिति के अध्यक्ष&amp;nbsp;&lt;/span&gt;डॉ. बी.आर. अम्बेडकर थे।&lt;/li&gt;
	&lt;li&gt;उन्होंने मरणोपरांत 1990 में भारत में सर्वोच्च नागरिक सम्मान,&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;भारत रत्न&lt;/span&gt;&amp;nbsp;प्रदान किया।&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;इस प्रकार,&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;स्वतंत्र भारत के प्रथम&amp;nbsp;कानून और न्याय मंत्री भीम राव अंबेडकर थे।&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;strong&gt;अर्जुन राम मेघवाल&lt;/strong&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;&lt;/span&gt;वर्तमान में भारत के कानून और न्याय के कैबिनेट मंत्री हैं।&lt;/li&gt;
&lt;/ul&gt;

