hn.value:
&lt;p&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;strong&gt;ऊर्जा एवं संसाधन संस्थान (&lt;/strong&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;TERI&lt;/span&gt;&lt;strong&gt;)&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;फरवरी (2022)&lt;/strong&gt;&lt;/u&gt; में &lt;u&gt;&lt;strong&gt;ऊर्जा और संसाधन संस्थान (&lt;span style=&quot;&quot;&gt;TERI&lt;/span&gt;)&lt;/strong&gt;&lt;/u&gt; ने &lt;u&gt;&lt;strong&gt;&amp;#39;विश्व सतत विकास शिखर सम्मेलन&amp;#39;&lt;/strong&gt;&lt;/u&gt; की मेजबानी की थी।

	&lt;ul&gt;
		&lt;li&gt;&lt;strong&gt;प्रधानमंत्री&amp;nbsp;नरेंद्र मोदी &lt;/strong&gt;ने 16 फरवरी 2022 को वीडियो संदेश के माध्यम से &lt;strong&gt;ऊर्जा एवं संसाधन संस्थान (&lt;/strong&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;TERI&lt;/span&gt;&lt;strong&gt;) विश्व सतत विकास शिखर सम्मेलन&lt;/strong&gt; में उद्घाटन भाषण दिया था।&lt;/li&gt;
		&lt;li&gt;शिखर सम्मेलन टी.ई.आर.आई. (TERI) का वार्षिक प्रमुख कार्यक्रम है और 2022 की थीम&amp;nbsp;&lt;strong&gt;&amp;#39;टुवार्ड्स ए रेजिलिएंट प्लैनेट: इंश्योरिंग ए सस्टेनेबल एंड इक्विटेबल फ्यूचर&amp;#39;&amp;nbsp;&lt;/strong&gt;है।&lt;/li&gt;
		&lt;li&gt;3 दिवसीय शिखर सम्मेलन में &lt;strong&gt;डोमिनिकन गणराज्य, गुयाना आदि &lt;/strong&gt;के &lt;strong&gt;राष्ट्रपति&lt;/strong&gt; भाग लेंगे।&lt;/li&gt;
		&lt;li&gt;शिखर सम्मेलन में &lt;strong&gt;जलवायु परिवर्तन, टिकाऊ उत्पादन, ऊर्जा संक्रमण, वैश्विक आम और संसाधन सुरक्षा सहित&lt;/strong&gt; कई मुद्दों पर चर्चा होगी।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;TERI:&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;strong&gt;ऊर्जा और संसाधन संस्थान&lt;/strong&gt; एक शोध संस्थान है जो &lt;strong&gt;ऊर्जा, पर्यावरण और सतत विकास के क्षेत्र &lt;/strong&gt;में विशेषज्ञता रखता है।&lt;/li&gt;
		&lt;li&gt;इसकी स्थापना &lt;strong&gt;1974&lt;/strong&gt; में हुई थी।&lt;/li&gt;
		&lt;li&gt;इसे पहले &lt;strong&gt;टाटा ऊर्जा अनुसंधान संस्थान&lt;/strong&gt;&amp;nbsp;के नाम से जाना जाता था।&lt;/li&gt;
		&lt;li&gt;इसका मुख्यालय&lt;strong&gt; नई दिल्ली&lt;/strong&gt; में है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

