	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;संरक्षित क्षेत्र&lt;/span&gt;&lt;/strong&gt;&amp;nbsp;राष्ट्रीय उद्यानों और अभयारण्यों से सटे राज्य के स्वामित्व वाले क्षेत्र हैं, जो परिदृश्य, समुद्र के दृश्य और जीवों और वनस्पतियों के आवास के संरक्षण के लिए हैं।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;शाकंभरी &lt;span style=&quot;&quot;&gt;संरक्षित क्षेत्र&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;यह &lt;strong&gt;सीकर और झुंझुनू&lt;/strong&gt; जिलों में है&lt;span style=&quot;&quot;&gt;।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;यह 2012 में स्थापित किया गया था।&lt;/li&gt;
		&lt;li&gt;यह 13100 हेक्टेयर क्षेत्र में फैला हुआ है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;बीड &lt;/strong&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;संरक्षित क्षेत्र&lt;/strong&gt;&amp;nbsp;&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;यह &lt;strong&gt;झुंझुनू&lt;/strong&gt; जिले में है&lt;span style=&quot;&quot;&gt;।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;यह 2013 में स्थापित किया गया था।&lt;/li&gt;
		&lt;li&gt;यह 1040 हेक्टेयर क्षेत्र में फैला हुआ है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;मनसा माता &lt;/strong&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;संरक्षित क्षेत्र&lt;/strong&gt;&amp;nbsp;&lt;/span&gt;​
	&lt;ul&gt;
		&lt;li&gt;यह &lt;strong&gt;झुंझुनू &lt;/strong&gt;जिले में है&lt;span style=&quot;&quot;&gt;।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;यह 102310 हेक्टेयर क्षेत्र में फैला हुआ है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Maharana&amp;nbsp;Shambhu Singh&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;In Mewar state, the &amp;#39;Mahkama Khas&amp;#39; was established by&amp;nbsp;&lt;/strong&gt;&lt;/u&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Maharana&amp;nbsp;Shambhu Singh&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;In the state of Mewar, &amp;#39;Mahakama Khas&amp;#39; (Supreme Court of Justice) was established in 1869 AD by Maharana Shambhu Singh.&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;He was the Maharana &lt;/span&gt;of the Princely state of Udaipur.&lt;span style=&quot;&quot;&gt;​&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;He ascended the throne as a minor and a British Political agent was appointed to guide him.&lt;/li&gt;
		&lt;li&gt;After attaining complete control, he set up various new rules and offices for improving administrative resources.&lt;/li&gt;
		&lt;li&gt;He introduced a new legal code for Mewar.&lt;/li&gt;
		&lt;li&gt;Under him, the military was reorganized and&amp;nbsp;various jail reforms were introduced.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Maharana&amp;nbsp;Ajit Singh&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;He&amp;nbsp;was the ruler of the Marwar region in present-day Rajasthan.&lt;/li&gt;
		&lt;li&gt;He formed an alliance with Sawai Raja Jai Singh II of Amer and set upon capturing his ancestral lands which had been occupied by the Mughals.&lt;/li&gt;
		&lt;li&gt;In 1712, Ajit Singh was given more power with his appointment as Mughal governor of Gujarat.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Maharana Sajjan&amp;nbsp;Singh&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​He&amp;nbsp;&lt;/span&gt;was the Maharana of the princely state of Udaipur.&lt;/li&gt;
		&lt;li&gt;He&amp;nbsp;was adopted by his first cousin Maharana Shambhu Singh, whom he succeeded in 1874.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Maharana Ganga&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;Singh&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​He&amp;nbsp;&lt;/span&gt;was the ruling Maharaja of the princely state of Bikaner.&lt;/li&gt;
		&lt;li&gt;As a ruler, he established a Chief Court in Bikaner, presided over by a Chief Judge who was assisted by two judges.&lt;/li&gt;
		&lt;li&gt;As a member of the Imperial War Cabinet, he was present in the Palace of Versailles during The Signing of Peace in the Hall of Mirrors.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्&amp;zwj;तर &lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;महाराणा शंभु सिंह&lt;/strong&gt;&lt;/u&gt;&amp;nbsp;&lt;/span&gt;है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&amp;nbsp;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;मेवाड़ राज्य में &amp;#39;महकामा खास&amp;#39; की स्थापना महाराणा शंभु सिंह ने की थी।&lt;/strong&gt;&lt;/u&gt;

	&lt;ul&gt;
		&lt;li&gt;मेवाड़ राज्य में, &amp;#39;महाकामा खास&amp;#39; (न्याय का सर्वोच्च न्यायालय) की स्थापना 1869 ई. में महाराणा शंभु सिंह ने की थी।&lt;/li&gt;
		&lt;li&gt;वह उदयपुर रियासत के महाराणा थे&lt;span style=&quot;&quot;&gt;।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;वह एक नाबालिग के रूप में सिंहासन पर बेठे और उसका मार्गदर्शन करने के लिए एक ब्रिटिश राजनीतिक एजेंट नियुक्त किया गया।&lt;/li&gt;
		&lt;li&gt;पूर्ण नियंत्रण प्राप्त करने के बाद, उन्होंने प्रशासनिक संसाधनों में सुधार के लिए विभिन्न नए नियमों और कार्यालयों की स्थापना की।&lt;/li&gt;
		&lt;li&gt;उन्होंने मेवाड़ के लिए एक नया कानूनी कोड पेश किया।&lt;/li&gt;
		&lt;li&gt;उसके तहत, सेना को पुनर्गठित किया गया और विभिन्न जेल सुधार पेश किए गए।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;महाराणा अजीत सिंह&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;वह वर्तमान राजस्थान में मारवाड़ क्षेत्र के शासक थे।&lt;/li&gt;
		&lt;li&gt;उन्होंने आमेर के सवाई राजा जय सिंह द्वितीय के साथ एक गठबंधन बनाया और अपनी पुश्तैनी जमीनों पर कब्जा करने के लिए तैयार हो गए, जिन पर मुगलों का कब्जा था।&lt;/li&gt;
		&lt;li&gt;1712 में, गुजरात के मुगल गवर्नर के रूप में उनकी नियुक्ति के साथ अजीत सिंह को और अधिक शक्ति दी गई थी।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;महाराणा सज्जन सिंह&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;वे उदयपुर रियासत के महाराणा थे।&lt;/li&gt;
		&lt;li&gt;उन्हें उनके पहले चचेरे भाई महाराणा शंभु सिंह ने गोद लिया था, जो 1874 में उनके उत्तराधिकारी बने।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;महाराणा गंगा सिंह&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;वह बीकानेर रियासत के शासक महाराजा थे।&lt;/li&gt;
		&lt;li&gt;एक शासक के रूप में, उन्होंने बीकानेर में एक मुख्य न्यायालय की स्थापना की, जिसकी अध्यक्षता एक मुख्य न्यायाधीश करते थे, जिन्हें दो न्यायाधीशों द्वारा सहायता प्रदान की जाती थी।&lt;/li&gt;
		&lt;li&gt;इंपीरियल वॉर कैबिनेट के सदस्य के रूप में, वह द साइनिंग ऑफ पीस इन द हॉल ऑफ मिरर्स के दौरान वर्साय के पैलेस में मौजूद थे।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Horticulture&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Horticulture&lt;/strong&gt;&lt;/u&gt;&amp;nbsp;is covered under the &lt;u&gt;&lt;strong&gt;Market Intervention Scheme (MIS) of the Indian Government&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;The objective of the intervention is to protect the growers of these commodities in the event of a bumper crop during the peak arrival period.&lt;/li&gt;
		&lt;li&gt;The scheme is implemented at the request of a State/UT government which is ready to bear 50 percent of the loss (25 percent in the case of North-Eastern States), if any, incurred on its implementation.&lt;/li&gt;
		&lt;li&gt;​The&amp;nbsp;Government implements a Market Intervention Scheme (MIS) for the&amp;nbsp;procurement of agricultural and horticultural commodities which are perishable in nature and are not covered under the Price Support Scheme (PSS).&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;A &lt;strong&gt;Minimum Support Price (MSP)&lt;/strong&gt; is a form of market intervention scheme by the central government. The scheme secures agricultural producers against any sharp fall in farm prices.&lt;/li&gt;
	&lt;li&gt;The &lt;strong&gt;Government has fixed MSPs for 23 crops&lt;/strong&gt;:
	&lt;ul&gt;
		&lt;li&gt;7 kinds of cereal (Paddy, Wheat, Maize, Bajra, Jowar, Ragi, and Barley)&lt;/li&gt;
		&lt;li&gt;5 pulses (Chana, Arhar/Tur, Urad, Moong, and Masur)&amp;nbsp;&lt;/li&gt;
		&lt;li&gt;7 oilseeds (Rapeseed-Mustard, Groundnut, Soybean, Sunflower, Sesamum, Safflower, and Nigerseed)&lt;/li&gt;
		&lt;li&gt;4 commercial crops (Cotton, Sugarcane, Copra, and Raw Jute).&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;बागवानी&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&amp;nbsp;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;u&gt;बागवानी&lt;/u&gt; &lt;u&gt;भारत सरकार की बाजार हस्तक्षेप योजना&lt;/u&gt;&lt;/strong&gt; (&lt;u style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;MIS&lt;/span&gt;&lt;/u&gt;) के अंतर्गत आती है।

	&lt;ul&gt;
		&lt;li&gt;हस्तक्षेप का उद्देश्य चरम आगमन अवधि के दौरान बंपर फसल की स्थिति में इन वस्तुओं के उत्पादकों की रक्षा करना है।&lt;/li&gt;
		&lt;li&gt;यह योजना एक राज्य/केंद्र शासित प्रदेश सरकार के अनुरोध पर लागू की जाती है जो इसके कार्यान्वयन पर होने वाले नुकसान का 50 प्रतिशत (पूर्वोत्तर राज्यों के मामले में 25 प्रतिशत), यदि कोई हो, वहन करने के लिए तैयार है।&lt;/li&gt;
		&lt;li&gt;सरकार कृषि और बागवानी वस्तुओं की खरीद के लिए बाजार हस्तक्षेप योजना (&lt;span style=&quot;&quot;&gt;MIS&lt;/span&gt;) को लागू करती है जो प्रकृति में खराब होने वाली हैं और मूल्य समर्थन योजना (&lt;span style=&quot;&quot;&gt;PSS&lt;/span&gt;) के अंतर्गत नहीं आती हैं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&amp;nbsp;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;न्यूनतम समर्थन मूल्य (MSP)&lt;/strong&gt; केंद्र सरकार द्वारा बाजार हस्तक्षेप योजना का एक रूप है। यह योजना कृषि उत्पादकों को कृषि कीमतों में किसी भी तेज गिरावट के खिलाफ सुरक्षित करती है।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;सरकार ने 23 फसलों के लिए &lt;span style=&quot;font-weight: 700; &quot;&gt;MSP&amp;nbsp;&lt;/span&gt;तय किया है:&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;7 प्रकार के अनाज (धान, गेहूं, मक्का, बाजरा, ज्वार, रागी और जौ)&lt;/li&gt;
		&lt;li&gt;5 दालें (चना, अरहर/तूर, उड़द, मूंग और मसूर)&lt;/li&gt;
		&lt;li&gt;7 तिलहन (सरसों, मूंगफली, सोयाबीन, सूरजमुखी, तिल, कुसुम और नाइजरसीड)&lt;/li&gt;
		&lt;li&gt;4 व्यावसायिक फसलें (कपास, गन्ना, खोपरा और कच्चा जूट)&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p style=&quot;&quot;&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Lucknow&lt;/span&gt;&lt;/u&gt;&lt;em&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;.&lt;/span&gt;&lt;/u&gt;&lt;/em&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;The&amp;nbsp;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Indian Institute of Sugarcane&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Research&lt;/strong&gt;&lt;/u&gt; is situated in &lt;u&gt;&lt;strong&gt;Lucknow&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;strong&gt;Indian Sugarcane Research Institute&lt;/strong&gt; celebrated its &lt;strong&gt;71st Foundation Day&lt;/strong&gt; on &lt;strong&gt;16 February 2022&lt;/strong&gt;.&lt;/li&gt;
		&lt;li&gt;The &lt;strong&gt;Indian Sugarcane Research Institute&lt;/strong&gt; was&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;&lt;/span&gt;established in&lt;span style=&quot;font-weight: 700;&quot;&gt; Lucknow, Uttar Pradesh&lt;/span&gt;&amp;nbsp;on &lt;strong&gt;16 February&lt;/strong&gt;&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;1952&lt;/span&gt;&amp;nbsp;to increase sugarcane production and create new varieties.&lt;/li&gt;
		&lt;li&gt;The&lt;strong&gt; Indian Institute of Sugarcane Research (IISR)&lt;/strong&gt;, &lt;strong&gt;Lucknow &lt;/strong&gt;was established in 1&lt;span style=&quot;font-weight: 700;&quot;&gt;952 by the erstwhile Indian Central Sugarcane Committee&amp;nbsp;&lt;/span&gt;for conducting research on fundamental and applied aspects of &lt;strong&gt;sugarcane culture &lt;/strong&gt;as well as to co-ordinate the research work done on this crop in different States of the country.&lt;/li&gt;
		&lt;li&gt;The &lt;strong&gt;Government of India&lt;/strong&gt; took over the Institute from the&lt;strong&gt; Indian Central Sugarcane Committee&lt;/strong&gt; on &lt;strong&gt;1st January 1954&lt;/strong&gt;.&lt;/li&gt;
		&lt;li&gt;On April 1,&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;1969, it was transferred to the Indian Council of Agricultural Research (ICAR), New Delhi&amp;nbsp;&lt;/span&gt;along with other central agricultural research institutes.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;The &lt;strong&gt;Indian Institute of Vegetable Research&lt;/strong&gt; is in &lt;strong&gt;Varanasi&lt;/strong&gt;.&lt;/li&gt;
	&lt;li&gt;The &lt;strong&gt;Indian Institute of Pulse Research&lt;/strong&gt; is in &lt;strong&gt;Kanpur&lt;/strong&gt;.&lt;/li&gt;
	&lt;li&gt;The&lt;strong&gt; Indian Agricultural&amp;nbsp;Research Institute&lt;/strong&gt; is in &lt;strong&gt;New Delhi&lt;/strong&gt;.&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;लखनऊ&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;भारतीय गन्ना अनुसंधान संस्थान&lt;/strong&gt;&lt;/u&gt; &lt;u&gt;&lt;strong&gt;लखनऊ&lt;/strong&gt;&lt;/u&gt; में स्थित है।

	&lt;ul&gt;
		&lt;li&gt;&lt;strong&gt;भारतीय गन्ना अनुसंधान संस्थान&lt;/strong&gt; ने &lt;strong&gt;16 फरवरी 2022 &lt;/strong&gt;को अपना &lt;strong&gt;71वां स्थापना दिवस&lt;/strong&gt; मनाया था।&lt;/li&gt;
		&lt;li&gt;गन्ने का उत्पादन बढ़ाने और नई किस्में बनाने के लिए &lt;strong&gt;16 फरवरी 1952 &lt;/strong&gt;को &lt;strong&gt;लखनऊ, उत्तर प्रदेश &lt;/strong&gt;में &lt;strong&gt;भारतीय गन्ना अनुसंधान संस्थान&lt;/strong&gt; की स्थापना की गई थी।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;भारतीय गन्ना अनुसंधान संस्थान (IISR), लखनऊ &lt;/strong&gt;की स्थापना &lt;strong&gt;1952 &lt;/strong&gt;में&lt;strong&gt; तत्कालीन भारतीय केंद्रीय गन्ना समिति द्वारा गन्ना संस्कृति&lt;/strong&gt; के मौलिक और देश की अनुप्रयुक्त पहलुओं पर अनुसंधान करने के साथ-साथ विभिन्न राज्यों में इस फसल पर किए गए शोध कार्य का समन्वय करने के लिए की गई थी।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;भारत सरकार &lt;/strong&gt;ने &lt;strong&gt;1 जनवरी 1954&lt;/strong&gt; को&lt;strong&gt; भारतीय केंद्रीय गन्ना समिति &lt;/strong&gt;से संस्थान का अधिग्रहण किया था।&lt;/li&gt;
		&lt;li&gt;1 अप्रैल, &lt;strong&gt;1969 &lt;/strong&gt;को इसे अन्य केंद्रीय कृषि अनुसंधान संस्थानों के साथ&lt;strong&gt; भारतीय कृषि अनुसंधान परिषद (ICAR), नई दिल्ली को स्थानांतरित कर दिया गया था।&lt;/strong&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;भारतीय सब्जी अनुसंधान संस्थान वाराणसी&lt;/strong&gt; में है।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;भारतीय &lt;/span&gt;&lt;strong&gt;दाल&lt;/strong&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt; अनुसंधान संस्थान&lt;/span&gt;&lt;strong&gt; कानपुर&lt;/strong&gt; में है।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;भारतीय कृषि अनुसंधान संस्थान नई दिल्ली&lt;/strong&gt; में है।&lt;/li&gt;
&lt;/ul&gt;

