hn.value:
&lt;p&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;strong&gt;राज वल्लभ - महाराणा कुम्भा&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;अमरसार&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;यह &lt;strong&gt;पंडित जीवाधर&lt;/strong&gt; द्वारा रचित पुस्तक है।&lt;/li&gt;
		&lt;li&gt;इसमें उन्होंने महाराणा प्रताप और महाराणा अमर सिंह के इतिहास की जानकारी दी है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;राजवल्लभ&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;इसे मंडन लिखते हैं।&lt;/li&gt;
		&lt;li&gt;यह 15वीं सदी के सैन्य संगठन, वास्तुकला और मेवाड़ के बारे में जानकारी प्रदान करता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;पाबू प्रकाश&lt;/strong&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;इसे &lt;strong&gt;मोदजी आशिया कृत&lt;/strong&gt; द्वारा लिखा गया है।&lt;/li&gt;
		&lt;li&gt;पाबू राजस्थान के लोकदेवता हैं।&lt;/li&gt;
		&lt;li&gt;पुस्तक में पाबूजी के सामाजिक, आर्थिक, राजनीतिक और ऐतिहासिक वर्णन को दर्शाया गया है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;राज प्रकाश&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​&lt;/span&gt;इसे राज प्रकाश लिखते हैं।&lt;/li&gt;
		&lt;li&gt;इस ग्रंथ में महाराणा राज सिंह द्वारा टीके की दौड़ के बहाने मुगल क्षेत्रों को लूटने का वर्णन है।&lt;/li&gt;
		&lt;li&gt;यह ग्रंथ हल्दीघाटी युद्ध में महाराणा प्रताप की विजय के बारे में&amp;nbsp; बताता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Vagad-Sikar, Jhunjhunu&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Vagad is a region in southeastern Rajasthan state.&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;Its boundaries are roughly defined by those of the districts of Dungarpur and Banswara.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Shivi Janapada&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;The Shibis (Shivi) migrated from Punjab to Rajasthan and settled at Madhyamika.&lt;/li&gt;
		&lt;li&gt;Capital: - Madhyamika (Present name Nagari)&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;Present region: - Chittorgarh And Udaipur districts&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;It was Rajasthan&amp;rsquo;s first excavated site.&lt;/li&gt;
		&lt;li&gt;It was excavated by D.R. Bhandarkar.&amp;nbsp;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Sapadalaksha&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;strong&gt;Chauhans of Ajmer&lt;/strong&gt; ruled several parts of Rajasthan and called it&amp;nbsp;Sapadalaksha.&lt;/li&gt;
		&lt;li&gt;​It&amp;nbsp;was also&amp;nbsp;the ancient name of &lt;strong&gt;Nagaur.&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;It included one lakh villages.&lt;/li&gt;
		&lt;li&gt;As the Chahamana territory expanded, the entire region ruled by them also expanded.&lt;/li&gt;
		&lt;li&gt;It included&amp;nbsp;Chahamana capitals Ajayameru (Ajmer) and Shakambhari (Sambhar).&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Arbud Desh&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;Son of Rao Sobha Ji, Shreshthmal had founded the present city of Sirohi on the western slope of Siranwa Hills&lt;/li&gt;
		&lt;li&gt;He laid the foundation stone of the Sirohi Fort on the second day (Dvitiya) of Vaishakh in the year 1482 (V.S.) i.e. 1425 (A.D.).&lt;/li&gt;
		&lt;li&gt;It was known as the capital and the entire area under Deora&amp;rsquo;s known as Sirohi later on.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;In puranic tradition, this area has been referred to as &amp;ldquo;Arbudh Pradesh&amp;rdquo; and Arbundachal i.e. Arbud+ Anchal.&lt;/strong&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;Sikar, Churu district, and Jhunjhunu districts comprise the Shekhawati region of Rajasthan. The old name of Sikar was &amp;quot;Veer Bhan Ka Bas&amp;quot;.&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्&amp;zwj;तर &lt;u&gt;&lt;strong&gt;वागड़-सीकर, झुंझुनू&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;वागड़ दक्षिण-पूर्वी राजस्थान राज्य का एक क्षेत्र है।&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;इसकी सीमाएँ मोटे तौर पर डूंगरपुर और बांसवाड़ा जिलों द्वारा परिभाषित की जाती हैं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;शिव जनपद&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;शिबि (शिवि) पंजाब से राजस्थान चले गए और मध्यमिका में बस गए।&lt;/li&gt;
		&lt;li&gt;राजधानी :- मध्यमिका (वर्तमान नाम नागरी)&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;वर्तमान क्षेत्र :- चित्तौड़गढ़ एवं उदयपुर जिले&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;यह राजस्थान का पहला उत्खनन स्थल था।&lt;/li&gt;
		&lt;li&gt;इसकी खुदाई डी.आर. भंडारकर द्वारा की गई थी।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;सपादलक्ष&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;strong&gt;अजमेर के चौहानों&lt;/strong&gt; ने राजस्थान के कई हिस्सों पर शासन किया और इसे सपादलक्ष कहा।&lt;/li&gt;
		&lt;li&gt;यह &lt;strong&gt;नागौर&lt;/strong&gt; का प्राचीन नाम भी था।&lt;/li&gt;
		&lt;li&gt;इसमें एक लाख गांव शामिल थे।&lt;/li&gt;
		&lt;li&gt;जैसे-जैसे चाहमना क्षेत्र का विस्तार हुआ, उनके द्वारा शासित पूरे क्षेत्र का भी विस्तार हुआ।&lt;/li&gt;
		&lt;li&gt;इसमें चौहानों की राजधानियाँ अजयमेरु (अजमेर) और शाकंभरी (सांभर) शामिल थीं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;अर्बुद देश&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;राव सोभा जी के पुत्र, श्रेष्ठमल ने सिरनवा पहाड़ियों के पश्चिमी ढलान पर सिरोही के वर्तमान शहर की स्थापना की थी।&lt;/li&gt;
		&lt;li&gt;उन्होंने वर्ष 1482 (विक्र.सं.) यानी 1425 (ईस्वी) में वैशाख के दूसरे दिन (द्वितीया) को सिरोही किले की आधारशिला रखी।&lt;/li&gt;
		&lt;li&gt;इसे राजधानी के रूप में जाना जाता था और देवड़ा के तहत पूरे क्षेत्र को बाद में सिरोही के नाम से जाना जाता था।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;पौराणिक परंपरा में इस क्षेत्र को &amp;quot;अर्बुध प्रदेश&amp;quot; और अर्बुंदचल यानी अर्बुद+अंचल कहा गया है।&lt;/strong&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;सीकर, चुरू जिले और झुंझुनू जिलों में राजस्थान का शेखावाटी क्षेत्र शामिल है। सीकर का पुराना नाम &amp;quot;वीर भान का बास&amp;quot; था।&lt;/li&gt;
&lt;/ul&gt;

