&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&amp;nbsp;&lt;span style=&quot;&quot;&gt;Janki Devi Bajaj&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​She&amp;nbsp;&lt;/span&gt;was an Indian independence activist who was jailed for participating in Civil Disobedience Movement in 1932.&lt;/li&gt;
		&lt;li&gt;After independence, she worked with Vinoba Bhave on the Bhoodan movement.&lt;/li&gt;
		&lt;li&gt;She conferred Padma Vibhushan the second-highest civilian award in 1956.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;She received it&lt;span style=&quot;&quot;&gt;&amp;nbsp;for her active participation in Bhoodah and Kup Daan programs.&lt;/span&gt;&lt;/strong&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Narayani&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;Varma&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​She&amp;nbsp;&lt;/span&gt;was an Indian freedom fighter and social worker.&lt;/li&gt;
		&lt;li&gt;She was the wife of Manikyalal Verma, a freedom fighter.&lt;/li&gt;
		&lt;li&gt;In the year 1939, he had to go to jail for participating in the works of Prajamandal.&lt;/li&gt;
		&lt;li&gt;She came to Bhilwara in 1944 AD and established Mahila Ashram Sanstha.&lt;/li&gt;
		&lt;li&gt;She&amp;nbsp;was a member of the Rajya Sabha from 1970 to 1976 AD. He died on March 12, 1977.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Ratan Shastri&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;​&lt;/strong&gt;She&amp;nbsp;&lt;/span&gt;was the founder of Banasthali Vidyapith.&lt;/li&gt;
		&lt;li&gt;She was a recipient of Padma Shri in 1955, and Padma Bhushan in 1975.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Anjana&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;Choudhary&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​She&amp;nbsp;&lt;/span&gt;was the wife of freedom fighter Ramnarayan Chowdhary.&lt;/li&gt;
		&lt;li&gt;She&amp;nbsp;rebelled against feudal tyranny.&lt;/li&gt;
		&lt;li&gt;She participated in Seva Gram Ashram from 1939-1942 AD.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;Padma Awards - One of the highest civilian awards of the country, are awarded in three categories, namely Padma Vibhushan, Padma Bhushan, and Padma Shri.
	&lt;ul&gt;
		&lt;li&gt;The awards are given in various disciplines/areas of activities, such as arts, social work, public affairs, science and engineering, trade and industry, medicine, literature and education, sports, civil service, etc.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;&amp;#39;Padma Vibhushan&amp;#39; &lt;/strong&gt;is given for exceptional and distinguished service.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;&amp;#39;Padma Bhushan&lt;/strong&gt;&amp;#39; for distinguished service of a high order.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;&amp;#39;Padma Shri&amp;#39;&lt;/strong&gt; for distinguished service in any field. These awards are announced every year on the occasion of Republic Day.&amp;nbsp;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;जानकी देवी बजाज&lt;/strong&gt;&lt;/u&gt; &lt;span style=&quot;&quot;&gt;है&lt;/span&gt;।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;जानकी देवी बजाज&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;वह एक भारतीय स्वतंत्रता कार्यकर्ता थीं, जिन्हें 1932 में सविनय अवज्ञा आंदोलन में भाग लेने के लिए जेल में डाल दिया गया था।&lt;/li&gt;
		&lt;li&gt;आजादी के बाद उन्होंने भूदान आंदोलन पर विनोबा भावे के साथ काम किया&lt;span style=&quot;&quot;&gt;&amp;nbsp;था।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;उन्होंने 1956 में पद्म विभूषण को दूसरे सर्वोच्च नागरिक पुरस्कार से सम्मानित किया&lt;span style=&quot;&quot;&gt;&amp;nbsp;था।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;भूदान&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;और कुप दान कार्यक्रमों में उनकी सक्रिय भागीदारी के लिए उन्हें यह प्राप्त हुआ था।&lt;/strong&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;नारायणी वर्मा&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;वह एक भारतीय स्वतंत्रता सेनानी और सामाजिक कार्यकर्ता थीं।&lt;/li&gt;
		&lt;li&gt;वह एक स्वतंत्रता सेनानी माणिकयाल वर्मा की पत्नी थीं।&lt;/li&gt;
		&lt;li&gt;सन् 1939 में प्रजामंडल के कार्यों में भाग लेने के कारण उन्हें जेल जाना पड़ा था।&lt;/li&gt;
		&lt;li&gt;वे 1944 ई. में भीलवाड़ा आईं और महिला आश्रम संस्था की स्थापना की थी।&lt;/li&gt;
		&lt;li&gt;वे 1970 से 1976 ई. तक राज्य सभा की सदस्य रहीं। 12 मार्च 1977 को उनका निधन हो गया&lt;span style=&quot;&quot;&gt;&amp;nbsp;था।&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;रतन शास्त्री&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;वह वनस्थली विद्यापीठ की संस्थापक थीं।&lt;/li&gt;
		&lt;li&gt;वह 1955 में पद्म श्री और 1975 में पद्म भूषण की प्राप्तकर्ता थीं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;अंजना चौधरी&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;वह स्वतंत्रता सेनानी रामनारायण चौधरी की पत्नी थीं।&lt;/li&gt;
		&lt;li&gt;उसने सामंती अत्याचार के खिलाफ विद्रोह किया था।&lt;/li&gt;
		&lt;li&gt;उन्होंने 1939-1942 ई. तक सेवा ग्राम आश्रम में भाग लिया&lt;span style=&quot;&quot;&gt;&amp;nbsp;था।&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;पद्म पुरस्कार - देश के सर्वोच्च नागरिक पुरस्कारों में से एक, तीन श्रेणियों में प्रदान किया जाता है, अर्थात् पद्म विभूषण, पद्म भूषण और पद्म श्री।
	&lt;ul&gt;
		&lt;li&gt;पुरस्कार विभिन्न विषयों/गतिविधियों के क्षेत्रों में दिए जाते हैं, जैसे कला, सामाजिक कार्य, सार्वजनिक मामले, विज्ञान और इंजीनियरिंग, व्यापार और उद्योग, चिकित्सा, साहित्य और शिक्षा, खेल, सिविल सेवा आदि।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;&amp;#39;पद्म विभूषण&amp;#39; &lt;/strong&gt;असाधारण और विशिष्ट सेवा के लिए दिया जाता है।&lt;/li&gt;
		&lt;li&gt;उच्च कोटि की विशिष्ट सेवा के लिए &lt;strong&gt;&amp;#39;पद्म भूषण&amp;#39;&lt;/strong&gt;।&lt;/li&gt;
		&lt;li&gt;किसी भी क्षेत्र में विशिष्ट सेवा के लिए &lt;strong&gt;&amp;#39;पद्म श्री&amp;#39;&lt;/strong&gt;। इन पुरस्कारों की घोषणा हर साल गणतंत्र दिवस के अवसर पर की जाती है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

