&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;जिप्सीफेरस मृदा&lt;/strong&gt;&lt;/u&gt; &lt;u&gt;&lt;strong&gt;राजस्थान&lt;/strong&gt;&lt;/u&gt; के &lt;u&gt;&lt;strong&gt;बीकानेर&lt;/strong&gt;&lt;/u&gt; जिले में पाई जाती है।

	&lt;ul&gt;
		&lt;li&gt;इस &lt;span style=&quot;&quot;&gt;मृदा&lt;/span&gt; में पर्याप्त मात्रा में &lt;strong&gt;जिप्सम&lt;/strong&gt; होता है जो पौधों की वृद्धि को रोकता है।&lt;/li&gt;
		&lt;li&gt;यह &lt;span style=&quot;&quot;&gt;मृदा&lt;/span&gt; आमतौर पर&lt;strong&gt; नम जलवायु &lt;/strong&gt;में नहीं पाई जाती है।&lt;/li&gt;
		&lt;li&gt;यह &lt;span style=&quot;&quot;&gt;मृदा&lt;/span&gt; &lt;strong&gt;शुष्क क्षेत्रों&lt;/strong&gt; में पायी जाती है, जहाँ कैल्शियम सल्फेट के स्रोत मौजूद हैं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;कृषि&amp;nbsp;से संबंधित &lt;span style=&quot;&quot;&gt;मृदा&lt;/span&gt; और अन्य स्थान-&lt;/strong&gt;&lt;/p&gt;

&lt;table border=&quot;1&quot; cellpadding=&quot;1&quot; cellspacing=&quot;1&quot; style=&quot; width: 250px;&quot;&gt;
	&lt;tbody&gt;
