en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Rao Chhatrasal&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;Rao Raja Chattar Sal&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;He was a prominent ruler&amp;nbsp;&lt;/span&gt;of the Kingdom of Bundi.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;He also built the temple of Keshavarao at Keshoraipatan and the Chathra Mahal at Bundi.&lt;span style=&quot;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;He was&amp;nbsp;&lt;/span&gt;considered an integral part of the Mughal army by Shah Jahan.&lt;/li&gt;
		&lt;li&gt;He&amp;nbsp;died fighting as the head of his Hada Rajput troops&amp;nbsp;in the Battle of Samugarh in 1658.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;In the olden days, during the 18th century, the town of Bundi was a home and a stronghold of miniature painting artists, and the local kings greatly encouraged miniature paintings.
	&lt;ul&gt;
		&lt;li&gt;&lt;strong&gt;The paintings&amp;nbsp;depicted gods and goddesses, war scenes, and various activities of elephants and &amp;#39;Radha Krishna&amp;#39;.&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;Chitra Mahal also has&amp;nbsp; &amp;quot;Chitra Shala&amp;quot; which was built by the orders of Maharaja Umaid Singh.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;strong&gt;राव छत्रसाल&lt;/strong&gt;&lt;/u&gt;&amp;nbsp;&lt;span style=&quot;&quot;&gt;हैI&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;राव राजा छत्तर साल&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;वह बूंदी साम्राज्य का एक प्रमुख शासक था।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;उन्होंने केशोरायपाटन में केशवराव का मंदिर और बूंदी में छत्र महल भी बनवाया था।&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;शाहजहाँ द्वारा उन्हें मुगल सेना का अभिन्न अंग माना जाता था।&lt;/li&gt;
		&lt;li&gt;वह 1658 में सामुगढ़ की लड़ाई में अपने हाड़ा राजपूत सैनिकों के प्रमुख के रूप में लड़ते हुए शहीद हो गए थे।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;पुराने दिनों में, 18वीं शताब्दी के दौरान, बूंदी शहर लघु चित्रकला कलाकारों का घर और गढ़ था, और स्थानीय राजाओं ने लघु चित्रों को बहुत प्रोत्साहित किया था।
	&lt;ul&gt;
		&lt;li&gt;&lt;strong&gt;चित्रों में देवी-देवताओं, युद्ध के दृश्यों और हाथियों और &amp;#39;राधा कृष्ण&amp;#39; की विभिन्न गतिविधियों को दर्शाया गया है।&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;चित्रा महल में &amp;quot;चित्रशाला&amp;quot; भी है जिसे महाराजा उम्मेद सिंह के आदेश से बनवाया गया था।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p style=&quot;&quot;&gt;The correct answer is option&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;u&gt;Kumbhalgarh fort&lt;/u&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Kumbhalgarh Fort&lt;/span&gt;&amp;nbsp;is a&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Mewar fort&amp;nbsp;&lt;/span&gt;in the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Rajsamand district of Rajasthan.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;It was built during the course of the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;15th century by Rana Kumbha.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;It was declared a UNESCO World Heritage Site under the group Hill Forts of Rajasthan.&lt;/li&gt;
	&lt;li&gt;There are over&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;360 temples within the fort, 300 ancient Jain and the rest Hindu.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Prithviraj Sisodia&amp;#39;s 12 khambo ki chatri&amp;nbsp;&lt;/span&gt;is also situated in Kumbhalgarh fort.&lt;/li&gt;
&lt;/ul&gt;

