&lt;p style=&quot;&quot;&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Sarangi.&lt;/span&gt;&lt;/u&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;u style=&quot;&quot;&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/span&gt;&lt;/u&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;Masters&amp;nbsp;from an primary&amp;nbsp;generation of sarangi players comprise&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Hanuman Prasad Mishra, Sagiruddin Khan, Shakoor Khan, Mamman Khan, Abdul Lateef Khan and Bundu Khan.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;A&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;sarangi is a bowed stringed instrument&lt;/span&gt;&amp;nbsp;with a skin-covered resonator.&amp;nbsp;&lt;/li&gt;
	&lt;li&gt;The classic&amp;nbsp;sarangi is produce&amp;nbsp;by hand, normally&amp;nbsp;from a&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;single block of wood.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;The&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;four playing strings on this instrument&lt;/span&gt;&amp;nbsp;are build&amp;nbsp;of&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;goat gut,&lt;/span&gt;&amp;nbsp;and the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;seventeen sympathetic strings are build&amp;nbsp;of steel.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;vertical-align: middle; &quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;The&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;Rudra veena&lt;/span&gt;&amp;nbsp;is a big&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;plucked string instrument&lt;/span&gt;&amp;nbsp;used in Hindustani classical music, mainly&amp;nbsp;dhrupad.&amp;nbsp;​&amp;nbsp;&lt;/li&gt;
	&lt;li&gt;The Indian&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;santoor instrument&lt;/span&gt;&amp;nbsp;is a trapezoid-formed&amp;nbsp;hammered dulcimer, and a variant&amp;nbsp;of the&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;Iranian santur.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Jal tarang&lt;/span&gt;&amp;nbsp;is a melodic percussion instrument which is&amp;nbsp;drive&amp;nbsp;from the Indian subcontinent.&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;सारंगी&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;सारंगी वादकों की एक प्राथमिक पीढ़ी के उस्तादों में &lt;strong&gt;हनुमान प्रसाद मिश्रा, सगीरुद्दीन खान, शकूर खान, मम्मन खान, अब्दुल लतीफ खान और बुंदू खान &lt;/strong&gt;शामिल हैं।&lt;/li&gt;
	&lt;li&gt;एक &lt;strong&gt;सारंगी एक झुका हुआ तार वाला वाद्य यंत्र&lt;/strong&gt; &lt;strong&gt;है&lt;/strong&gt; जिसमें त्वचा से ढका गुंजयमान यंत्र होता है।&lt;/li&gt;
	&lt;li&gt;क्लासिक&amp;nbsp;सारंगी को हाथ से बनाने के लिए आमतौर पर &lt;strong&gt;लकड़ी के&lt;/strong&gt; &lt;strong&gt;एक ब्लॉक&lt;/strong&gt; का इस्तेमाल किया जाता है।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;इस &lt;/strong&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;वाद्य&amp;nbsp;&lt;/span&gt;&lt;strong&gt;यंत्र पर बजने वाले चार तार बकरी की आंत&lt;/strong&gt; से बने होते हैं, और &lt;strong&gt;सत्रह अनुकंपी तार स्टील के बने होते हैं।&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;रुद्र वीणा &lt;/strong&gt;हिंदुस्तानी शास्त्रीय संगीत, मुख्य रूप से ध्रुपद में इस्तेमाल किया जाने वाला एक बड़ा&lt;strong&gt; प्लक्ड स्ट्रिंग वाद्य यंत्र&lt;/strong&gt; है।&lt;/li&gt;
	&lt;li&gt;भारतीय &lt;strong&gt;संतूर वाद्य यंत्र &lt;/strong&gt;एक ट्रेपे&lt;span style=&quot;&quot;&gt;जॉ&lt;/span&gt;इड-निर्मित हथौड़े वाला डलसीमर है, और&lt;strong&gt; ईरानी संतूर&lt;/strong&gt; का एक प्रकार है।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;जल तरंग &lt;/strong&gt;एक मधुर तबला वाद्य यंत्र है जो भारतीय उपमहाद्वीप से प्रेरित है।&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p style=&quot;&quot;&gt;The correct answer is&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;u&gt;&lt;strong&gt;NH 548&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;u&gt;NH118,&lt;/u&gt;&lt;/span&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;as well as the NH 548,&lt;/span&gt;&amp;nbsp;is the shortest National highway of India.

	&lt;ul&gt;
		&lt;li&gt;NH 118 connects the towns of Asanbani and Jamshedpur in the state of Jharkhand, running for a distance of&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;only about 5 km&lt;/span&gt;.&lt;/li&gt;
		&lt;li&gt;The NH 548 traverses the state of Maharashtra for about 5 km in length.&lt;/li&gt;
		&lt;li&gt;This new system of naming indicates the direction of National Highways whether it is&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;East-West (odd numbers) or North-South (even numbers)&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;It also indicates the geographical region where it is located,&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;increasing from east to west and from north to south.&lt;/span&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;NH 44&amp;nbsp;&lt;/span&gt;-&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;3,745 km (Old NH 7)&amp;nbsp;&lt;/span&gt;-&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;&lt;/span&gt;It is the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;longest National Highway&lt;/span&gt;&amp;nbsp;in India

	&lt;ul&gt;
		&lt;li&gt;It starts from Srinagar and terminates in Kanyakumari.&lt;/li&gt;
		&lt;li&gt;A major stretch of NH 44 is part of the&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;North-South Corridor and Golden Quadrilateral&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;Golden Quadrilateral, connects several important Indian cities from Srinagar to Kanyakumari.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर&lt;strong&gt; &lt;u&gt;NH 548&lt;/u&gt;&lt;/strong&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;NH118,&lt;/strong&gt;&lt;/u&gt; &lt;strong&gt;साथ ही NH 548, &lt;/strong&gt;भारत का सबसे छोटा राष्ट्रीय राजमार्ग है।

	&lt;ul&gt;
		&lt;li&gt;NH 118 झारखंड राज्य के असनबनी और जमशेदपुर शहरों को जोड़ता है, जिसकी&amp;nbsp;दूरी&amp;nbsp;&lt;strong&gt;केवल लगभग 5 किमी&lt;/strong&gt;&amp;nbsp;है।&lt;/li&gt;
		&lt;li&gt;NH 548 महाराष्ट्र राज्य में लगभग 5 किमी की लंबाई में&amp;nbsp;है।&lt;/li&gt;
		&lt;li&gt;नामकरण की यह नई प्रणाली राष्ट्रीय राजमार्गों की दिशा को इंगित करती है चाहे वह &lt;strong&gt;पूर्व-पश्चिम (विषम संख्या) या उत्तर-दक्षिण (सम संख्या)&lt;/strong&gt; हो।&lt;/li&gt;
		&lt;li&gt;यह भौगोलिक क्षेत्र को भी इंगित करता है जहां यह स्थित है, &lt;strong&gt;पूर्व से पश्चिम तक और उत्तर से दक्षिण तक बढ़ रहा है।&lt;/strong&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;NH 44 - 3,745 किमी (पुराना NH 7) &lt;/strong&gt;- यह भारत का &lt;strong&gt;सबसे लंबा राष्ट्रीय राजमार्ग&lt;/strong&gt; है।

	&lt;ul&gt;
		&lt;li&gt;यह श्रीनगर से शुरू होती है, और कन्याकुमारी में समाप्त होती है।&lt;/li&gt;
		&lt;li&gt;NH 44 का एक बड़ा हिस्सा&lt;strong&gt; उत्तर-दक्षिण गलियारा&amp;nbsp;और स्वर्णिम चतुर्भुज &lt;/strong&gt;का हिस्सा है।&lt;/li&gt;
		&lt;li&gt;स्वर्णिम चतुर्भुज, श्रीनगर से कन्याकुमारी तक कई महत्वपूर्ण भारतीय शहरों को जोड़ता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p style=&quot;&quot;&gt;The correct answer is the &amp;nbsp;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Output method&lt;/span&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;In India, agriculture income is calculated by the Output method&lt;/span&gt;&lt;/u&gt;.&lt;/li&gt;
	&lt;li&gt;The Output Method is the most direct method of&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;estimating a country&amp;#39;s national output or income&lt;/span&gt;.&lt;/li&gt;
	&lt;li&gt;The output method for agriculture income&amp;nbsp;includes&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;income from farming&lt;/span&gt;,&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;income from farming land&lt;/span&gt;,&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;building structures, farmhouses, and types of equipment&lt;/span&gt;.&lt;/li&gt;
	&lt;li&gt;The&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;agricultural income&lt;/span&gt;&amp;nbsp;is&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;not taxable&lt;/span&gt;&amp;nbsp;because&amp;nbsp;it is not taken as a part of a&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;person&amp;rsquo;s total income&lt;/span&gt;.&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;The expenditure method helps in the calculation of&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;gross domestic product (GDP)&lt;/span&gt;&amp;nbsp;which combines&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;consumption, investment, government spending, and net exports.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;The commodity flow method&lt;/span&gt;&amp;nbsp;provides a systematic and consistent framework for the estimation of GDP by&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;final expenditures&lt;/span&gt;.&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;निर्गत विधि&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;भारत में, कृषि आय की गणना निर्गत&lt;/strong&gt;&lt;/u&gt;&lt;u&gt;&lt;strong&gt; विधि द्वारा की जाती है।&lt;/strong&gt;&lt;/u&gt;&lt;/li&gt;
	&lt;li&gt;निर्गत विधि &lt;strong&gt;किसी देश के राष्ट्रीय निर्गत या आय का अनुमान लगाने&lt;/strong&gt; का सबसे सीधा तरीका है।&lt;/li&gt;
	&lt;li&gt;कृषि आय के लिए निर्गत विधि में &lt;strong&gt;खेती से आय, कृषि भूमि से आय, भवन संरचनाओं, फार्महाउस और उपकरणों के प्रकार&lt;/strong&gt; शामिल हैं।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;कृषि आय कर योग्य नहीं&lt;/strong&gt; है क्योंकि इसे किसी &lt;strong&gt;व्यक्ति की कुल आय&lt;/strong&gt; के हिस्से के रूप में नहीं लिया जाता है।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;व्यय विधि,&amp;nbsp;&lt;strong&gt;सकल घरेलू उत्पाद (GDP) &lt;/strong&gt;की गणना में मदद करती है जो &lt;strong&gt;खपत, निवेश, सरकारी खर्च और शुद्ध निर्यात &lt;/strong&gt;को जोड़ती है।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;वस्तु प्रवाह विधि&lt;/strong&gt; &lt;strong&gt;अंतिम व्यय&lt;/strong&gt; द्वारा सकल घरेलू उत्पाद के अनुमान के लिए एक व्यवस्थित और सुसंगत रूपरेखा प्रदान करती है।&lt;/li&gt;
&lt;/ul&gt;

