hn.value:
&lt;p&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;strong&gt;शहरी सड़कें&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;कार्यक्रम &lt;strong&gt;का&lt;/strong&gt; &lt;strong&gt;उद्देश्य गरीबी उन्मूलन, ग्रामीण क्षेत्रों में रोजगार सृजन, आवास, शिक्षा, परिवार कल्याण और स्वास्थ्य, पर्यावरण की सुरक्षा&lt;/strong&gt; और विशेष रूप से ग्रामीण क्षेत्रों में जीवन की गुणवत्ता को प्रभावित करने वाली कई अन्य योजनाओं&lt;strong&gt; से&lt;/strong&gt; &lt;strong&gt;संबंधित योजनाओं को गति प्रदान करना है।&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;इसलिए शहरी सड़कें बीस सूत्री कार्यक्रम 2006 का हिस्सा नहीं हैं।&lt;/strong&gt;&lt;/u&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;बीस सूत्री कार्यक्रम 2006:&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;बीस&amp;nbsp;सूत्री&amp;nbsp;कार्यक्रम&amp;nbsp;पहली बार 1975 में शुरू&amp;nbsp;किया गया था और 1982, 1986 और फिर 2006 में पुनर्गठित किया गया था।&lt;/li&gt;
		&lt;li&gt;पुनर्गठित कार्यक्रम, जिसे बीस सूत्री कार्यक्रम (TPP) &lt;span style=&quot;&quot;&gt;&amp;ndash;&lt;/span&gt; 2006 के रूप में जाना जाता है, यह&amp;nbsp;1 अप्रैल 2007 से प्रभावी हो गया&lt;span style=&quot;&quot;&gt;&amp;nbsp;था।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;बीस सूत्रीय कार्यक्रम की राज्य स्तरीय अनुश्रवण समिति की एक वर्ष में दो बैठकें&amp;nbsp;हैं।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;कार्यक्रम का उद्देश्य गरीबी उन्मूलन, ग्रामीण क्षेत्रों में रोजगार सृजन, आवास, शिक्षा, परिवार कल्याण और स्वास्थ्य, पर्यावरण की सुरक्षा &lt;/strong&gt;और विशेष रूप से ग्रामीण क्षेत्रों में जीवन की गुणवत्ता को प्रभावित करने वाली कई अन्य योजनाओं&lt;strong&gt; से संबंधित योजनाओं को गति प्रदान करना है।&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;बीस सूत्रीय कार्यक्रम-2006 में 65 निगरानी योग्य मदें शामिल हैं, जिनमें से 15 रैंक योग्य मदों की निगरानी राज्य स्तर पर की जा रही है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

