&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;शिव चरण माथुर&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;वह 1981 से 1985 तक और फिर 1988 से 1989 तक &lt;strong&gt;राजस्थान के मुख्यमंत्री&lt;/strong&gt; रहे थे।&lt;/li&gt;
		&lt;li&gt;वह 2008 से 2009 तक असम के राज्यपाल भी रहे&lt;span style=&quot;&quot;&gt;&amp;nbsp;थे।&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;टीकाराम पालीवाल&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;उन्होंने 3 मार्च 1952 से 31 अक्टूबर 1952 तक &lt;strong&gt;राजस्थान के मुख्यमंत्री&lt;/strong&gt; के रूप में कार्य किया था।&lt;/li&gt;
		&lt;li&gt;1962 में, वह हिंडौन लोकसभा क्षेत्र से एक स्वतंत्र उम्मीदवार के रूप में चुने गए थे।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;सचिन पायलट&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;उन्होंने 17 दिसंबर 2018 से 14 जुलाई 2020 के बीच &lt;strong&gt;राजस्थान के 5वें उपमुख्यमंत्री&lt;/strong&gt; के रूप में कार्य किया&lt;span style=&quot;&quot;&gt;&amp;nbsp;था।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;उन्होंने कॉर्पोरेट मामलों के MoS (स्वतंत्र प्रभार) और MoS संचार और IT, भारत सरकार के रूप में भी कार्य किया&lt;span style=&quot;&quot;&gt;&amp;nbsp;था।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;2014 में, उन्हें राजस्थान प्रदेश कांग्रेस कमेटी का अध्यक्ष नियुक्त किया गया&lt;span style=&quot;&quot;&gt;&amp;nbsp;था।&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;घनश्याम तिवारी&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;उन्होंने 2013 और 2018 के बीच राजस्थान में स्थित सांगानेर निर्वाचन क्षेत्र के विधायक के रूप में कार्य किया&lt;span style=&quot;&quot;&gt;&amp;nbsp;था।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;उन्होंने भारतीय जनता पार्टी की स्थापना में महत्वपूर्ण भूमिका निभाई थी।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;हीरालाल देवपुरा&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;वह 23 फरवरी 1985 से 10 मार्च 1985 तक भारत में राजस्थान राज्य के मुख्यमंत्री थे।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;कमला बेनीवाल&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;उन्होंने गुजरात, त्रिपुरा और मिजोरम के राज्यपाल के रूप में कार्य किया है।&lt;/li&gt;
		&lt;li&gt;उन्होंने 2003 में &lt;strong&gt;राजस्थान के चौथे उप मुख्यमंत्री&lt;/strong&gt; के रूप में कार्य किया&lt;span style=&quot;&quot;&gt;&amp;nbsp;था।&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

