hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;लक्ष्य सेन&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;भारत के लक्ष्य सेन ने 13 मार्च 2022 को जर्मन ओपन 2022 में रजत पदक जीता है।&lt;/strong&gt;&lt;/u&gt;

	&lt;ul&gt;
		&lt;li&gt;वह पुरुष एकल के फाइनल में थाईलैंड के कुनलावुत विटिडसर्न से हार गए थे।&lt;/li&gt;
		&lt;li&gt;फाइनल में उन्हें 18-21, 15-21 से हार का सामना करना पड़ा था।&lt;/li&gt;
		&lt;li&gt;लक्ष्य सेन बैडमिंटन वर्ल्ड फेडरेशन BWF सुपरसीरीज 300 जर्मन ओपन 2022 में रजत पदक जीतने वाले प्रथम&amp;nbsp;भारतीय बन गए हैं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;Jalore&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;Bijoliya inscription found the names of ancient times like &lt;strong&gt;Jabalipur&lt;/strong&gt;, Shakmbhari, Srimal.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;An inscription of&amp;nbsp;Vikram Samvat 1226 Falgun Krishna Tritiya&amp;nbsp;(5 February 1170) is inscribed on a rock near the northern wall of the ancient Parshvanath temple located in Bijolia.&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;The historical place &amp;#39;Jabalipur&amp;#39; is identified in modern times as Jalore&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;It is believed that &lt;strong&gt;Jalore (Jabalipur) &lt;/strong&gt;was the Tapobhoomi of Maharishi Jabali in 22 ancient times.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;Kanhaddev, the famous ruler of Jalore had fought with Alauddin Khilji for a long time.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;The&lt;strong&gt; Suvarnagiri fort of Jalore &lt;/strong&gt;was built by the Parmar Rajputs. &lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;The fort has Vaishnava and Jain temples and the tomb of the Sufi saint Malikshah.&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;जालोर&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;बिजौलिया शिलालेख में &lt;strong&gt;जाबालिपुर&lt;/strong&gt;, शाकंभरी, श्रीमल जैसे प्राचीन काल के नाम मिले हैं।&lt;/li&gt;
	&lt;li&gt;बिजौलिया स्थित प्राचीन पार्श्वनाथ मंदिर की उत्तरी दीवार के पास एक शिला पर विक्रम संवत 1226 फाल्गुन कृष्ण तृतीया (5 फरवरी 1170) का एक शिलालेख अंकित है।&lt;/li&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;ऐतिहासिक स्थान &amp;#39;जबालिपुर&amp;#39; की पहचान आधुनिक काल के&amp;nbsp;जालोर के रूप में होती है।&lt;/strong&gt;&lt;/u&gt;
	&lt;ul&gt;
		&lt;li&gt;ऐसा माना जाता है कि&amp;nbsp;प्राचीन काल में &lt;strong&gt;जालोर (जबालिपुर)&lt;/strong&gt; महर्षि जबालि की तपोभूमि थी।&lt;/li&gt;
		&lt;li&gt;जालोर के प्रसिद्ध शासक कान्हड़देव ने अलाउद्दीन खिलजी से लम्बे&amp;nbsp;समय तक युद्ध किया था।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;जालोर के सुवर्णगिरि किले&lt;/strong&gt; का निर्माण परमार राजपूतों ने करवाया था।&lt;/li&gt;
		&lt;li&gt;किले में वैष्णव और जैन मंदिर और सूफी संत मलिकशाह की कब्र है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is &lt;u&gt;&lt;strong&gt;Kerela&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Kerala ranks first in the production of rubber&lt;/strong&gt;&lt;/u&gt;.&amp;nbsp;&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;The rest is produced in Tamil Nadu and the North East states.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;Rubber is cultivated on 5.45 lakh hectares in Kerala.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;Malanadu, Idanadu, Kottayam and Palakkad&lt;/strong&gt; are rubber-producing centers.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;The first commercial rubber plantation in India was established in &lt;strong&gt;1902 at Thattekadu in Kerala&lt;/strong&gt;. But extensive cultivation of rubber started in Kerala after 1940.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;India is the fourth largest producer in the world after Thailand, Indonesia and China.&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;केरल&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;रबर&amp;nbsp;के उत्पादन में केरल का प्रथम स्थान है।&lt;/strong&gt;&lt;/u&gt;

	&lt;ul&gt;
		&lt;li&gt;बाकी रबर&amp;nbsp;तमिलनाडु और उत्तर पूर्व राज्यों में उत्पादित होता है।&lt;/li&gt;
		&lt;li&gt;केरल में 5.45 लाख हेक्टेयर में रबर&amp;nbsp;की खेती होती है।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;मलानाडु, इदनाडु, कोट्टायम और पलक्कड़&lt;/strong&gt; रबर&amp;nbsp;उत्पादक केंद्र हैं।&lt;/li&gt;
		&lt;li&gt;भारत में पहला व्यावसायिक रबर&amp;nbsp;बागान &lt;strong&gt;1902 में केरल के थट्टेकाडु&lt;/strong&gt; में स्थापित किया गया था। लेकिन 1940 के बाद केरल में रबर की व्यापक खेती शुरू हुई।&lt;/li&gt;
		&lt;li&gt;थाईलैंड, इंडोनेशिया और चीन के बाद भारत विश्व&amp;nbsp;में चौथा सबसे बड़ा रबर उत्पादक देश है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Rajasthan is divided into 14 agro-climatic zones&lt;/strong&gt;&lt;/u&gt; is NOT correct.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;The regions have been classified on the basis of agro-climatic zones by the Indian Council of Agricultural Analysis (ICAR) on the basis of agro-climatic parameters.
	&lt;ul&gt;
		&lt;li&gt;&lt;u&gt;&lt;strong&gt;Rajasthan is divided into ten agro-climatic zones&lt;/strong&gt;&lt;/u&gt;.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;The Agro-climatic zones of Rajasthan are:&lt;/strong&gt;

	&lt;ol&gt;
		&lt;li&gt;Arid North-Western Sandy Plain&lt;/li&gt;
		&lt;li&gt;Irrigated North Western Plain&lt;/li&gt;
		&lt;li&gt;Hyper Arid Partial Irrigated Zone&lt;/li&gt;
		&lt;li&gt;Transitional Plain of Inland Drainage&lt;/li&gt;
		&lt;li&gt;Alluvial Plain of Luni Basin&lt;/li&gt;
		&lt;li&gt;Semi-Arid Eastern Plain&lt;/li&gt;
		&lt;li&gt;Flood Prone Eastern Plain&lt;/li&gt;
		&lt;li&gt;Sub Humid Southern Plain and Aravallis&lt;/li&gt;
		&lt;li&gt;Humid Southern Plain&lt;/li&gt;
		&lt;li&gt;Humid South Eastern Plain&lt;/li&gt;
	&lt;/ol&gt;
	&lt;/li&gt;
&lt;/ul&gt;

