	&lt;ol&gt;
		&lt;li&gt;शुष्क उत्तर-पश्चिमी रेतीला मैदान&lt;/li&gt;
		&lt;li&gt;सिंचित उत्तर पश्चिमी मैदान&lt;/li&gt;
		&lt;li&gt;अति शुष्क आंशिक सिंचित क्षेत्र&lt;/li&gt;
		&lt;li&gt;अंतर्देशीय अपवाह का संक्रमणकालीन मैदान&lt;/li&gt;
		&lt;li&gt;लूनी बेसिन का जलोढ़ मैदान&lt;/li&gt;
		&lt;li&gt;अर्ध-शुष्क पूर्वी मैदान&lt;/li&gt;
		&lt;li&gt;बाढ़ प्रवण पूर्वी मैदान&lt;/li&gt;
		&lt;li&gt;उप आर्द्र दक्षिणी मैदान और अरावली&lt;/li&gt;
		&lt;li&gt;आर्द्र दक्षिणी मैदान&lt;/li&gt;
		&lt;li&gt;आर्द्र दक्षिण पूर्वी मैदान&lt;/li&gt;
	&lt;/ol&gt;
	&lt;/li&gt;
&lt;/ul&gt;

