&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Chief Minister&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Chief Minister is the Chairman of the State Tourism Advisory Committee in Rajasthan&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;The tourism policy ensures the directions given for the development of tourism. &lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;The head of this committee is&lt;strong&gt; &lt;/strong&gt;&lt;/span&gt;&lt;strong&gt;Bhajan lal&lt;span style=&quot;&quot;&gt;.&lt;/span&gt;&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;The vice-chairman of the committee was made the minister of the tourism department.&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;In &lt;strong&gt;1956&lt;/strong&gt;, the tourism department is working as an independent department for the development of tourism in Rajasthan.&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​Under the control of the Department of Tourism, two Public Sector Undertakings&lt;/span&gt;

		&lt;ul&gt;
			&lt;li&gt;&lt;span style=&quot;&quot;&gt;Rajasthan Tourism Development Corporation Limited and Rajasthan State Hotel Corporation Limited &lt;/span&gt;&lt;/li&gt;
			&lt;li&gt;&lt;span style=&quot;&quot;&gt;an autonomous institute &amp;#39;Rajasthan Institute of Tourism and Travel Management (RITMAN)&amp;#39; are working respectively.&lt;/span&gt;&lt;/li&gt;
		&lt;/ul&gt;
		&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;मुख्यमंत्री&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;राजस्थान में राज्य पर्यटन सलाहकार समिति के अध्यक्ष मुख्यमंत्री होते हैं।&lt;/strong&gt;&lt;/u&gt;&lt;/li&gt;
	&lt;li&gt;पर्यटन नीति पर्यटन के विकास के लिए दिए गए दिशा-निर्देशों को सुनिश्चित करती है।&lt;span style=&quot;&quot;&gt; &lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;इस समिति के अध्यक्ष &lt;strong&gt;भजन लाल&lt;/strong&gt;&amp;nbsp;&amp;nbsp;हैं।&lt;/li&gt;
		&lt;li&gt;समिति के उपाध्यक्ष को पर्यटन विभाग का मंत्री बनाया गया है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;1956&lt;/strong&gt; में पर्यटन विभाग राजस्थान में पर्यटन के विकास के लिए एक स्वतंत्र विभाग के रूप में कार्य कर रहा है।

	&lt;ul&gt;
		&lt;li&gt;​पर्यटन विभाग के नियंत्रण में दो सार्वजनिक क्षेत्र के उपक्रम
		&lt;ul&gt;
			&lt;li&gt;राजस्थान पर्यटन विकास निगम लिमिटेड और राजस्थान स्टेट होटल कॉर्पोरेशन लिमिटेड&lt;/li&gt;
			&lt;li&gt;एक स्वायत्त संस्थान &amp;#39;राजस्थान पर्यटन और यात्रा प्रबंधन संस्थान (RITMAN)&amp;#39; क्रमशः कार्य&amp;nbsp;कर रहे हैं।&lt;/li&gt;
		&lt;/ul&gt;
		&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Phad Painting&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;Shree Lal Joshi&amp;nbsp;&lt;/strong&gt;is a world-renowned artist from Bhilwara, Rajasthan.

	&lt;ul&gt;
		&lt;li&gt;&lt;u&gt;&lt;strong&gt;He hails from a family of&amp;nbsp;Phad artists&amp;nbsp;who were once the sole keepers of the art of&amp;nbsp;Phad painting&lt;/strong&gt;&lt;/u&gt;.&lt;/li&gt;
		&lt;li&gt;Phad painting is an art linked to the lively tradition of storytelling, music, and performance.&lt;/li&gt;
		&lt;li&gt;Shree Lal Joshi is credited with reviving this colorful art.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;img 620f86258a4d509fed4b6e58=&quot;&quot; alt=&quot;620f86258a4d509fed4b6e58 16468214177721&quot; src=&quot;https://storage.googleapis.com/tb-img/production/22/03/620f86258a4d509fed4b6e58_16468214177721.png&quot; /&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;Shree Lal Joshi&amp;nbsp;guided both his sons Kalyan Joshi and Gopal Joshi in adding new dimensions to this art.&lt;/li&gt;
	&lt;li&gt;Kalyan Joshi is a leading&amp;nbsp;Phad artist who received the&amp;nbsp;National Award in 2012.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;strong&gt;फड़ चित्रण&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;श्रीलाल जोशी&lt;/strong&gt; राजस्थान के भीलवाड़ा के एक विश्व प्रसिद्ध कलाकार हैं।

	&lt;ul&gt;
		&lt;li&gt;&lt;u&gt;&lt;strong&gt;वह फड कलाकारों के परिवार से हैं, जो कभी फड़ चित्रकला की कला के एकमात्र रखवाले थे।&lt;/strong&gt;&lt;/u&gt;&lt;/li&gt;
		&lt;li&gt;फड़ चित्रकला कहानी कहने, संगीत और प्रदर्शन की जीवंत परंपरा से जुड़ी एक कला है।&lt;/li&gt;
		&lt;li&gt;इस रंगीन कला को पुनर्जीवित करने का श्रेय श्रीलाल जोशी को जाता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;img 620f86258a4d509fed4b6e58=&quot;&quot; alt=&quot;620f86258a4d509fed4b6e58 16468214177721&quot; src=&quot;https://storage.googleapis.com/tb-img/production/22/03/620f86258a4d509fed4b6e58_16468214177721.png&quot; /&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;श्रीलाल जोशी ने अपने दोनों पुत्रों कल्याण जोशी और गोपाल जोशी को इस कला में नए आयाम जोड़ने के लिए मार्गदर्शन किया।&lt;/li&gt;
	&lt;li&gt;कल्याण जोशी 2012 में राष्ट्रीय पुरस्कार प्राप्त करने वाले एक प्रमुख फड़ कलाकार हैं।&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;Mumbai and Hyderabad&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Mumbai&lt;/strong&gt;&lt;/u&gt; has been recognized as the &amp;quot;&lt;u&gt;&lt;strong&gt;2021 Tree City of the World&lt;/strong&gt;&lt;/u&gt;&amp;quot; by the Food and Agriculture Organisation of the United Nations (UN) jointly with Arbor Day Foundation.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;It is the second city in India to receive this distinction, after &lt;u&gt;&lt;strong&gt;Hyderabad&lt;/strong&gt;&lt;/u&gt;, which bagged the title two years in a row.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;The&lt;strong&gt; United Nations&amp;rsquo; &amp;lsquo;Tree City of the World&lt;/strong&gt;&amp;rsquo; program provides direction, assistance, and worldwide recognition for communities&amp;rsquo; dedication to its urban forest, and provides a framework for healthy, sustainable urban forestry.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;
	&lt;div&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Food and Agriculture Organisation&lt;/span&gt;&lt;/strong&gt;&lt;/div&gt;

	&lt;ul&gt;
		&lt;li&gt;
		&lt;div&gt;&lt;span style=&quot;&quot;&gt;Headquarters: Rome, Italy&lt;/span&gt;&lt;/div&gt;
		&lt;/li&gt;
		&lt;li&gt;
		&lt;div&gt;&lt;span style=&quot;&quot;&gt;Founded: 16 October 1945.&lt;/span&gt;&lt;/div&gt;
		&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;मुंबई और हैदराबाद&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;संयुक्त राष्ट्र (UN) के खाद्य और कृषि संगठन द्वारा आर्बर डे फाउंडेशन के साथ संयुक्त रूप से &lt;u&gt;&lt;strong&gt;मुंबई&lt;/strong&gt;&lt;/u&gt; को &lt;strong&gt;&amp;quot;&lt;u&gt;2021 ट्री सिटी ऑफ द वर्ल्ड&lt;/u&gt;&amp;quot;&lt;/strong&gt; के रूप में मान्यता दी गई है।&lt;/li&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;हैदराबाद&lt;/strong&gt;&lt;/u&gt; के बाद यह गौरव प्राप्त करने वाला यह भारत का दूसरा शहर है, जिसने लगातार दो वर्षों में यह खिताब जीता है।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;संयुक्त राष्ट्र&lt;/strong&gt; का &lt;strong&gt;&amp;#39;ट्री सिटी ऑफ द वर्ल्ड&amp;#39; &lt;/strong&gt;कार्यक्रम अपने शहरी वन के लिए समुदायों के समर्पण के लिए दिशा, सहायता और विश्वव्यापी मान्यता प्रदान करता है, और स्वस्थ, सतत&amp;nbsp;शहरी वानिकी के लिए एक ढांचा प्रदान करता है।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;खाद्य और कृषि संगठन&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;
		&lt;div&gt;मुख्यालय: रोम, इटली&lt;/div&gt;
		&lt;/li&gt;
		&lt;li&gt;
		&lt;div&gt;स्थापना: 16 अक्टूबर 1945&lt;/div&gt;
		&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;103&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;103rd&amp;nbsp;Amendment Act, 2019&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;u&gt;&lt;strong&gt;It&amp;nbsp;introduces a 10% reservation for Economically Weaker Sections (EWS)&lt;/strong&gt;&lt;/u&gt; of society for admission to Central Government-run educational institutions and private educational institutions (except for minority educational institutions), and for employment in Central Government jobs.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;104th&amp;nbsp;Amendment Act, 2020&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;It&amp;nbsp;extends reservation for ten years for Scheduled Caste and Scheduled Tribes to Lok Sabha and State Assemblies.&amp;nbsp;&lt;/li&gt;
		&lt;li&gt;It also&amp;nbsp;removed the reserved seats for the Anglo-Indian community in the Lok Sabha and state assemblies.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;105th&amp;nbsp;Amendment Act, 2021&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;It restors the power of State Governments to identify and specify Socially and Economically Backward Classes (SEBCs).&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;102nd&amp;nbsp;Amendment Act, 2018&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;It&amp;nbsp;inserted articles 338B, which deals with the structure, duties and powers of the National Commission for Backward Classes, and 342A which deals with the powers of the president to notify a particular caste as an SEBC and the power of Parliament to change the list.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;
	&lt;div&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;101st Constitution Amendment Act, 2016&lt;/strong&gt;&amp;nbsp; introduced the Goods and Services Tax.&lt;/span&gt;&lt;/div&gt;

	&lt;ul&gt;
		&lt;li&gt;
		&lt;div&gt;&lt;span style=&quot;&quot;&gt;GST Bill was first introduced in 2014 as The Constitution (122nd Amendment) Bill.&lt;/span&gt;&lt;/div&gt;
		&lt;/li&gt;
		&lt;li&gt;
		&lt;div&gt;&lt;span style=&quot;&quot;&gt;Goods and Services Tax is a widespread indirect tax on the manufacture, sale, and consumption of goods and services throughout India.&lt;/span&gt;&lt;/div&gt;
		&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;103&lt;/strong&gt;&lt;/u&gt;&amp;nbsp;है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;103वां संशोधन अधिनियम, 2019&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;यह समाज के &lt;strong&gt;आर्थिक रूप से कमजोर वर्गों (EWS)&lt;/strong&gt; के लिए केंद्र सरकार द्वारा संचालित शैक्षणिक संस्थानों और निजी शैक्षणिक संस्थानों (अल्पसंख्यक शैक्षणिक संस्थानों को छोड़कर) में प्रवेश के लिए और केंद्र सरकार की नौकरियों में रोजगार &lt;strong&gt;के लिए 10% आरक्षण&lt;/strong&gt; पेश करता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;104वां संशोधन अधिनियम, 2020&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;यह लोकसभा और राज्य विधानसभाओं के लिए अनुसूचित जाति और अनुसूचित जनजाति के लिए दस वर्ष&amp;nbsp;के लिए आरक्षण का विस्तार करता है।&lt;/li&gt;
		&lt;li&gt;इसने लोकसभा और राज्य विधानसभाओं में आंग्ल-भारतीय समुदाय के लिए आरक्षित सीटों को भी हटा दिया।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;105वां संशोधन अधिनियम&lt;/strong&gt;&lt;strong&gt;, 2021&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;यह सामाजिक और आर्थिक रूप से पिछड़े वर्गों (SEBC) की पहचान करने और निर्दिष्ट करने के लिए राज्य सरकारों की शक्ति को बहाल करता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;102वां संशोधन अधिनियम, 2018&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;इसने अनुच्छेद 338B को सम्मिलित किया, जो पिछड़े वर्गों के लिए राष्ट्रीय आयोग की संरचना, कर्तव्यों और शक्तियों से संबंधित है, और 342A जो किसी विशेष जाति को SEBC के रूप में अधिसूचित करने की राष्ट्रपति की शक्तियों और सूची को बदलने के लिए संसद की शक्ति से संबंधित है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;
	&lt;div&gt;&lt;strong&gt;101वें संविधान संशोधन अधिनियम, 2016&lt;/strong&gt; ने वस्तु&amp;nbsp;और सेवा कर पेश किया था।&lt;/div&gt;

	&lt;ul&gt;
		&lt;li&gt;
		&lt;div&gt;माल और सेवा कर (GST)&amp;nbsp;विधेयक पहली बार 2014 में संविधान (122वें संशोधन) विधेयक के रूप में पेश किया गया था।&lt;/div&gt;
		&lt;/li&gt;
		&lt;li&gt;
		&lt;div&gt;माल&amp;nbsp;और सेवा कर पूरे भारत में वस्तुओं और सेवाओं के निर्माण, बिक्री और उपभोग&amp;nbsp;पर एक व्यापक अप्रत्यक्ष कर है।&lt;/div&gt;
		&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;Gaurishankar Hirachand Ojha&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;Gauri Shankar Hirachand Ojha&amp;nbsp;is the author of&amp;nbsp;&amp;#39; Bharatiya Prachin Lipimala&lt;/strong&gt;&lt;/u&gt;&amp;#39;.

	&lt;ul&gt;
		&lt;li&gt;The book is the&amp;nbsp;first book devoted to the paleography of India.&lt;/li&gt;
		&lt;li&gt;Gauri Shankar Hirachand Ojha&amp;nbsp;was a historian from Rajasthan.&lt;/li&gt;
		&lt;li&gt;He was awarded the&amp;nbsp;title of Rao Bahadur&amp;nbsp;in 1914.&lt;/li&gt;
		&lt;li&gt;He was honored with&amp;nbsp;Sahitya Vachaspati&amp;nbsp;in 1937.&lt;/li&gt;
		&lt;li&gt;He&amp;nbsp;regarded Kaviraj Shyamaldas as his guru and&amp;nbsp;worked under him as assistant secretary of the historical department, Udaipur.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;Bishweshwar Nath Reu&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;He started his career as an assistant to Gaurishankar Hirachand Ojha.&lt;/li&gt;
		&lt;li&gt;He&amp;nbsp;published Bharat ke Prachin Rajvansh with the three volumes being released in 1920, 1921, and 1935 respectively.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Ramkarna Asopa&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;​He&amp;nbsp;had helped Tasitori in compiling Rajasthani texts.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Muni Jinvijay&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;He&amp;nbsp;was a scholar of orientalism, archaeology, Indology, and Jainism.&lt;/li&gt;
		&lt;li&gt;He learned Sanskrit and Prakrit literature under Kantivijay, a Jain ascetic.&lt;/li&gt;
		&lt;li&gt;He was awarded the Padma Shri in 1961 for his contributions in the fields of literature and education.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर&lt;u&gt;&lt;strong&gt; गौरीशंकर हीराचंद ओझा&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;&amp;#39;भारतीय प्राचीन लिपिमाला&amp;#39; के लेखक गौरी शंकर हीराचंद ओझा हैं।&lt;/strong&gt;&lt;/u&gt;

	&lt;ul&gt;
		&lt;li&gt;यह पुस्तक भारत के पुरालेख को समर्पित पहली पुस्तक है।&lt;/li&gt;
		&lt;li&gt;गौरी शंकर हीराचंद ओझा राजस्थान के इतिहासकार थे।&lt;/li&gt;
		&lt;li&gt;1914 में उन्हें राव बहादुर की उपाधि से सम्मानित किया गया।&lt;/li&gt;
		&lt;li&gt;उन्हें 1937 में साहित्य वाचस्पति से सम्मानित किया गया था।&lt;/li&gt;
		&lt;li&gt;उन्होंने कविराज श्यामलदास को अपना गुरु माना और उनके अधीन ऐतिहासिक विभाग, उदयपुर के सहायक सचिव के रूप में काम किया।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&amp;nbsp;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;विश्वेश्वरनाथ&lt;/span&gt;&amp;nbsp;रेउ&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;उन्होंने गौरीशंकर हीराचंद ओझा के सहायक के रूप में शुरुआत&amp;nbsp;की।&lt;/li&gt;
		&lt;li&gt;उन्होंने भारत के प्राचीन राजवंश को क्रमशः 1920, 1921 और 1935 में जारी तीन खंडों के साथ प्रकाशित किया।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;रामकर्ण असोपा&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;उन्होंने राजस्थानी ग्रंथों के संकलन में तसितोरी की मदद की थी।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;मुनि जिनविजय&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;वह प्राच्यवाद, पुरातत्व, इंडोलॉजी और जैन धर्म के विद्वान थे।&lt;/li&gt;
		&lt;li&gt;उन्होंने एक जैन तपस्वी कांतिविजय के तहत संस्कृत और प्राकृत साहित्य सीखा।&lt;/li&gt;
		&lt;li&gt;साहित्य और शिक्षा के क्षेत्र में उनके योगदान के लिए उन्हें 1961 में पद्म श्री से सम्मानित किया गया था।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is &lt;u&gt;&lt;strong&gt;Narmada&lt;/strong&gt;&lt;/u&gt;.&amp;nbsp;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;u&gt;Narmada&amp;nbsp;&lt;span style=&quot;&quot;&gt;river flows in Rift&amp;nbsp;&lt;/span&gt;&lt;/u&gt;&lt;/strong&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Valley&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;strong&gt;Narmada&lt;/strong&gt; is the largest west-flowing river in peninsular India.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;Narmada flows westwards &lt;/strong&gt;through a&amp;nbsp;rift valley between the &lt;strong&gt;Vindhyan Range&lt;/strong&gt; on the north and the &lt;strong&gt;Satpura Range&lt;/strong&gt; on the south.&lt;/li&gt;
		&lt;li&gt;It&amp;nbsp;rises from the &lt;strong&gt;Maikala range near Amarkantak in Madhya Pradesh&lt;/strong&gt;.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;Rift Valley&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;A rift valley is a &lt;strong&gt;lowland region&lt;/strong&gt; that forms where&amp;nbsp;Earth&amp;rsquo;s tectonic plates move apart or rift.&lt;/li&gt;
		&lt;li&gt;Rift valleys are found&amp;nbsp;&lt;strong&gt;both on land and at the bottom of the ocean&amp;nbsp;&lt;/strong&gt;and are created by the process of seafloor spreading.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;The&amp;nbsp;Tapti River and Mahi River&lt;/strong&gt;&amp;nbsp;also flow through rift valleys, but between different ranges.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;नर्मदा &lt;/strong&gt;&lt;/u&gt;है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;नर्मदा &lt;/strong&gt;नदी &lt;span style=&quot;&quot;&gt;भ्रंश&lt;/span&gt; घाटी में बहती है।

	&lt;ul&gt;
		&lt;li&gt;&lt;strong&gt;नर्मदा &lt;/strong&gt;प्रायद्वीपीय भारत में पश्चिम की ओर बहने वाली&lt;strong&gt; &lt;/strong&gt;सबसे बड़ी नदी है।&lt;/li&gt;
		&lt;li&gt;नर्मदा उत्तर में&lt;strong&gt; विंध्य श्रेणी&amp;nbsp;&lt;/strong&gt;और दक्षिण में &lt;strong&gt;सतपुड़ा श्रेणी&amp;nbsp;&lt;/strong&gt;के बीच एक भ्रंश घाटी के माध्यम से &lt;strong&gt;पश्चिम की ओर बहती&lt;/strong&gt; है।&lt;/li&gt;
		&lt;li&gt;यह &lt;strong&gt;मध्यप्रदेश में अमरकंटक के निकट मैकाल&amp;nbsp;श्रेणी&lt;/strong&gt; से निकलती है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;भ्रंश घाटी&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;भ्रंश घाटी&lt;/span&gt; एक &lt;strong&gt;निचला क्षेत्र &lt;/strong&gt;है जो पृथ्वी की विवर्तनिक प्लेटों के अलग होने या दरार का निर्माण करता है।&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;भ्रंश&amp;nbsp;&lt;/span&gt;घाटियाँ &lt;strong&gt;भूमि और समुद्र के तल दोनों पर पाई जाती हैं&lt;/strong&gt; और समुद्र तल के फैलने की प्रक्रिया द्वारा बनती&amp;nbsp;हैं।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;ताप्ती नदी और माही नदी&lt;/strong&gt; भी भ्रंश घाटियों से होकर बहती हैं, लेकिन विभिन्न श्रेणियों के बीच।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is &lt;u&gt;&lt;strong&gt;Bhil&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Maize is the staple food of Bhil&amp;nbsp;tribe of Rajasthan&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;Maize&amp;nbsp;is the main cereal in the Banswara district of Rajasthan.
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;The state government is coming up with an ambitious project of Hybrid Maize Seed Production in &lt;strong&gt;Banswara and Dungarpur&lt;/strong&gt;.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;It is a staple food of Rajasthan, especially in the Mewar region where it is fondly consumed during the winter season.&lt;/li&gt;
		&lt;li&gt;It suitably grows in&amp;nbsp;Red-Black soil&amp;nbsp;and requires high temperature and rainfalls.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;Chittorgarh, Bhilwara, Rajsamand, Banswara, Dungarpur district etc.&lt;/strong&gt; are the major producer of Maize.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;भील&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;मक्का राजस्थान की भील जनजाति का मुख्य भोजन है।&lt;/strong&gt;&lt;/u&gt;&lt;/li&gt;
	&lt;li&gt;मक्का राजस्थान के बांसवाड़ा जिले का प्रमुख अनाज है।
	&lt;ul&gt;
		&lt;li&gt;राज्य सरकार &lt;strong&gt;बांसवाड़ा और डूंगरपुर&lt;/strong&gt; में संकर मक्का बीज उत्पादन की महत्वाकांक्षी परियोजना लेकर आ रही है।&lt;/li&gt;
		&lt;li&gt;यह राजस्थान का एक मुख्य भोजन है, विशेष रूप से मेवाड़ क्षेत्र में जहाँ&amp;nbsp;सर्दियों के मौसम में इसका सेवन बड़े चाव से किया जाता है।&lt;/li&gt;
		&lt;li&gt;यह लाल-काली मिट्टी में उपयुक्त रूप से उगता है और इसके लिए उच्च तापमान और वर्षा की आवश्यकता होती है।&lt;/li&gt;
		&lt;li&gt;मक्का के प्रमुख उत्पादक &lt;strong&gt;चित्तौड़गढ़, भीलवाड़ा, राजसमंद, बांसवाड़ा, डूंगरपुर&lt;/strong&gt; जिले आदि हैं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;Sawai Ram Singh II&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;The Rajasthan School of Arts was established in 1857 AD by Maharaja Sawai Ram Singh II&lt;/strong&gt;&lt;/u&gt;, the ruler of the then princely state of Jaipur, under the name of &amp;#39;Madrasa-e-Hunari&amp;#39; (Institute of Arts).&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;span id=&quot;cke_bm_7497S&quot; style=&quot;display: none;&quot;&gt;&amp;nbsp;&lt;/span&gt;In 1886 it was renamed the Maharaja&amp;#39;s School of Arts. &lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;Thereafter, it became famous as Rajasthan Kala Vidyalaya.&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span id=&quot;cke_bm_7497E&quot; style=&quot;display: none;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;Rajasthan&lt;/strong&gt; has many beautiful artistic and cultural traditions&amp;nbsp;which reflect the ancient Indian way of life.

	&lt;ul&gt;
		&lt;li&gt;Rajasthan is also called the &amp;quot;&lt;strong&gt;Land of Kings&lt;/strong&gt;&amp;quot;.&lt;/li&gt;
		&lt;li&gt;The first mention of the word &lt;strong&gt;Rajasthan&lt;/strong&gt; comes from the works of George Thomas and James Tod.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;strong&gt;सवाई राम सिंह द्वितीय&lt;/strong&gt;&lt;/u&gt;&amp;nbsp;है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;राजस्थान स्कूल ऑफ आर्ट्स की स्थापना 1857 ई. में&lt;/strong&gt; जयपुर की तत्कालीन रियासत के शासक &lt;strong&gt;महाराजा सवाई राम सिंह द्वितीय &lt;/strong&gt;ने &amp;#39;मदरसा-ए-हुनारी&amp;#39; (कला संस्थान) के नाम से की थी।

	&lt;ul&gt;
		&lt;li&gt;1886 में इसका नाम बदलकर महाराजा स्कूल ऑफ आर्ट्स कर दिया गया था।&lt;/li&gt;
		&lt;li&gt;तत्पश्चात, यह राजस्थान कला विद्यालय के रूप में प्रसिद्ध हुआ।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span id=&quot;cke_bm_7497E&quot; style=&quot;display: none;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;राजस्थान &lt;/strong&gt;में कई खूबसूरत कलात्मक और सांस्कृतिक परंपराएँ&amp;nbsp;हैं जो प्राचीन भारतीय जीवन शैली को दर्शाती हैं।

	&lt;ul&gt;
		&lt;li&gt;राजस्थान को &lt;strong&gt;&amp;quot;राजाओं की भूमि&amp;quot;&lt;/strong&gt; भी कहा जाता है।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;राजस्थान&lt;/strong&gt; शब्द का सर्वप्रथम उल्लेख जॉर्ज थॉमस और जेम्स टॉड की रचनाओं में मिलता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;Only (iii)&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;
	&lt;div&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;The Monetary Policy Report is issued by the Monetary Policy Committee (MPC) of RBI&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/div&gt;
	&lt;/li&gt;
	&lt;li&gt;
	&lt;div&gt;&lt;strong&gt;Bank Rate&lt;/strong&gt; refers to the&amp;nbsp;official interest rate&amp;nbsp;at which&amp;nbsp;RBI will provide loans to the banking system.&lt;/div&gt;

	&lt;ul&gt;
		&lt;li&gt;
		&lt;div&gt;Bank rate is used as a signal by the RBI&amp;nbsp;to the commercial banks on RBI&amp;#39;s thinking about what the interest rate should be.&lt;/div&gt;
		&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Monetary Tools of RBI:&lt;/strong&gt;&lt;/p&gt;

&lt;table border=&quot;1&quot; cellpadding=&quot;1&quot; cellspacing=&quot;1&quot; style=&quot;width: 350px;&quot;&gt;
	&lt;tbody&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;REPO RATE&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;
			&lt;p&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;Repo&amp;nbsp;denotes Re Purchase Option&amp;nbsp;- the rate by which RBi gives loans to other banks i.e., it is the rate at which banks buy back the securities they keep with RBI at a later period.&lt;/span&gt;&lt;/p&gt;
			&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;REVERSE REPO RATE&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;The rate at which RBI borrows from the bank is known as&amp;nbsp;Reverse Repo Rate.&amp;nbsp;&lt;/span&gt;&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;CRR&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;Cash Reserve Ratio, it corresponds to the percentage of cash each bank has to keep as a cash reserve with RBI.&lt;/span&gt;&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;SLR&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;Statutory Liquidity Ratio&amp;nbsp;or SLR is the minimum percentage of the deposit that a commercial bank has to maintain in the form of Liquid cash/ gold/or other.&lt;/span&gt;&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;OMO&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;Open market operation&amp;nbsp;is a platform where government securities are sold and purchased by RBI.&lt;/span&gt;&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;BANK RATE&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;It is the official interest rate at which RBI provides a&amp;nbsp;loan to the bank&amp;nbsp;and extends&amp;nbsp;long term credit&amp;nbsp;to commercial banks.&lt;/span&gt;&lt;/td&gt;
		&lt;/tr&gt;
	&lt;/tbody&gt;
&lt;/table&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;केवल (iii)&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;
	&lt;div&gt;&lt;strong&gt;&lt;u&gt;मौद्रिक नीति रिपोर्ट भारतीय रिजर्व बैंक&lt;/u&gt;&lt;/strong&gt;&lt;strong&gt;&lt;u&gt; की मौद्रिक नीति समिति (MPC) द्वारा जारी की जाती है।&lt;/u&gt;&lt;/strong&gt;&lt;/div&gt;
	&lt;/li&gt;
	&lt;li&gt;
	&lt;div&gt;&lt;strong&gt;बैंक दर&lt;/strong&gt; आधिकारिक ब्याज दर को संदर्भित करता है जिस पर भारतीय रिजर्व बैंक बैंकिंग प्रणाली को ऋण प्रदान करेगा।&lt;/div&gt;

	&lt;ul&gt;
		&lt;li&gt;
		&lt;div&gt;ब्याज दर क्या होनी चाहिए, इस बारे में भारतीय रिजर्व बैंक की सोच पर वाणिज्यिक बैंकों को भारतीय रिजर्व बैंक द्वारा बैंक दर को एक संकेत के रूप में उपयोग किया जाता है।&lt;/div&gt;
		&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;भारतीय रिजर्व बैंक के मौद्रिक उपकरण:&lt;/strong&gt;&lt;/p&gt;

&lt;table border=&quot;1&quot; cellpadding=&quot;1&quot; cellspacing=&quot;1&quot; style=&quot;width: 350px;&quot;&gt;
	&lt;tbody&gt;
		&lt;tr&gt;
			&lt;td&gt;रेपो दर&lt;/td&gt;
			&lt;td&gt;
			&lt;p&gt;रेपो पुन: खरीद विकल्प को दर्शाता है - वह दर जिसके द्वारा भारतीय रिजर्व बैंक अन्य बैंकों को ऋण देता है, यह वह दर है जिस पर बैंक उन प्रतिभूतियों को वापस खरीदते हैं जो वे बाद की अवधि में भारतीय रिजर्व बैंक के पास रखते हैं।&lt;/p&gt;
			&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;रिवर्स रेपो दर&lt;/td&gt;
			&lt;td&gt;जिस दर पर भारतीय रिजर्व बैंक बैंक से उधार लेता है उसे रिवर्स रेपो दर के रूप में जाना जाता है।&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;CRR&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;नकद आरक्षित अनुपात, यह नकदी के प्रतिशत के अनुरूप होता है जिसे प्रत्येक बैंक को भारतीय रिजर्व बैंक के पास नकद आरक्षित के रूप में रखना होता है।&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;SLR&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;वैधानिक तरलता अनुपात या SLR जमा का न्यूनतम प्रतिशत है जिसे एक वाणिज्यिक बैंक को तरल नकदी/सोने/या अन्य के रूप में बनाए रखना होता है।&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;OMO&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;मुक्त बाज़ार प्रचालन ऐसा प्लेटफॉर्म है, जहाँ सरकारी प्रतिभूतियाँ V द्वारा बेची और खरीदी जाती हैं।&lt;/td&gt;
		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;बैंक&lt;span style=&quot;font-size: 14px;&quot;&gt; &lt;/span&gt;दर&lt;/td&gt;
			&lt;td&gt;यह आधिकारिक ब्याज दर है जिस पर भारतीय रिजर्व बैंक बैंक को ऋण प्रदान करता है और वाणिज्यिक बैंकों को दीर्घकालिक ऋण प्रदान करता है।&lt;/td&gt;
		&lt;/tr&gt;
	&lt;/tbody&gt;
&lt;/table&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;Narmada Canal Project&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;In the Narmada Canal Project&amp;nbsp;for the first time, the sprinkler irrigation system has been made compulsory in Rajasthan&lt;/strong&gt;&lt;/u&gt;.

	&lt;ul&gt;
		&lt;li&gt;The Narmada Canal is a contour canal in northwestern India that&amp;nbsp;brings water from the Sardar Sarovar Dam&amp;nbsp;to the state of Gujarat and then into Rajasthan state.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;Mahi Bajaj Sagar Dam&amp;nbsp;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;Mahi Bajaj Sagar Dam is a dam across the &lt;strong&gt;Mahi River&lt;/strong&gt;.&lt;/li&gt;
		&lt;li&gt;It is situated in the&amp;nbsp;Banswara district.&lt;/li&gt;
		&lt;li&gt;It is named after Jamnalal Bajaj.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Indira Gandhi Canal Project &lt;/strong&gt;does not provide drinking water to Pali.
	&lt;ul&gt;
		&lt;li&gt;The canal traverses&amp;nbsp;seven districts of Rajasthan:&amp;nbsp;Barmer, Bikaner, Churu, Hanumangarh, Jaisalmer, Jodhpur, and Sriganganagar.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Chambal Valley Canal Irrigation Project:&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;Chambal Valley Project ​is a joint venture of Rajasthan and Madhya Pradesh.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;It was initiated in 1954 on the Chambal River (the main tributary of the Yamuna).&lt;/span&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;नर्मदा नहर परियोजना&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;नर्मदा नहर परियोजना में पहली बार राजस्थान में फव्वारा सिंचाई प्रणाली को अनिवार्य किया गया है।&lt;/strong&gt;&lt;/u&gt;

	&lt;ul&gt;
		&lt;li&gt;नर्मदा नहर उत्तर-पश्चिमी भारत में एक समोच्च नहर है जो सरदार सरोवर बांध से गुजरात राज्य और फिर राजस्थान राज्य में पानी लाती है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;माही बजाज सागर बांध&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;माही बजाज सागर बांध &lt;strong&gt;माही नदी&lt;/strong&gt; पर बना बांध है।&lt;/li&gt;
		&lt;li&gt;यह बांसवाड़ा जिले में स्थित है।&lt;/li&gt;
		&lt;li&gt;इसका नाम जमनालाल बजाज के नाम पर रखा गया है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;इंदिरा गांधी नहर परियोजना &lt;/strong&gt;से पाली को पेयजल की आपूर्ति नहीं होती है।
	&lt;ul&gt;
		&lt;li&gt;नहर राजस्थान के सात जिलों -&amp;nbsp;बाड़मेर, बीकानेर, चूरू, हनुमानगढ़, जैसलमेर, जोधपुर और श्रीगंगानगर से होकर गुजरती है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;चंबल घाटी नहर सिंचाई परियोजना:&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;चंबल घाटी परियोजना राजस्थान और मध्य प्रदेश का संयुक्त उद्यम है।&lt;/li&gt;
		&lt;li&gt;इसकी शुरुआत 1954 में चंबल नदी (यमुना की मुख्य सहायक नदी) पर हुई थी।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;ii and iv&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&amp;nbsp;(i) It was formed in Cambrian age.
	&lt;ul&gt;
		&lt;li&gt;This statement is false. The Aravalli Range was formed during the Proterozoic Era, not the Cambrian age.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;(ii) It is considered a residual mountain at present.
	&lt;ul&gt;
		&lt;li&gt;This statement is true. The Aravalli Range is considered a residual mountain range in the sense that it is the eroded stub of ancient mountains.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;(iii) It is mainly made of Igneous rocks.
	&lt;ul&gt;
		&lt;li&gt;This statement is false. The Aravalli Range is primarily composed of metamorphic rocks like marble, gneiss, and schist. It also contains sedimentary rocks, not igneous rocks.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;(iv) It extends from south-west to north-east direction.
	&lt;ul&gt;
		&lt;li&gt;This statement is true. The Aravalli Range extends in a southwest-northeast direction across the Indian states of Gujarat, Rajasthan, Haryana, and Delhi.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;Aravalli Mountain range&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;It is considered residual mountain at present.&lt;/li&gt;
		&lt;li&gt;It extends from&lt;strong&gt; south-west to north-east direction&lt;/strong&gt;.&amp;nbsp;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;The Aravalli Range is a mountain range in Northwestern India, the length of the range is approximately 692 km in a south-west direction.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;The literal meaning of Aravalli Range is &amp;lsquo;&lt;strong&gt;line of peaks&lt;/strong&gt;&amp;rsquo;.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;Aravalli range is starting from Delhi, passing through southern Haryana and Rajasthan, and ending in Gujarat.&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;
		&lt;div&gt;&lt;span style=&quot;&quot;&gt;The highest peak is &lt;strong&gt;Guru Shikhar at 1,722 meters (5,650 ft) situated in Mount Abu&lt;/strong&gt;.&lt;/span&gt;&lt;/div&gt;
		&lt;/li&gt;
		&lt;li&gt;
		&lt;div&gt;&lt;span style=&quot;&quot;&gt;The Aravalli Range is the&lt;strong&gt; oldest range of fold mountains&lt;/strong&gt; in India.&lt;/span&gt;&lt;/div&gt;
		&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर &lt;u&gt;&lt;strong&gt;ii और iv&lt;/strong&gt;&lt;/u&gt; है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&amp;nbsp;(i) इसका निर्माण कैंब्रियन युग में हुआ था।
	&lt;ul&gt;
		&lt;li&gt;यह कथन गलत है. अरावली पर्वतमाला का निर्माण प्रोटेरोज़ोइक युग के दौरान हुआ था, न कि कैंब्रियन युग के दौरान।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;(ii) इसे वर्तमान में एक अवशिष्ट पर्वत माना जाता है।
	&lt;ul&gt;
		&lt;li&gt;यह कथन सत्य है. अरावली पर्वतमाला को इस अर्थ में अवशिष्ट पर्वत शृंखला माना जाता है कि यह प्राचीन पर्वतों का घिसा हुआ ठूंठ है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;(iii) यह मुख्यतः आग्नेय चट्टानों से बना है।
	&lt;ul&gt;
		&lt;li&gt;यह कथन गलत है. अरावली पर्वत श्रृंखला मुख्य रूप से संगमरमर, नीस और शिस्ट जैसी रूपांतरित चट्टानों से बनी है। इसमें अवसादी चट्टानें भी होती हैं, आग्नेय चट्टानें नहीं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;(iv) इसका विस्तार दक्षिण-पश्चिम से उत्तर-पूर्व दिशा तक है।
	&lt;ul&gt;
		&lt;li&gt;यह कथन सत्य है. अरावली पर्वतमाला भारतीय राज्यों गुजरात, राजस्थान, हरियाणा और दिल्ली में दक्षिण-पश्चिम-उत्तर-पूर्व दिशा में फैली हुई है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;अरावली पर्वतमाला&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;यह वर्तमान में अवशिष्ट पर्वत माना जाता है।&lt;/li&gt;
		&lt;li&gt;यह &lt;strong&gt;दक्षिण-पश्चिम से उत्तर-पूर्व दिशा तक&lt;/strong&gt; फैली हुई है।&lt;/li&gt;
		&lt;li&gt;अरावली पर्वत श्रृंखला उत्तर पश्चिमी भारत में एक पर्वत श्रृंखला है, दक्षिण-पश्चिम दिशा में सीमा की लंबाई लगभग 692 किलोमीटर&amp;nbsp;है।&lt;/li&gt;
		&lt;li&gt;अरावली पर्वतमाला का शाब्दिक अर्थ&amp;nbsp;&lt;strong&gt;&amp;#39;चोटियों की रेखा&amp;#39;&lt;/strong&gt;&amp;nbsp;है।&lt;/li&gt;
		&lt;li&gt;अरावली पर्वतमाला दिल्ली से शुरू होकर दक्षिणी हरियाणा और राजस्थान से होते हुए गुजरात में समाप्त होती है।&lt;/li&gt;
		&lt;li&gt;सबसे ऊँची चोटी&lt;strong&gt; माउंट आबू में स्थित 1,722 मीटर (5,650 फीट) पर गुरु शिखर&lt;/strong&gt; है।&lt;/li&gt;
		&lt;li&gt;अरावली पर्वतमाला भारत में &lt;strong&gt;वलित पर्वतों में&amp;nbsp;सबसे पुरानी पर्वतमाला&lt;/strong&gt; है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;u&gt;&lt;strong&gt;Allahabad&lt;/strong&gt;&lt;/u&gt;.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;Maulvi Liaquat Ali was a&amp;nbsp;Muslim religious leader from Allahabad (Prayagraj)&lt;/strong&gt;&lt;/u&gt;, in the state of Uttar Pradesh&amp;nbsp;in present-day India.

	&lt;ul&gt;
		&lt;li&gt;He was one of the leaders in the revolt against the British in 1857.&lt;/li&gt;
		&lt;li&gt;This war was also known as the First War of Independence.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
