&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;1857 का भारतीय विद्रोह&lt;/strong&gt; ब्रिटिश ईस्ट इंडिया कंपनी के शासन के खिलाफ भारत में एक बड़ा विद्रोह था, जिसने ब्रिटिश क्राउन&amp;nbsp;की ओर से एक संप्रभु शक्ति के रूप में कार्य किया था।

	&lt;ul&gt;
		&lt;li&gt;विद्रोह &lt;strong&gt;10 मई 1857 &lt;/strong&gt;को मेरठ के गैरीसन शहर में कंपनी की सेना के सैनिकों द्वारा विद्रोह के रूप में शुरू हुआ।&lt;/li&gt;
		&lt;li&gt;विद्रोह ने उस क्षेत्र में ब्रिटिश सत्ता के लिए एक बड़ा खतरा पैदा कर दिया और &lt;strong&gt;20 जून 1858&lt;/strong&gt; को ग्वालियर में विद्रोहियों की हार के साथ ही समाहित हो गया।&lt;/li&gt;
		&lt;li&gt;इसके&amp;nbsp;नाम के सम्बंध में मत विरोध है&amp;nbsp;और इसे सिपाही विद्रोह, भारतीय विद्रोह, महान विद्रोह, 1857 का विद्रोह, भारतीय विद्रोह और प्रथम&amp;nbsp;स्वतंत्रता संग्राम&amp;nbsp;के रूप में वर्णित किया जाता&amp;nbsp;है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Karauli&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;Shivratri cattle fair is held at&amp;nbsp;Karauli district of Rajasthan&lt;/strong&gt;.&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;It is also called&amp;nbsp;&lt;/span&gt;Karauli Cattle Fair.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;​The fair&amp;nbsp;is held in the&lt;strong&gt; month of February every year&lt;/strong&gt; for a week which &lt;strong&gt;coincides with the festival of Maha Shivratri&lt;/strong&gt;.&lt;/li&gt;
	&lt;li&gt;This fair is one of the oldest cattle fairs of Rajasthan where thousands of animals like camel, buffalo, donkeys, etc. are brought for sale/purchase.&lt;/li&gt;
	&lt;li&gt;Visitors can see the trading of animals, the animal owners camping, shops selling colorful and attractive items for use and decoration of the animals.&lt;/li&gt;
	&lt;li&gt;At the end of the fair, various competitions are also held to judge the outstanding specimens.&lt;/li&gt;
	&lt;li&gt;Then, the animal fair are traded for spices, handicraft items and all kind of household goods.&lt;/li&gt;
	&lt;li&gt;The religious fairs at Karauli are held in March-April and Sept-Oct at the temple of Kaila Devi Ji.&lt;span style=&quot;&quot;&gt;&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p style=&quot;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सही उत्तर&amp;nbsp;&lt;/font&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;करौली&lt;/span&gt;&lt;/u&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;है।&lt;/font&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;strong&gt;शिवरात्रि पशु मेला राजस्थान के करौली जिले में लगता है।&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;इसे&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;करौली पशु मेला भी कहते हैं।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;मेला&amp;nbsp;&lt;/font&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;हर साल फरवरी के महीने में&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;एक सप्ताह के लिए आयोजित किया जाता है जो&amp;nbsp;&lt;/font&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;महा शिवरात्रि के त्योहार के साथ पड़ता है&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;।&lt;/font&gt;&lt;/li&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह मेला राजस्थान के सबसे पुराने पशु मेलों में से एक है जहां ऊंट, भैंस, गधे आदि जैसे हजारों जानवरों को बिक्री / खरीद के लिए लाया जाता है।&lt;/font&gt;&lt;/li&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;आगंतुकों को पशुओं&amp;nbsp;के व्यापार, डेरा डाले हुए पशु मालिकों, पशुओं&amp;nbsp;के उपयोग और सजावट के लिए रंगीन और आकर्षक वस्तुओं की बिक्री करने वाली दुकानें&amp;nbsp;देखने को मिलती&amp;nbsp;हैं।&lt;/font&gt;&lt;/li&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;मेले के अंत में, उत्कृष्ट नमूनों की परख करने के लिए विभिन्न प्रतियोगिताएं भी आयोजित की जाती हैं।&lt;/font&gt;&lt;/li&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;फिर, पशु मेले में मसालों, हस्तकला की वस्तुओं और सभी प्रकार के घरेलू सामानों का व्यापार किया जाता है।&lt;/font&gt;&lt;/li&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;करौली में धार्मिक मेले मार्च-अप्रैल और सितंबर-अक्टूबर में कैला देवी जी के मंदिर में आयोजित किए जाते हैं।&lt;/font&gt;&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Tallinath Ji - Katriyasar (Bikaner)&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Devnarayan Ji&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;He was married to Pipalde, the daughter of Raja Jai Singh (the ruler of Dhar in Madhya Pradesh).&lt;/li&gt;
		&lt;li&gt;He is the deity of the Gurjar caste.&lt;/li&gt;
		&lt;li&gt;He is considered an incarnation of Vishnu.&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​&lt;/span&gt;The principal temple of Devnaryan is located at Sawai Bhoj near &lt;strong&gt;Asind town in Bhilwara&lt;/strong&gt;.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Veer Teja&lt;/strong&gt;, also known as &lt;strong&gt;Tejaji&lt;/strong&gt;, is a Rajasthani folk god.
	&lt;ul&gt;
		&lt;li&gt;He was born in the Jat dynasty at Nagaur.&lt;/li&gt;
		&lt;li&gt;He is venerated as a deity and is one of Shiva&amp;#39;s principal eleven incarnations.&lt;/li&gt;
		&lt;li&gt;He&amp;nbsp;got injured in Sursura village to save the cows of Lachha Gurjari and died due to a snake bite.&lt;/li&gt;
		&lt;li&gt;The snake is worshipped as the protector deity. Tejaji is called the deity of &amp;#39;Kala Bala&amp;#39;.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;A large fair, Mela Tejaji, takes place on the eleventh lunar day of Bhadrapad Shukla Paksh every year in&amp;nbsp; Parbatsar, District Nagaur at his main temple&lt;/strong&gt;.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Tallinath ji&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;He was born in Shergarh, Jodhpur.&lt;/li&gt;
		&lt;li&gt;He is the main folk deity of &lt;strong&gt;Jalore district&lt;/strong&gt;.&lt;/li&gt;
		&lt;li&gt;His main temple is situated on Panchmukhi hill in Jalore in Panchota village.&amp;nbsp;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Pabuji is a folk deity of Rajasthan&lt;/span&gt;.
	&lt;ul&gt;
		&lt;li&gt;He is worshiped as the protector of cattle.&lt;/li&gt;
		&lt;li&gt;He&amp;nbsp;is known for many characteristics such as being a great warrior, committed to his words, the refugee and untouchables, and honor for women.&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;He was born in Kolu&amp;nbsp;village&lt;/span&gt;.&lt;/li&gt;
		&lt;li&gt;Kolu&amp;nbsp;village is located in Phalodi tehsil of Jodhpur district in Rajasthan.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

