&lt;p style=&quot;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सही उत्तर&amp;nbsp;&lt;/font&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;बंगाल का विभाजन -&amp;nbsp; कांग्रेस का&amp;nbsp;सूरत विभाजन - लखनऊ समझौता&lt;/span&gt;&lt;/u&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;&lt;/font&gt;&lt;span style=&quot;&quot;&gt;है&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;।&lt;/font&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;strong&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;बंगाल&lt;/font&gt;&lt;/strong&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;का विभाजन&lt;/font&gt;&lt;/span&gt;&lt;/font&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;19 जुलाई, 1905&lt;/font&gt;&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;को बंगाल विभाजन की घोषणा की गई थी।&lt;/font&gt;&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;लॉर्ड कर्जन ने प्रशासनिक उपाय के रूप में प्रांत के विभाजन का प्रस्ताव रखा।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;विभाजन ने बड़े पैमाने पर मुस्लिम पूर्वी क्षेत्रों को बड़े पैमाने पर हिंदू पश्चिमी क्षेत्रों से अलग कर दिया।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;भागीरथी नदी ने पूर्वी बंगाल और पश्चिम बंगाल के बीच एक भौतिक विभाजनकर्ता के रूप में कार्य किया।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;रवींद्रनाथ टैगोर ने विभाजन के समय प्रसिद्ध गीत &amp;#39;आमार सोनार बांग्ला&amp;#39; की रचना की जो बाद में बांग्लादेश का राष्ट्रगान बना।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;कांग्रेस का सूरत विभाजन&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;भारतीय राष्ट्रीय कांग्रेस का सूरत अधिवेशन 26 दिसंबर&amp;nbsp;&lt;/font&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;1907&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;को संपन्न हुआ।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह मुख्य रूप से उदारवादी और चरमपंती&amp;nbsp;समूहों के दृष्टिकोणों के बीच अंतर के कारण था।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;चरमपंथियों का नेतृत्व लोकमान्य तिलक, लाजपत राय और बिपिन चंद्र पाल ने किया था।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;उदारवादियों&amp;nbsp;का नेतृत्व गोपाल कृष्ण गोखले, फिरोज शाह मेहता और सुरेंद्रनाथ बनर्जी ने किया।&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सूरत अधिवेशन (1907) में, अध्यक्ष&amp;nbsp;पद के उम्मीदवार के रूप में, &lt;/font&gt;&lt;span style=&quot;&quot;&gt;चरमपंती&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt; राय या तिलक चाहते थे और &lt;/font&gt;&lt;span style=&quot;&quot;&gt;उदारवादियों&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt; ने घोष को अध्यक्ष&amp;nbsp;बनाने का समर्थन किया।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;1916 में कांग्रेस के लखनऊ अधिवेशन में विभाजित कांग्रेस फिर से एक हो गई।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;लखनऊ समझौता&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;दिसंबर 1916&lt;/font&gt;&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;में लखनऊ में आयोजित दोनों दलों के संयुक्त सत्र में भारतीय राष्ट्रीय कांग्रेस और मुस्लिम लीग (&lt;/font&gt;&lt;/font&gt;&lt;span style=&quot;&quot;&gt;AIMLM&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;) के बीच एक समझौता हुआ था।&lt;/font&gt;&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;समझौते के माध्यम से, दोनों पक्ष प्रांतीय विधानसभाओं में धार्मिक अल्पसंख्यकों को प्रतिनिधित्व की अनुमति देने पर सहमत हुए।&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;दोनों पक्षों द्वारा अंग्रेजों को प्रस्तुत की गई कुछ सामान्य माँगें थीं-&lt;/font&gt;
		&lt;ul&gt;
			&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;परिषदों पर निर्वाचित सीटों की संख्या बढ़ाई जानी चाहिए।&lt;/font&gt;&lt;/li&gt;
			&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;प्रांतों में अल्पसंख्यकों की रक्षा की जानी चाहिए।&lt;/font&gt;&lt;/li&gt;
			&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सभी प्रांतों को स्वायत्तता दी जानी चाहिए।&lt;/font&gt;&lt;/li&gt;
			&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;कार्यपालिका को न्यायपालिका से अलग करना।&lt;/font&gt;&lt;/li&gt;
		&lt;/ul&gt;
		&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;Ghudla - Shravana Shukla Tritiya&lt;/strong&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Fuldol/Phooldol fair&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;It is held in ​&lt;/span&gt;Shahpura&amp;nbsp;&lt;strong&gt;on&amp;nbsp;&lt;span style=&quot;&quot;&gt;Chaitra Krishna Pratipada&lt;/span&gt;&lt;/strong&gt;.&lt;/li&gt;
		&lt;li&gt;The tradition of celebrating the Phuldol fair started in Bhilwara.&lt;/li&gt;
		&lt;li&gt;After celebrating the Phuldol fair in Bhilwara for about four years, Maharaj went to Shahpura.&lt;/li&gt;
		&lt;li&gt;This fair/festival is primarily celebrated by&amp;nbsp;Ramsnehi Sect.&lt;/li&gt;
		&lt;li&gt;Devotees create a hindolo of flowers, install the Bhagwan&amp;#39;s murti, and swing Him on the day of Pushapadolotsav.&lt;/li&gt;
		&lt;li&gt;The devotees are sprayed with coloured and aromatic water from a hose attached to Bhagwan Swaminarayan&amp;#39;s murti in the central shrine.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Gangaur&amp;nbsp;&lt;/span&gt;​festival&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;It is&amp;nbsp;celebrated on &lt;strong&gt;Chaitra Shukla Teej&lt;/strong&gt;.&lt;/li&gt;
		&lt;li&gt;It is devoted to Parvati (Gauri).&lt;/li&gt;
		&lt;li&gt;It is the celebration of spring, harvest, marital fidelity, and childbearing.&lt;/li&gt;
		&lt;li&gt;It is observed for marital-bliss.&amp;nbsp;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Ub Chhath festival&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;It is celebrated on &lt;strong&gt;Bhadrapad Krishna Paksh Shashthi&lt;/strong&gt;.​&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;The birthday of Balram, the elder brother of Lord Krishna&amp;nbsp;(as per Hindu Mythology) is celebrated as Ub Chhath.&lt;/li&gt;
		&lt;li&gt;It is celebrated for&amp;nbsp;the happiness and&amp;nbsp;prosperity of the family.&lt;/li&gt;
		&lt;li&gt;The fast and worship of Ub Chhath is observed by married women for the long life of their husbands and unmarried girls for a good husband.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Ghudla festival&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;It&amp;nbsp;is mainly celebrated in the Jodhpur, Barmer, and Jaisalmer districts of Marwar from Sheetla Saptami to &lt;strong&gt;Chaitra Shukla Tritiya&lt;/strong&gt;.&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​It&amp;nbsp;&lt;/span&gt;is the prominent festival of Rajasthan in which women gather and come to the potter&amp;#39;s house, placing a lamp in a pot with a hole and singing their home song.&lt;/li&gt;
		&lt;li&gt;After roaming around in the locality, women take Gurla to their relative&amp;#39;s houses singing folk songs and praying for happiness and prosperity.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p style=&quot;&quot;&gt;सही उत्तर &lt;strong&gt;घुड़ला - श्रावण शुक्ल तृतीया&lt;/strong&gt; है।&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;फुलडोल/फूलडोल मेला&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;यह &lt;strong&gt;चैत्र कृष्ण प्रतिपदा&lt;/strong&gt; पर शाहपुरा में आयोजित किया जाता है।&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;भीलवाड़ा में फूलडोल मेला मनाने की परंपरा शुरू हुई।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;लगभग चार वर्षों तक भीलवाड़ा में फूलडोल मेला मनाने के बाद महाराज शाहपुरा चले गए।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह मेला/उत्सव&amp;nbsp;मुख्य रूप से रामस्नेही संप्रदाय द्वारा मनाया जाता है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;भक्त फूलों का हिंडोलो बनाते हैं, भगवान की मूर्ति स्थापित करते हैं, और उन्हें पुष्पदोलोत्सव के दिन झुलाते हैं।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;केंद्रीय मंदिर में भगवान स्वामीनारायण की मूर्ति से जुड़ी एक नली से भक्तों पर रंगीन और सुगंधित पानी का छिड़काव किया जाता है।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;गणगौर &lt;/strong&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;उत्सव&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह&amp;nbsp;&lt;/font&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;चैत्र शुक्ल तीज&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;को मनाया जाता है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह पार्वती (गौरी) को समर्पित है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह वसंत, फसल, वैवाहिक निष्ठा और बच्चे को पालने का उत्सव है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह वैवाहिक-आनंद के लिए मनाया जाता है।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;ऊबछठ&lt;/span&gt; &lt;/strong&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;उत्सव&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;यह &lt;strong&gt;भाद्रपद कृष्ण पक्ष षष्ठी&lt;/strong&gt; को मनाया जाता है&lt;span style=&quot;&quot;&gt;।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;भगवान कृष्ण के बड़े भाई बलराम (हिंदू पौराणिक कथाओं के अनुसार) के जन्मदिन को उब छठ के रूप में मनाया जाता है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह परिवार की सुख-समृद्धि के लिए मनाया जाता है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;उब छठ का व्रत और पूजा विवाहित महिलाएं अपने पति की लंबी उम्र के लिए और कुंवारी लड़कियां अच्छे पति के लिए करती हैं।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;घुड़ला उत्सव&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह मुख्य रूप से मारवाड़ के जोधपुर, बाड़मेर और जैसलमेर जिलों में शीतला सप्तमी से&amp;nbsp;&lt;/font&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;चैत्र शुक्ल तृतीया&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;तक मनाया जाता है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;राजस्थान का प्रमुख उत्सव&amp;nbsp;है जिसमें महिलाएं इकट्ठा होकर कुम्हार के घर आती हैं, एक छेद वाले बर्तन में दीपक रखती हैं और अपने घर का गीत गाती हैं।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;मोहल्ले में घूमने के बाद महिलाएं गुरला को लोकगीत गाते हुए और सुख-समृद्धि की प्रार्थना करते हुए अपने रिश्तेदार के घर ले जाती हैं।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Rs.&amp;nbsp;12.00 per kg&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;The Government of&amp;nbsp;&lt;/span&gt;Rajasthan makes available free / highly subsidized Jatropha saplings to the farmers for planting on their unused / barren land besides providing technical guidance.&lt;/li&gt;
	&lt;li&gt;The Govt. provides declared support price for Jatropha seed &lt;strong&gt;(Rs.12.00 per kg)&lt;/strong&gt; to safeguard interest of farmers who plant&amp;nbsp; Jatropha on their fallow land.&lt;/li&gt;
	&lt;li&gt;The Govt. land can also be alloted to BPL-SHGS &amp;amp; Gram panchyat for plantation of jatropha through financial support under Mahatma Gandhi NREGA.&lt;/li&gt;
	&lt;li&gt;Once planted, Jatropha/Ratanjot plantation would continue for about 40 years.
	&lt;ul&gt;
		&lt;li&gt;It starts fruiting from 3rd year.&lt;/li&gt;
		&lt;li&gt;On an average, one Plant gives 3 to 4 kg fruits per year comes twice a year.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Jatropha&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​It&lt;/span&gt;&amp;nbsp;is cultivated to be used as Bio-diesel.&lt;/li&gt;
		&lt;li&gt;It is a flowering plant that belongs to the Euphorbiaceae family.&lt;/li&gt;
		&lt;li&gt;In Hindi, it is known as &amp;#39;Jangli Arandi&amp;#39;.&lt;/li&gt;
		&lt;li&gt;It is found in tropical and sub-tropical regions of the world.&lt;/li&gt;
		&lt;li&gt;It is grown in the wasteland.&lt;/li&gt;
		&lt;li&gt;Jatropha seeds have high-quality oil content. It has 43% of oil content in its seeds which are used for producing various industrial products.&lt;/li&gt;
		&lt;li&gt;These seeds are toxic for human consumption.&lt;/li&gt;
		&lt;li&gt;These seeds are used to produce biodiesel, biokerosene, cosmetic products, and pesticides.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p style=&quot;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सही उत्&amp;zwj;तर&amp;nbsp;&lt;/font&gt;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;12.00₹ प्रति किग्रा&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;है&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;राजस्थान सरकार&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;तकनीकी मार्गदर्शन प्रदान करने के अलावा किसानों को उनकी अनुपयोगी/बंजर भूमि पर रोपण के लिए मुफ्त/अत्यधिक सब्सिडी वाले जट्रोफा के पौधे उपलब्ध कराती है।&lt;/font&gt;&lt;/li&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सरकार&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;अपनी बंजर भूमि पर जेट्रोफा लगाने वाले किसानों के हितों की रक्षा के&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;लिए जेट्रोफा बीज&amp;nbsp;&lt;/font&gt;&lt;/font&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;(&lt;/span&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;12.00₹&lt;/span&gt;&lt;/strong&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt; प्रति किग्रा) के लिए घोषित समर्थन मूल्य प्रदान करती&amp;nbsp;है।&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सरकार&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;महात्मा गांधी नरेगा के तहत वित्तीय सहायता के माध्यम से जेट्रोफा के रोपण के लिए &lt;/font&gt;&lt;/font&gt;&lt;span style=&quot;&quot;&gt;BPL-SHGS&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;और ग्राम पंचायत को भूमि भी आवंटित की जा सकती है।&lt;/font&gt;&lt;/font&gt;&lt;/li&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;एक बार रोपने के बाद जेट्रोफा/ रतनजोत का पौधारोपण लगभग 40 वर्षों तक जारी रहेगा।&lt;/font&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह तीसरे वर्ष से फल देना शुरू कर देता है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;औसतन एक पौधा साल में दो बार 3 से 4 किलो फल देता है।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;जट्रोफा&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;बायो-डीजल के रूप में उपयोग करने के लिए इसकी खेती की जाती है&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;।&lt;/font&gt;&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह एक फूल वाला पौधा है जो यूफोरबिएसी परिवार का है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;कई तरह की होती हैं &amp;#39;जंगली अरंडी&amp;#39;&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह दुनिया के उष्णकटिबंधीय और उपोष्णकटिबंधीय क्षेत्रों में पाया जाता है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;इसे बंजर भूमि में उगाया जाता है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;जेट्रोफा के बीज में उच्च गुणवत्ता वाली तेल सामग्री होती है।&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;इसके बीजों में 43% तेल की मात्रा होती है जिसका उपयोग विभिन्न औद्योगिक उत्पादों के उत्पादन के लिए किया जाता है।&lt;/font&gt;&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;ये बीज मानव उपभोग के लिए जहरीले होते हैं।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;इन बीजों का उपयोग बायोडीजल, बायोकेरोसिन, कॉस्मेटिक उत्पादों और कीटनाशकों के उत्पादन के लिए किया जाता है।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Shillong&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;The highest point of the Meghalaya Plateau is&amp;nbsp;&lt;u&gt;&lt;strong&gt;Shillong peak&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Shillong Peak&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​It is&amp;nbsp;&lt;/span&gt;at 6,433 feet&amp;nbsp;(1,961 metres) located 5 km south of the city of Shillong.&lt;/li&gt;
		&lt;li&gt;There&amp;nbsp;is also a prominent IAF station.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;The Shillong Plateau is considered an outlier of the plateau of peninsular India.
	&lt;ul&gt;
		&lt;li&gt;It is composed primarily of ancient rocks.&lt;/li&gt;
		&lt;li&gt;It contains reserves of coal and iron ore, and limestone is quarried.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Meghalaya is one of the seven sister states in the North East&lt;/strong&gt;.
	&lt;ul&gt;
		&lt;li&gt;It was declared as a state on 21st January, 1972.&lt;/li&gt;
		&lt;li&gt;It is divided into five administrative districts of the Jaintia Hills, East and West Garo Hills and East and West Khasi Hills.&lt;/li&gt;
		&lt;li&gt;The state of Meghalaya is also known as &amp;ldquo; Meghalaya Plateau&amp;rdquo;.&lt;/li&gt;
		&lt;li&gt;It consists mainly of Archean rock formations. These rock formations contain rich deposits of valuable minerals like Coal, Limestone, Uranium and Silimanite.&lt;/li&gt;
		&lt;li&gt;The elevation of the plateau ranges between 150 m to 1961 m.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;The central part of the plateau comprising the Khasi Hills has the highest elevation.&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;The Cherrapunjee &amp;ndash; Mawsynram belt in the southern slopes of Khasi Hills records the heaviest rainfall in the world.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;The Garo Hills which form the western part of Meghalaya are lower in elevation.&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;The greater part of Garo Hills range in height from 450 m to 600 m and drop steeply to the Brahmaputra valley on the north and to the plains of Bangladesh on the south.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;The Hill area of Jaintia Hills is similar to that of Khasi Hills&lt;/strong&gt;.
	&lt;ul&gt;
		&lt;li&gt;The northern strip comprises of low lying terrain region, fertile and favourable for cultivation.&lt;/li&gt;
		&lt;li&gt;Lum Maryngksih is&amp;nbsp;the highest peak in Jaintia Hills.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p style=&quot;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सही उत्तर&amp;nbsp;&lt;/font&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;शिलांग&lt;/span&gt;&lt;/u&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;है।&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;मेघालय पठार का उच्चतम बिंदु&amp;nbsp;&lt;/font&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;शिलांग चोटी&lt;/span&gt;&lt;/u&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;है।&lt;/font&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;शिलांग &lt;/span&gt;&lt;strong&gt;चोटी&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;शिलांग शहर से 5 किमी दक्षिण में स्थित 6,433 फीट (1,961 मीटर) पर है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यहां एक प्रमुख भारतीय वायु सेना स्टेशन भी है।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;शिलांग पठार को प्रायद्वीपीय भारत के पठार का बाहरी भाग माना जाता है।&lt;/font&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह मुख्य रूप से प्राचीन चट्टानों से बना है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;इसमें कोयले और लौह अयस्क के भंडार हैं, और चूना पत्थर का उत्खनन किया जाता है।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;मेघालय उत्तर पूर्व के सात बहन राज्यों में से एक है&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;।&lt;/font&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;21 जनवरी 1972 को इसे राज्य घोषित किया गया।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह जयंतिया हिल्स, पूर्व और पश्चिम गारो हिल्स और पूर्व और पश्चिम खासी हिल्स के पांच प्रशासनिक जिलों में विभाजित है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;मेघालय राज्य को &amp;quot;मेघालय का पठार&amp;quot; भी कहा जाता है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;इसमें मुख्य रूप से आर्कियन रॉक फॉर्मेशन शामिल हैं।&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;इन रॉक संरचनाओं में कोयला, चूना पत्थर, यूरेनियम और सिलिमेनाइट जैसे मूल्यवान खनिजों का समृद्ध भंडार है।&lt;/font&gt;&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;पठार की ऊंचाई 150 मीटर से 1961 मीटर के बीच है।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;खासी पहाड़ियों वाले पठार के मध्य भाग में सबसे अधिक ऊँचाई है।&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;खासी &lt;/font&gt;पहाड़ियां&lt;font style=&quot;vertical-align: inherit;&quot;&gt; के दक्षिणी ढलानों में स्थित चेरापूंजी-मौसिनराम बेल्ट में दुनिया की सबसे भारी बारिश दर्ज की जाती है।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;गारो पहाड़ियाँ जो मेघालय के पश्चिमी भाग का निर्माण करती हैं, ऊँचाई में कम हैं।&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;गारो हिल्स का बड़ा हिस्सा 450 मीटर से 600 मीटर तक ऊंचा है और उत्तर में ब्रह्मपुत्र घाटी और दक्षिण में बांग्लादेश के मैदानी इलाकों में तेजी से गिरता है।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;जयंतिया &lt;/span&gt;&lt;strong&gt;पहाड़ियां&lt;/strong&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt; का पहाड़ी क्षेत्र खासी &lt;/span&gt;&lt;strong&gt;पहाड़ियां&lt;/strong&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt; के समान है&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;।&lt;/font&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;उत्तरी पट्टी में निचले इलाके के इलाके, उपजाऊ और खेती के लिए अनुकूल हैं।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;लुम मेरींगक्षिह जयंतिया &lt;/font&gt;पहाड़ियां&lt;font style=&quot;vertical-align: inherit;&quot;&gt; की सबसे ऊंची चोटी है।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Bundi&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;Vegetable Centre of Excellence has been established in Rajasthan in &lt;u&gt;&lt;strong&gt;Bundi&lt;/strong&gt;&lt;/u&gt;.&amp;nbsp;&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​It is&amp;nbsp;&lt;/span&gt;aimed at providing saplings of improved vegetable varieties to farmers apart from increasing vegetable production and ensuring fair prices.&lt;/li&gt;
		&lt;li&gt;The Centre has been developed under the Rashtriya Krishi Vikas Yojana. However, its infrastructure has been developed by Rajasthan Government.&lt;/li&gt;
		&lt;li&gt;The Centre would provide good quality vegetable seedlings to farmers who face challenges growing vegetables during off season.&lt;/li&gt;
		&lt;li&gt;Techniques such as Hyrdophonics (cultivation in water), aqua (cultivation of vegetables and fish together), polyhouse and shade net house have been developed at the centre.&lt;/li&gt;
		&lt;li&gt;The centre has also set up a solar hydration unit for glut management and to assist farmers in getting due price for their vegetables after processing.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p style=&quot;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सही उत्तर&amp;nbsp;&lt;/font&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;बूंदी&lt;/span&gt;&lt;/u&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;है।&lt;/font&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;राजस्थान के&amp;nbsp;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;बूंदी&lt;/span&gt;&lt;/u&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;में सब्जी उत्कृष्टता केंद्र स्थापित किया गया है&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;।&amp;nbsp;&lt;/font&gt;&lt;/font&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;इसका&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;उद्देश्य सब्जी उत्पादन बढ़ाने और उचित मूल्य सुनिश्चित करने के अलावा किसानों को उन्नत सब्जियों की किस्मों के पौधे उपलब्ध कराना है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;केंद्र को राष्ट्रीय कृषि विकास योजना के तहत विकसित किया गया है।&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;हालांकि, इसके इंफ्रास्ट्रक्चर को राजस्थान सरकार ने विकसित किया है।&lt;/font&gt;&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;केंद्र उन किसानों को अच्छी गुणवत्ता वाली सब्जियां उपलब्ध कराएगा जो ऑफ सीजन के दौरान सब्जियां उगाने में चुनौतियों का सामना करते हैं।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;केंद्र में हाइड्रोफोनिक्स (पानी में खेती), एक्वा (सब्जियों और मछलियों की एक साथ खेती), पॉलीहाउस और शेड नेट हाउस जैसी तकनीकें विकसित की गई हैं।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;केंद्र ने ग्लूट प्रबंधन के लिए एक सौर जलयोजन इकाई भी स्थापित की है और किसानों को प्रसंस्करण के बाद उनकी सब्जियों के लिए उचित मूल्य प्राप्त करने में सहायता प्रदान की है।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;P.C. Mahalanobis&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;Second Five-Year Plan&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;It&amp;nbsp;&lt;/span&gt;was based on the ideas of &lt;strong&gt;Prasanta Chandra Mahalanobis.&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;The second five-year plan was spread across the time period of&lt;strong&gt; 1956 to 1961.&lt;span style=&quot;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;The areas of focus of the second five-year plan were on the &amp;quot;&lt;strong&gt;development of the public sector and rapid industrialization&lt;/strong&gt;&amp;quot;.&lt;/li&gt;
		&lt;li&gt;The plan attempted to determine the optimal allocation of investment between productive sectors in order to maximize long-run economic growth.&lt;/li&gt;
		&lt;li&gt;It used the prevalent state-of-the-art techniques of operations research and optimization as well as the novel applications of statistical models developed at the Indian Statistical Institute.&lt;/li&gt;
		&lt;li&gt;The plan assumed a closed economy in which the main trading activity would be centered on importing capital goods.&lt;/li&gt;
		&lt;li&gt;From the Second Five-Year Plan, there was a determined thrust towards substitution of basic and capital good industries.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;P.C. Mahalanobis&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;He is ​&lt;/span&gt;considered the father of modern statistics in India.&lt;/li&gt;
		&lt;li&gt;He founded the Indian Statistical Institute (ISI) and&amp;nbsp;shaped the Planning Commission.&lt;/li&gt;
		&lt;li&gt;He made pioneering studies in anthropometry in India.&lt;/li&gt;
		&lt;li&gt;He pioneered methodologies for large-scale surveys.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p style=&quot;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सही उत्&amp;zwj;तर&amp;nbsp;&lt;/font&gt;&lt;/font&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;पी.सी. महलानोबिस&lt;/span&gt;&lt;/u&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;है।&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;दूसरी पंचवर्षीय योजना&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;यह&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;प्रशांत चंद्र महालनोबिस&lt;/font&gt;&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;nbsp;के विचारों पर आधारित थी।&lt;/font&gt;&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;दूसरी पंचवर्षीय योजना की &lt;/font&gt;&lt;span style=&quot;color: rgb(33, 37, 41); font-weight: 700;&quot;&gt;समयावधि&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;1956 से 1961 तक थी।&lt;/font&gt;&lt;/font&gt;&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;दूसरी पंचवर्षीय योजना के केंद्र में&amp;nbsp;&amp;quot;&lt;/font&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;सार्वजनिक क्षेत्र के विकास और तीव्र औद्योगीकरण&lt;/span&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&amp;quot; थे।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;योजना ने दीर्घकालीन आर्थिक विकास को अधिकतम करने के लिए उत्पादक क्षेत्रों के बीच निवेश के इष्टतम आवंटन को निर्धारित करने का प्रयास किया।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;इसने संचालन अनुसंधान और अनुकूलन की प्रचलित अत्याधुनिक तकनीकों के साथ-साथ भारतीय सांख्यिकी संस्थान में विकसित सांख्यिकीय मॉडल के उपन्यास अनुप्रयोगों का उपयोग किया।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;योजना ने एक बंद अर्थव्यवस्था की कल्पना की जिसमें मुख्य व्यापारिक गतिविधि पूंजीगत वस्तुओं के आयात पर केंद्रित होगी।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;दूसरी पंचवर्षीय योजना से, बुनियादी और पूंजीगत अच्छे उद्योगों के प्रतिस्थापन की दिशा में दृढ़ बल दिया गया था।&lt;/font&gt;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;पी.सी. महालनोबिस&lt;/span&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;उन्हें भारत में आधुनिक सांख्यिकी का जनक&amp;nbsp;&lt;/font&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;माना जाता है।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;उन्होंने भारतीय सांख्यिकी संस्थान (ISI) की स्थापना की और योजना आयोग को आकार दिया।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;उन्होंने भारत में एंथ्रोपोमेट्री में अग्रणी अध्ययन किया।&lt;/font&gt;&lt;/li&gt;
		&lt;li&gt;उन्होंने बड़े पैमाने पर सर्वेक्षणों के लिए पद्धतियों का आरम्भ किया। ​&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;2013&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;The Finance Minister of India had announced the establishment of an all-women bank with an initial capital of Rs 1,000 crore in Budget 2013-14.&lt;/li&gt;
	&lt;li&gt;Former Indian Prime Minister Manmohan Singh inaugurated &lt;strong&gt;Bharatiya Mahila Bank&lt;/strong&gt;&amp;nbsp;on 19 November 2013 on the occasion of the 96th birth anniversary of former Indian Prime Minister Indira Gandhi.&lt;/li&gt;
	&lt;li&gt;Bharatiya Mahila Bank was a fully owned subsidiary of State Bank of India based in Mumbai, India.
	&lt;ul&gt;
		&lt;li&gt;&lt;strong&gt;It was&amp;nbsp;merged with State Bank of India on 1 April 2017&lt;/strong&gt;.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;India was the third country, after Pakistan and Tanzania, to have a bank exclusively to benefit women.
	&lt;ul&gt;
		&lt;li&gt;The bank placed an emphasis on funding for skills developments to help in economic activity.&lt;/li&gt;
		&lt;li&gt;One of the other objectives of the bank was to promote asset ownership amongst women customers.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p style=&quot;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;सही उत्&amp;zwj;तर&amp;nbsp;&lt;/font&gt;&lt;/font&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;2013&lt;/span&gt;&lt;/u&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;है।&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;font style=&quot;vertical-align: inherit;&quot;&gt;भारत के वित्त मंत्री ने बजट 2013-14 में 1,000 करोड़ रुपये की प्रारंभिक पूंजी के साथ एक पूर्ण महिला बैंक की स्थापना की घोषणा की थी।&lt;/font&gt;&lt;/li&gt;
