&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Fedora&amp;nbsp;&lt;/strong&gt;&lt;/u&gt;is not an antivirus&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;software.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Fedora&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;It is an open source Linux-based operating system.&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​&lt;/span&gt;Fedora operating system is an open-source operating system that is based on the Linux OS kernel architecture.&lt;/li&gt;
		&lt;li&gt;It&amp;nbsp;is sponsored by Red Hat.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Anti-virus&amp;nbsp;&lt;/span&gt;helps in saving&amp;nbsp;computers from viruses.
	&lt;ul&gt;
		&lt;li&gt;It&amp;nbsp;is a&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;software program that identifies and eliminates any threats that can damage a computer system.&lt;/span&gt;​&lt;/li&gt;
		&lt;li&gt;It is a set of programs that are designed to prevent, search for, detect, and remove software viruses.&lt;/li&gt;
		&lt;li&gt;Antivirus software begins operating by checking&amp;nbsp;computer programs and files against a database of known types of malware.&lt;/li&gt;
		&lt;li&gt;Most antivirus programs incorporate both automated and manual filtering abilities.&amp;nbsp;&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;F-Prot,&amp;nbsp;McAfee, and&amp;nbsp;NPAV are&amp;nbsp;antivirus&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;&quot;&gt;software.&lt;/span&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;&lt;span style=&quot;&quot;&gt;सही उत्तर&amp;nbsp;&lt;/span&gt;&lt;u style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;Fedora&lt;/span&gt;&lt;/u&gt;&lt;span style=&quot;&quot;&gt; &lt;/span&gt;है।&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;Fedora&lt;/span&gt;&lt;/u&gt; एक एंटीवायरस सॉफ्टवेयर नहीं है।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Fedora&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;यह एक ओपन सोर्स लिनक्स-बेस्ड&amp;nbsp;ऑपरेटिंग सिस्टम है।&lt;/li&gt;
		&lt;li&gt;Fedora ऑपरेटिंग सिस्टम एक ओपन-सोर्स ऑपरेटिंग सिस्टम है, जो कि &lt;span style=&quot;&quot;&gt;लिनक्स&lt;/span&gt; OS कर्नेल आर्किटेक्चर पर आधारित है।&lt;/li&gt;
		&lt;li&gt;यह Red Hat द्वारा प्रायोजित है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;एंटी-वायरस&lt;/strong&gt; कंप्यूटर को वायरस से बचाने में मदद करता है।
	&lt;ul&gt;
		&lt;li&gt;यह एक &lt;strong&gt;सॉफ़्टवेयर प्रोग्राम है जो कंप्यूटर सिस्टम को नुकसान पहुँचा सकने वाले किसी भी खतरे की पहचान करता है और उसे समाप्त करता है।​&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;यह प्रोग्रामों का एक सेट है, जो सॉफ़्टवेयर वायरस को रोकने, ज्ञात करने, पता लगाने और हटाने के लिए डिज़ाइन किया गया है।&lt;/li&gt;
		&lt;li&gt;एंटीवायरस सॉफ़्टवेयर के काम करना शुरू करने से पहले ज्ञात मैलवेयर प्रकारों के डेटाबेस की कंप्यूटर प्रोग्राम और फ़ाइलों के विरुद्ध जाँच की जाती है।&lt;/li&gt;
		&lt;li&gt;अधिकांश एंटीवायरस प्रोग्राम ऑटोमेटेड और मैन्युअल फ़िल्टरिंग एबिलिटीज़ दोनों को शामिल करते हैं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;F-Prot, McAfee&amp;nbsp;और NPAV एंटीवायरस सॉफ़्टवेयर हैं।&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;WAV files&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;WAV files &lt;/strong&gt;&lt;/u&gt;is a sound file&amp;nbsp;format.&lt;/span&gt;

	&lt;ul&gt;
		&lt;li&gt;It is&amp;nbsp;Waveform Audio File Format.&lt;/li&gt;
		&lt;li&gt;It&amp;nbsp;is an audio file format standard, developed by IBM and Microsoft, for storing an audio bitstream.&lt;/li&gt;
		&lt;li&gt;It is the main format used on Microsoft Windows systems for uncompressed audio.&lt;/li&gt;
		&lt;li&gt;A WAV file is a lossless audio format that does not compress the original analog audio recording from which it is derived.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;A &lt;strong&gt;DRV file&lt;/strong&gt; is a driver file used by Windows operating systems to connect and communicate with hardware devices (both external and internal).&lt;/li&gt;
	&lt;li&gt;A &lt;strong&gt;log file&lt;/strong&gt; is a computer-generated data file that contains information about usage patterns, activities, and operations within an operating system, application, server or another device.&lt;/li&gt;
	&lt;li&gt;A &lt;strong&gt;DAT file&lt;/strong&gt; is a data file that contains specific information about the program used to create it.&amp;nbsp;A file with the .dat file extension is a generic data file that stores specific information relating to the program that created the file.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;&lt;span style=&quot;&quot;&gt;सही उत्तर&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;WAV फाइल्स&amp;nbsp;&lt;/strong&gt;&lt;/u&gt;है&lt;strong&gt;।​&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;u&gt;&lt;strong&gt;WAV फ़ाइलें&lt;/strong&gt; &lt;/u&gt;एक साउंड&amp;nbsp;फ़ाइल फॉर्मेट&amp;nbsp;है।​

	&lt;ul&gt;
		&lt;li&gt;यह वेवफ़ॉर्म ऑडियो फ़ाइल फ़ॉर्मैट है।&lt;/li&gt;
		&lt;li&gt;यह एक ऑडियो बिटस्ट्रीम स्टोर करने के लिए IBM और माइक्रोसॉफ्ट द्वारा डेवलप्ड एक ऑडियो फ़ाइल फॉर्मेट स्टैण्डर्ड है।&lt;/li&gt;
		&lt;li&gt;यह असम्पीडित ऑडियो के लिए माइक्रोसॉफ्ट विंडोज सिस्टम पर इस्तेमाल किया जाने वाला मुख्य &lt;span style=&quot;&quot;&gt;फॉर्मेट&lt;/span&gt; है।&lt;/li&gt;
		&lt;li&gt;एक WAV फ़ाइल एक दोषरहित ऑडियो &lt;span style=&quot;&quot;&gt;फॉर्मेट&lt;/span&gt; है जो मूल एनालॉग ऑडियो रिकॉर्डिंग को कंप्रेस नहीं करता है जिससे इसे प्राप्त&amp;nbsp;किया गया है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;DRV फाइल &lt;/strong&gt;एक ड्राइवर फाइल है जिसका उपयोग विंडोज ऑपरेटिंग सिस्टम द्वारा हार्डवेयर डिवाइस&amp;nbsp;(एक्सटर्नल&amp;nbsp;और &lt;span style=&quot;&quot;&gt;इंटरल&lt;/span&gt; दोनों) से जुड़ने और संचार करने के लिए किया जाता है।&lt;/li&gt;
	&lt;li&gt;एक &lt;strong&gt;लॉग फ़ाइल&lt;/strong&gt; एक कंप्यूटर-जनरेटेड डेटा फ़ाइल है जिसमें एक ऑपरेटिंग सिस्टम, एप्लिकेशन, सर्वर या अन्य डिवाइस के भीतर उपयोग पैटर्न, एक्टिविटीज और ऑपरेशन्स के बारे में इनफार्मेशन होती है।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;DAT फ़ाइल &lt;/strong&gt;एक डेटा फ़ाइल होती है जिसमें इसे बनाने के लिए उपयोग किए गए प्रोग्राम के बारे में स्पेसिफिक इनफार्मेशन होती है। .dat फ़ाइल एक्सटेंशन वाली फ़ाइल एक जेनेरिक डेटा फ़ाइल होती है जो फ़ाइल बनाने वाले प्रोग्राम से संबंधित स्पेसिफिक इनफार्मेशन स्टोर&amp;nbsp;करती है।&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;132 column printers, Ink jet printers&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Page printers&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;It&amp;nbsp;&lt;/span&gt;is a non-impact printer that prints a full page at once.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;Laser&lt;/strong&gt;, LED and solid ink printers are examples&amp;nbsp;of this printer.&lt;/li&gt;
		&lt;li&gt;A laser printer does not require ink but it uses toner, which is made up of plastic and iron particles that are heated and melted to the paper by a fuser unit.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Line printers&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​It is a printer that&amp;nbsp;&lt;/span&gt;prints one entire line of text before advancing to another line.&lt;/li&gt;
		&lt;li&gt;Early line printers used a type of slugs linked together in a chain as its printing mechanism.&lt;/li&gt;
		&lt;li&gt;A drum printer is the type of line printer.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;​&lt;strong&gt;Drum printer&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;​It prints&amp;nbsp;characters etched on a physical drum that spun around and impacted paper in specific ways.&lt;/li&gt;
		&lt;li&gt;A series of hammers behind the paper would press the paper onto the drum at the right time, to create text on a page.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Impact printers&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​It&amp;nbsp;&lt;/span&gt;refers to a class of printers that work by banging a head or needle against an ink ribbon to make a mark on the paper.&lt;/li&gt;
		&lt;li&gt;The three most common forms of impact printers are
		&lt;ul&gt;
			&lt;li&gt;Dot-matrix&lt;/li&gt;
			&lt;li&gt;Daisy-wheel&lt;/li&gt;
			&lt;li&gt;Line printers​&lt;span style=&quot;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
		&lt;/ul&gt;
		&lt;/li&gt;
		&lt;li&gt;Daisy Wheel Printer was invented by Dr. Andrew Gabor in 1970.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Ink jet printers&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;The Ink-jet printer prints by spraying streams of quick-drying ink on paper.&lt;/li&gt;
		&lt;li&gt;The ink is stored in disposable ink cartridges, and often a separate cartridge is used for each of the major colors.&lt;/li&gt;
		&lt;li&gt;The first inkjet printer was invented and developed by Hewlett-Packard in 1976.&lt;span style=&quot;&quot;&gt;​&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;A typical inkjet printer can produce color printing copies with a resolution of 1200 x 1440 dpi.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Dot matrix printers can be either a 80 column printer or a 132 column printer&lt;/strong&gt; depending on the maximum number of characters that can be printed in a line.&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;&lt;span style=&quot;&quot;&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;strong&gt;132 कॉलम प्रिन्टर्स, इन्क - जेट प्रिन्टर्स&amp;nbsp;&lt;/strong&gt;&lt;/u&gt;है&lt;strong&gt;।&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;पेज प्रिंटर&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;यह एक नॉन-इम्पैक्ट प्रिंटर है जो एक बार में पूरा पेज प्रिंट करता है।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;लेज़र, &lt;/strong&gt;एलईडी और सॉलिड इंक प्रिंटर इस प्रिंटर के उदाहरण हैं।&lt;/li&gt;
		&lt;li&gt;एक लेजर प्रिंटर को स्याही की आवश्यकता नहीं होती है, लेकिन यह टोनर का उपयोग करता है, जो प्लास्टिक और लोहे के कणों से बना होता है, जो एक फ्यूज़र यूनिट के&amp;nbsp; द्वारा कागज को गर्म और पिघलाया जाता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;strong&gt;लाइन प्रिंटर&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;​यह एक ऐसा प्रिंटर है जो दूसरी लाइन&amp;nbsp;में आगे बढ़ने से पहले टेक्स्ट की एक पूरी लाइन&amp;nbsp;को प्रिंट करता है।&lt;/li&gt;
		&lt;li&gt;प्रारंभिक &lt;span style=&quot;&quot;&gt;लाइन&lt;/span&gt; के प्रिंटर अपने प्रिंटिंग मैकेनिज्म के रूप में एक शृंखला में एक साथ जुड़े एक प्रकार के स्लग का उपयोग करते थे।&lt;/li&gt;
		&lt;li&gt;ड्रम प्रिंटर लाइन प्रिंटर का प्रकार है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;ड्रम प्रिंटर&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;​यह फिजिकल ड्रम पर उकेरे गए कॅरेक्टर को प्रिंट करता है जो चारों ओर घूमता है और स्पेसिफिक तरीकों से कागज को इम्पैक्ट&amp;nbsp;करता है।&lt;/li&gt;
		&lt;li&gt;कागज के पीछे हथौड़ों की एक शृंखला एक पेज&amp;nbsp;पर टेक्स्ट&amp;nbsp;बनाने के लिए सही समय पर कागज को ड्रम पर दबाएगी।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;इम्पैक्ट&amp;nbsp;प्रिंटर&lt;/strong&gt;​
	&lt;ul&gt;
		&lt;li&gt;यह प्रिंटर के उस वर्ग को संदर्भित करता है जो कागज पर निशान बनाने के लिए सिर या सुई को स्याही के रिबन से टकराकर काम करता है।&lt;/li&gt;
		&lt;li&gt;इम्पैक्ट प्रिंटर के तीन सबसे सामान्य रूप हैं
		&lt;ul&gt;
			&lt;li&gt;डॉट मैट्रिक्स&lt;/li&gt;
			&lt;li&gt;डेज़ी-व्हील&amp;nbsp;&lt;/li&gt;
			&lt;li&gt;लाइन प्रिंटर​&lt;/li&gt;
		&lt;/ul&gt;
		&lt;/li&gt;
		&lt;li&gt;डेज़ी व्हील प्रिंटर का आविष्कार 1970 में डॉ एंड्रयू गैबोर ने किया था।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;इंक जेट प्रिंटर&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;इंक-जेट प्रिंटर कागज पर त्वरित सुखाने वाली स्याही की स्प्रेइंग स्ट्रीम्स कर प्रिंट करता है।&lt;/li&gt;
		&lt;li&gt;स्याही को डिस्पोजेबल स्याही कार्ट्रिज में स्टोर&amp;nbsp;किया जाता है&amp;nbsp;और अक्सर प्रत्येक प्रमुख रंग के लिए एक अलग कार्ट्रिज का उपयोग किया जाता है।&lt;/li&gt;
		&lt;li&gt;1976 में हेवलेट पैकर्ड द्वारा पहले इंकजेट प्रिंटर का आविष्कार और विकास किया गया था&lt;span style=&quot;&quot;&gt;।&lt;/span&gt;&lt;/li&gt;
		&lt;li&gt;एक टिपिकल&amp;nbsp;इंकजेट प्रिंटर 1200 x 1440 डीपीआई के रिज़ॉल्यूशन के साथ कलर प्रिंटिंग कॉपी&amp;nbsp;तैयार कर सकता है।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;डॉट मैट्रिक्स प्रिंटर एक लाइन&amp;nbsp;में &lt;span style=&quot;&quot;&gt;प्रिंट&lt;/span&gt;&amp;nbsp;किए जा सकने वाले &lt;span style=&quot;&quot;&gt;कॅरेक्टर&lt;/span&gt; की अधिकतम संख्या&lt;/strong&gt; के आधार पर या तो 80 कॉलम प्रिंटर या 132 कॉलम प्रिंटर हो सकता है।&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Only I&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Ctrl + Shift + 8&lt;/span&gt;&lt;/strong&gt;

	&lt;div&gt;&lt;span style=&quot;&quot;&gt;In MS Word, pressing Ctrl + Shift + 8 (which is the same as pressing Ctrl + *) toggles the display of non-printing characters (also called hidden formatting symbols) such as paragraph marks (&amp;para;), spaces, tabs, and line breaks.&lt;/span&gt;&lt;/div&gt;

	&lt;div&gt;&lt;span style=&quot;&quot;&gt;This shortcut is a well-known built-in feature across MS Word versions including 2019.&lt;/span&gt;&lt;/div&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;To view &lt;span style=&quot;&quot;&gt;Hidden format symbols&lt;/span&gt;&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;Go to File &amp;gt; Options &amp;gt; Display&lt;/li&gt;
		&lt;li&gt;Under &amp;quot;Always show these formatting marks on the screen&amp;quot;, select the check box for each formatting mark that you always want to display.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Shift + Enter&lt;/strong&gt; is used to insert a &lt;strong&gt;line break&lt;/strong&gt;.&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Ctrl + Enter&lt;/strong&gt; is used to insert a &lt;strong&gt;page break&lt;/strong&gt;.&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;vertical-align: middle; &quot;&gt;&lt;u&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/u&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
