			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;Select all document content.&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+A&lt;/p&gt;
