hn.value:
&lt;p&gt;&lt;span style=&quot;&quot;&gt;सही उत्तर :&amp;nbsp;&lt;/span&gt;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;color: rgb(33, 37, 41);&quot;&gt;केवल I&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Ctrl + Shift + 8&lt;/span&gt;&lt;/strong&gt;

	&lt;div style=&quot;color: rgb(33, 37, 41);&quot;&gt;MS Word में, Ctrl + Shift + 8 (जो Ctrl + * दबाने के समान है) दबाने से गैर-मुद्रण वर्णों (जिन्हें हिडन फॉर्मेटिंग&amp;nbsp;चिह्न भी कहा जाता है) जैसे पैराग्राफ़ चिह्न (&amp;para;), रिक्त स्थान, टैब और लाइन ब्रेक का प्रदर्शन टॉगल हो जाता है। यह शॉर्टकट 2019 सहित MS Word के सभी संस्करणों में एक प्रसिद्ध अंतर्निहित सुविधा है।&lt;/div&gt;
	&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;हिडन फॉर्मेट सिम्बल्स को व्यू करने&amp;nbsp;के लिए&lt;/strong&gt;​
	&lt;ul&gt;
		&lt;li&gt;फ़ाइल&amp;gt; ऑप्शन&amp;gt; डिस्प्ले&amp;nbsp;पर जाएं।&amp;nbsp;&lt;/li&gt;
		&lt;li&gt;&amp;quot;हमेशा इन फोर्मत्तिंग मार्क्स को स्क्रीन पर दिखाएँ&amp;quot; के अंतर्गत, प्रत्येक फॉर्मेटिंग मार्क्स के लिए चेक बॉक्स का चयन करें जिसे आप हमेशा डिस्प्ले&amp;nbsp;करना चाहते हैं।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;Shift+Enter का प्रयोग लाइन ब्रेक डालने के लिए किया जाता है।&lt;/li&gt;
	&lt;li&gt;Ctrl+Enter का प्रयोग पेज ब्रेक इन्सर्ट करने&amp;nbsp;के लिए किया जाता है।&lt;/li&gt;
&lt;/ul&gt;

&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;display: flex; gap: 6px; align-items: center;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;span style=&quot;vertical-align: middle; &quot;&gt;&lt;u&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/additional-information-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Additional Information&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/u&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;एमएस वर्ड में शॉर्टकट&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;
	&lt;table border=&quot;1&quot; cellpadding=&quot;0&quot; cellspacing=&quot;0&quot; style=&quot; width: 350px;&quot;&gt;
		&lt;tbody&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;एक डॉक्यूमेंट खोलें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+O&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;एक नया डॉक्यूमेंट बनाएँ।&amp;nbsp;&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+N&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;डॉक्यूमेंट सेव करे।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+S&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;डॉक्यूमेंट क्लोज&amp;nbsp;करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+W&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;चयनित कंटेंट&amp;nbsp;को क्लिपबोर्ड पर कट करे।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+X&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;चयनित &lt;span style=&quot;&quot;&gt;कंटेंट&lt;/span&gt; को क्लिपबोर्ड पर कॉपी करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+C&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;क्लिपबोर्ड की &lt;span style=&quot;&quot;&gt;कंटेंट&lt;/span&gt; को पेस्ट करें&lt;span style=&quot;&quot;&gt;।&lt;/span&gt;&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+V&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;सभी डॉक्यूमेंट &lt;span style=&quot;&quot;&gt;कंटेंट&lt;/span&gt; का चयन करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+A&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;टेक्स्ट में बोल्ड &lt;span style=&quot;&quot;&gt;फ़ॉर्मैटिंग&lt;/span&gt; लागू करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+B&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;टेक्स्ट&amp;nbsp;पर इटैलिक &lt;span style=&quot;&quot;&gt;फ़ॉर्मैटिंग&lt;/span&gt; लागू करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+I&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;टेक्स्ट पर अंडरलाइन फ़ॉर्मैटिंग लागू करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+U&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;फ़ॉन्ट साइज&amp;nbsp;को 1 बिंदु घटाएं।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+[&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;फ़ॉन्ट का &lt;span style=&quot;&quot;&gt;साइज&lt;/span&gt; 1 बिंदु बढ़ाएँ।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+]&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;&lt;span style=&quot;&quot;&gt;टेक्स्ट&lt;/span&gt; को केन्द्रित करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+E&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;&lt;span style=&quot;&quot;&gt;टेक्स्ट&amp;nbsp;&lt;/span&gt;को बाईं ओर अलाइन&amp;nbsp;करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+L&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;&lt;span style=&quot;&quot;&gt;टेक्स्ट&lt;/span&gt; को दाईं ओर &lt;span style=&quot;&quot;&gt;अलाइन&lt;/span&gt; करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+R&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;एक कमांड कैंसिल करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Esc&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;प्रीवियस एक्शन को अंडू&amp;nbsp; &amp;nbsp;करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+Z&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;&lt;span style=&quot;&quot;&gt;यदि संभव हो तो प्रीवियस एक्शन को रीडू&amp;nbsp;करें।&lt;/span&gt;&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+Y&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;ज़ूम मैग्निफिकेशन एडजस्ट&amp;nbsp; करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Alt+W, Q, फिर ज़ूम डायलॉग बॉक्स में इच्छित वैल्यू&amp;nbsp;पर टैब करें&lt;span style=&quot;&quot;&gt;।&lt;/span&gt;&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;डॉक्यूमेंट विंडो को स्पिल्ट&amp;nbsp; करें।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Ctrl+Alt+S&lt;/p&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
				&lt;td&gt;
				&lt;p&gt;डॉक्यूमेंट विंडो स्प्लिट रिमूव करे।&lt;/p&gt;
				&lt;/td&gt;
				&lt;td&gt;
				&lt;p&gt;Alt+Shift+C या Ctrl+Alt+S&lt;/p&gt;

				&lt;div&gt;&amp;nbsp;&lt;/div&gt;
				&lt;/td&gt;
			&lt;/tr&gt;
		&lt;/tbody&gt;
	&lt;/table&gt;
	&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;1 and 3&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;Web 3.0&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;It&amp;nbsp;is the third generation of the evolution of web technologies.&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;​&lt;/span&gt;It is a&lt;strong&gt; decentralized&lt;/strong&gt; internet to be run on &lt;strong&gt;blockchain technology&lt;/strong&gt;.&lt;/li&gt;
		&lt;li&gt;It&amp;nbsp;is a set of values and technical applications that define a new era of the World Wide Web.&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;Web 3.0 is not operated by intergovernmental panel.&amp;nbsp;&lt;/span&gt;It will be permissionless and democratic.&lt;/li&gt;
		&lt;li&gt;It&amp;nbsp;is built upon the core concepts of &lt;strong&gt;decentralization, openness, and greater user utility&lt;/strong&gt;.&lt;/li&gt;
		&lt;li&gt;&lt;span style=&quot;&quot;&gt;Web 3.0 Technology enables people to control their own data.&amp;nbsp;&lt;/span&gt;In Web3, users will have ownership stakes in platforms and applications.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;In Web 3.0, computers will be able to understand information similarly to humans, through technologies based upon Semantic Web concepts and natural language processing.&lt;/li&gt;
	&lt;li&gt;In a Web 3.0 universe, people will control their own data and will be able to move around from social media to email to shopping using a single personalized account, creating a public record on the blockchain of all of that activity.&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;&lt;span style=&quot;&quot;&gt;सही उत्तर&lt;u&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/u&gt;&lt;/span&gt;&lt;u&gt;&lt;strong&gt;1 और 3&amp;nbsp;&lt;/strong&gt;&lt;/u&gt;&lt;span style=&quot;&quot;&gt;है&lt;/span&gt;&lt;u&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;।&lt;/span&gt;&lt;/strong&gt;&lt;/u&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;वैब 3.0&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;

	&lt;ul&gt;
		&lt;li&gt;यह वेब टेक्नोलॉजीस&amp;nbsp;के विकास की तीसरी पीढ़ी है।​&lt;/li&gt;
		&lt;li&gt;यह &lt;strong&gt;ब्लॉकचेन &lt;span style=&quot;&quot;&gt;टेक्नोलॉजी&lt;/span&gt;&lt;/strong&gt; पर रन होने वाला एक &lt;strong&gt;डेंटरलिज़्ड &lt;/strong&gt;इंटरनेट है।&lt;/li&gt;
		&lt;li&gt;यह वैल्यू&amp;nbsp;और टेक्निकल ऍप्लिकेशन्स का एक सेट है जो वर्ल्ड वाइड वेब के एक नए एरा को परिभाषित करता है।&lt;/li&gt;
		&lt;li&gt;वेब 3.0 इंटरगवर्नमेंटल पैनल द्वारा ऑपरेटेड नहीं है। यह अनुमति रहित और लोकतांत्रिक होगा।&lt;/li&gt;
		&lt;li&gt;यह&lt;strong&gt; &lt;/strong&gt;&lt;strong&gt;विकेंद्रीकरण, स्पष्टता&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;और ग्रेटर यूजर यूटिलिटी की&lt;/strong&gt; कोर कॉन्सेप्ट्स पर बनाया गया है।&lt;/li&gt;
		&lt;li&gt;वेब 3.0 &lt;span style=&quot;&quot;&gt;टेक्नोलॉजी&lt;/span&gt; लोगों को अपने स्वयं के डेटा को कण्ट्रोल&amp;nbsp;करने में सक्षम बनाती है। Web3 में, यूजर के पास प्लेटफ़ॉर्म और एप्लिकेशन में ओनरशिप स्टेक्स का हिस्सा होगा।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
	&lt;li&gt;वेब 3.0 में, सिमेंटिक वेब &lt;span style=&quot;&quot;&gt;कॉन्सेप्ट्स&lt;/span&gt;&amp;nbsp;और नेचुरल लैंग्वेज प्रोसेसिंग पर आधारित टेक्नोलॉजी के माध्यम से, कंप्यूटर मनुष्यों के समान इनफार्मेशन को समझने में सक्षम होंगे।&lt;/li&gt;
	&lt;li&gt;एक वेब 3.0 यूनिवर्स में, लोग अपने स्वयं के डेटा को कण्ट्रोल&amp;nbsp; करेंगे और एक पर्सनलाइज्ड अकाउंट का उपयोग करके सोशल मीडिया से ईमेल से खरीदारी करने में सक्षम होंगे, उस सभी एक्टिविटी&amp;nbsp;के ब्लॉकचेन पर एक पब्लिक&amp;nbsp;रिकॉर्ड बना सकते हैं।&lt;/li&gt;
&lt;/ul&gt;

en.value:
&lt;p&gt;The correct answer is&amp;nbsp;&lt;span style=&quot;&quot;&gt;&lt;u&gt;&lt;strong&gt;Filarial worms&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;Elephantiasis is caused by&amp;nbsp;&lt;u&gt;&lt;strong&gt;Filarial worms&lt;/strong&gt;&lt;/u&gt;.&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;Lymphatic Filariasis commonly known as Elephantiasis is one of the oldest tropical diseases which is caused by Filarial worms.&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;It is transmitted by the bite of an infected mosquito.&lt;/li&gt;
		&lt;li&gt;The saliva of the infected mosquito carries the parasite larva of the worms causing filariasis.&lt;/li&gt;
		&lt;li&gt;This parasitic larva enters the bloodstream of the person from where it migrates to the lymphatic vessels and develops to become adult worms.&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;The parasite worms causing this are Wuchereria malayi &amp;amp; Wuchereria bancrofti.&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;These worms create a blockage of lymph vessels that results in intense swelling.&lt;/li&gt;
		&lt;li&gt;The lower limbs of the infected person appear like the legs of an elephant, thus it is named elephantiasis.&lt;/li&gt;
		&lt;li&gt;The genital organs may also get affected, leading to severe deformation.&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

hn.value:
&lt;p&gt;सही उत्तर&amp;nbsp;&lt;u&gt;&lt;strong&gt;फाइलेरिया कृमि&lt;/strong&gt;&lt;/u&gt;&lt;span style=&quot;&quot;&gt; है&lt;/span&gt;।&lt;span style=&quot;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;श्लीपद (एलीफेंटियासिस) &lt;u&gt;&lt;strong&gt;फाइलेरिया कृमि&lt;/strong&gt;&lt;/u&gt; के कारण होता है।&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;लिंफैटिक&amp;nbsp;&lt;/strong&gt;&lt;strong&gt;फाइलेरिया रोग&amp;nbsp;जिसे आमतौर पर श्लीपद के रूप में जाना जाता है, सबसे पुराने उष्णकटिबंधीय रोगों में से एक है&amp;nbsp;जो फाइलेरिया कृमि के कारण होता है।&lt;/strong&gt;
	&lt;ul&gt;
		&lt;li&gt;यह एक संक्रमित मच्छर के काटने से फैलता है।&lt;/li&gt;
		&lt;li&gt;संक्रमित मच्छर की लार में फाइलेरिया उत्पन्न&amp;nbsp;करने वाले कृमियों के परजीवी लार्वा होते हैं।&lt;/li&gt;
		&lt;li&gt;यह परजीवी लार्वा व्यक्ति के रक्तप्रवाह में प्रवेश करता है जहां से यह लसीका वाहिकाओं में चला जाता है और वयस्क कृमि बनने के लिए विकसित होता है।&lt;/li&gt;
		&lt;li&gt;&lt;strong&gt;वुचेरेरिया&lt;/strong&gt;&amp;nbsp;&lt;strong&gt;मलेयी और वुचेरेरिया&lt;/strong&gt;&amp;nbsp;&lt;strong&gt;ब्रेंकोफ्टाई&lt;/strong&gt;&amp;nbsp;&lt;strong&gt;नामक&amp;nbsp;परजीवी कृमि इस रोग के कारण हैं।&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;
		&lt;li&gt;ये कृमि लसीका वाहिकाओं में रुकावट &lt;span style=&quot;&quot;&gt;उत्पन्न&lt;/span&gt; करते हैं जिसके परिणामस्वरूप तीव्र सूजन होती है।&lt;/li&gt;
		&lt;li&gt;संक्रमित व्यक्ति के निचले अंग हाथी के पाद&amp;nbsp;जैसे दिखाई देते हैं, इसलिए इसे श्लीपद (&lt;span style=&quot;&quot;&gt;एलीफेंटियासिस&lt;/span&gt;) कहते हैं।&lt;/li&gt;
		&lt;li&gt;इससे जनन अंग भी प्रभावित होते हैं, जिससे गंभीर विकृतियां&amp;nbsp;होती &lt;span style=&quot;&quot;&gt;हैं&lt;/span&gt;।&lt;/li&gt;
	&lt;/ul&gt;
	&lt;/li&gt;
&lt;/ul&gt;

