&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;किसी&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;शब्द&lt;/span&gt;&amp;nbsp;में आये हुए&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;अक्षरों&amp;nbsp;&lt;/span&gt;को मात्राओं&amp;nbsp; सहित&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;कहने या लिखने&lt;/span&gt;&amp;nbsp;की&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;रीति&lt;/span&gt;&amp;nbsp;को&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;वर्तनी&lt;/span&gt;&amp;nbsp;कहते हैं।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;वर्तनी&lt;/span&gt;&amp;nbsp;का सम्बन्ध का सीधा सम्बन्ध&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;उच्चारण&amp;nbsp;&lt;/span&gt;से होता है।&lt;/li&gt;
	&lt;li&gt;यदि&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;उच्चारण शुद्ध&lt;/span&gt;&amp;nbsp;होगा तो वर्तनी शुद्ध होगी और यदि&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;उच्चारण अशुद्ध&amp;nbsp;&lt;/span&gt;होगा तो&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;वर्तनी भी&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;अशुद्ध&amp;nbsp;&lt;/span&gt;होगी।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;​&lt;span style=&quot;font-weight: 700;&quot;&gt;कुछ अन्य शुद्ध&amp;nbsp;&lt;/span&gt;&lt;strong&gt;और&lt;/strong&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;अशुद्ध शब्द:-&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;अशुद्ध -&amp;nbsp;&amp;nbsp;शुद्ध&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;ज्योत्सना -&amp;nbsp; ज्योत्स्ना&lt;/li&gt;
	&lt;li&gt;गीतांजली -&amp;nbsp; गीतांजलि&lt;/li&gt;
	&lt;li&gt;न्यौछावर -&amp;nbsp; न्योछावर&lt;/li&gt;
	&lt;li&gt;तुष्टिकरण -&amp;nbsp; तुष्टीकरण&lt;span style=&quot;white-space: pre;&quot;&gt; &lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;अन्ताक्षरी&lt;span style=&quot;white-space: pre;&quot;&gt; - &lt;/span&gt;अन्त्याक्षरी&lt;/li&gt;
	&lt;li&gt;नौसीखिया -&amp;nbsp;नौसिखिया&lt;/li&gt;
	&lt;li&gt;अक्षोहिणी -&lt;span style=&quot;white-space: pre;&quot;&gt; &lt;/span&gt;अक्षौहिणी&lt;/li&gt;
	&lt;li&gt;सप्ताहिक -&amp;nbsp; साप्ताहिक&lt;/li&gt;
	&lt;li&gt;कार्यवाई -&amp;nbsp; &amp;nbsp;कार्रवाई&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&amp;#39;राजा&amp;nbsp;&lt;/span&gt;&lt;strong&gt;&lt;u&gt;सेवक&lt;/u&gt;&lt;/strong&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;&lt;u&gt;&amp;nbsp;को&lt;/u&gt;&lt;/strong&gt; कम्बल देता है।&lt;strong&gt; &amp;#39;उक्त&amp;#39; &lt;/strong&gt;वाक्य में रेखांकित पद में कारक है -&lt;strong&gt; &amp;#39;सम्प्रदान कारक&amp;#39;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;(यहाँ पर&lt;strong&gt;&amp;nbsp;&amp;#39;को&amp;#39; &lt;/strong&gt;विभक्ति चिह्न&amp;nbsp;का प्रयोग करते&amp;nbsp;है। यह&amp;nbsp;&lt;span style=&quot;&quot;&gt;चिह्न&lt;/span&gt; बताता है, कि किसी ने &lt;strong&gt;किसी को कुछ दिया है।&lt;/strong&gt;)&lt;/li&gt;
	&lt;li&gt;जब &lt;strong&gt;वाक्य&lt;/strong&gt; में किसी को&lt;strong&gt; कुछ&lt;/strong&gt; &lt;strong&gt;दिया जाए &lt;/strong&gt;या किसी के लिए &lt;strong&gt;कुछ किया जाए&lt;/strong&gt; तो वहां पर&lt;strong&gt; सम्प्रदान कारक&lt;/strong&gt; होता है।&lt;/li&gt;
	&lt;li&gt;सम्प्रदान कारक के विभक्ति चिन्ह&amp;nbsp;&lt;span style=&quot;font-weight: bolder;&quot;&gt;के लिए&amp;nbsp;&lt;/span&gt;या&amp;nbsp;&lt;span style=&quot;font-weight: bolder;&quot;&gt;को&amp;nbsp;&lt;/span&gt;हैं।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;strong&gt;जैसे -&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;वह अरुण &lt;strong&gt;&lt;u&gt;के लिए&lt;/u&gt;&lt;/strong&gt; मिठाई लाया।&lt;/li&gt;
	&lt;li&gt;विकास तुषार &lt;strong&gt;&lt;u&gt;को&lt;/u&gt;&lt;/strong&gt; किताबें देता है।&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;table border=&quot;2&quot; style=&quot;width:200px;&quot;&gt;
	&lt;tbody&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;strong&gt;कारक&lt;/strong&gt;&lt;/td&gt;
			&lt;td&gt;&lt;strong&gt;विभक्ति&lt;/strong&gt;&lt;/td&gt;
		&lt;/tr&gt;
