&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;table border=&quot;2&quot; cellpadding=&quot;1&quot; cellspacing=&quot;1&quot; style=&quot;width:300px;&quot;&gt;
	&lt;tbody&gt;
		&lt;tr&gt;
			&lt;td&gt;
			&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;कर्ता कारक:-&lt;/span&gt;&lt;/p&gt;

			&lt;ul style=&quot;&quot;&gt;
				&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;संज्ञा&lt;/span&gt;&amp;nbsp;या&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;सर्वनाम&amp;nbsp;&lt;/span&gt;के जिस रूप से&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;क्रिया करने वाले का बोध&lt;/span&gt;&amp;nbsp;होता है, उसे&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;कर्ता कारक&lt;/span&gt;&amp;nbsp;कहते हैं।&lt;/li&gt;
				&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;कर्ता कारक&amp;nbsp;&lt;/span&gt;का विभक्ति चिन्ह&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;&amp;lsquo;ने&amp;rsquo;&amp;nbsp;&lt;/span&gt;होता है।&amp;nbsp;&lt;/li&gt;
			&lt;/ul&gt;

			&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;जैसे -&lt;/span&gt;&amp;nbsp;&lt;/p&gt;

			&lt;ul style=&quot;&quot;&gt;
				&lt;li&gt;अमित&amp;nbsp;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;ने&lt;/span&gt;&lt;/u&gt;&amp;nbsp;पूरी किताब पढ़ ली।&amp;nbsp;&lt;/li&gt;
				&lt;li&gt;मेरे मित्र&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;u&gt;ने&lt;/u&gt;&lt;/span&gt;&amp;nbsp;मेरी सहायता की।&lt;/li&gt;
			&lt;/ul&gt;

			&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;कर्म कारक:-&lt;/span&gt;&lt;/p&gt;

			&lt;ul style=&quot;&quot;&gt;
				&lt;li&gt;वह&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;वस्तु&lt;/span&gt;&amp;nbsp;या&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;व्यक्ति&amp;nbsp;&lt;/span&gt;जिस पर&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;वाक्य&lt;/span&gt;&amp;nbsp;में की गयी&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;क्रिया का प्रभाव&amp;nbsp;&lt;/span&gt;पड़ता है वह&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;कर्म&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;कारक&amp;nbsp;&lt;/span&gt;कहलाता है।&lt;/li&gt;
				&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;कर्म कारक&lt;/span&gt;&amp;nbsp;का विभक्ति चिन्ह&lt;span style=&quot;font-weight: 700;&quot;&gt;&amp;nbsp;&amp;lsquo;को&amp;rsquo;&lt;/span&gt;&amp;nbsp;होता है।&lt;/li&gt;
			&lt;/ul&gt;

			&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;जैसे -&lt;/span&gt;&lt;/p&gt;

			&lt;ul style=&quot;&quot;&gt;
				&lt;li&gt;राम ने रावण&amp;nbsp;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;को&lt;/span&gt;&lt;/u&gt;&amp;nbsp;मारा।&amp;nbsp;&lt;/li&gt;
				&lt;li&gt;माँ बच्चे&amp;nbsp;&lt;u&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;को&lt;/span&gt;&lt;/u&gt;&amp;nbsp;सुला रही है।&lt;/li&gt;
			&lt;/ul&gt;

			&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;सम्बन्ध कारक:-&lt;/span&gt;&amp;nbsp;&lt;/p&gt;

			&lt;ul style=&quot;&quot;&gt;
				&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;संज्ञा&lt;/span&gt;&amp;nbsp;या&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;सर्वनाम&amp;nbsp;&lt;/span&gt;का वह रूप जो हमें किन्हीं&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;दो वस्तुओं के बीच संबंध&lt;/span&gt;&amp;nbsp;का बोध कराता है, वह&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;संबंध कारक&amp;nbsp;&lt;/span&gt;कहलाता है।&lt;/li&gt;
				&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;सम्बन्ध कारक&lt;/span&gt;&amp;nbsp;के विभक्ति चिन्ह&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;का, के, की, ना, ने, नो, रा, रे, री&lt;/span&gt;&amp;nbsp;आदि हैं।&lt;/li&gt;
			&lt;/ul&gt;

			&lt;p style=&quot;&quot;&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;जैसे -&lt;/span&gt;&lt;/p&gt;

			&lt;ul style=&quot;&quot;&gt;
				&lt;li&gt;राजा दशरथ&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;u&gt;के&lt;/u&gt;&lt;/span&gt;&amp;nbsp;चार बेटे थे।&amp;nbsp;&lt;/li&gt;
				&lt;li&gt;यह सुनील&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;u&gt;की&lt;/u&gt;&lt;/span&gt;&amp;nbsp;किताब है।&lt;/li&gt;
				&lt;li&gt;यह साहिल&amp;nbsp;&lt;span style=&quot;font-weight: 700;&quot;&gt;&lt;u&gt;का&lt;/u&gt;&lt;/span&gt;&amp;nbsp;स्कूटर है।&amp;nbsp;&lt;/li&gt;
			&lt;/ul&gt;
			&lt;/td&gt;
		&lt;/tr&gt;
