&lt;/table&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;&amp;#39;सबसे अलग स्थिति&amp;#39; &lt;/strong&gt;उक्त अर्थ की बोधक लोकोक्ति है-&amp;nbsp;&lt;strong&gt; &amp;#39;तीन लोक से मथुरा न्यारी&amp;#39;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;वाक्य प्रयोग-&amp;nbsp;&lt;/strong&gt;हमारी छोटी बेटी का सजने सवरने का ढंग ऐसा है जैसे- &lt;strong&gt;&amp;quot;तीन लोक से मथुरा न्यारी&amp;quot;।&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/mistake-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Mistake Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;बालू से तेल निकालना-&lt;/span&gt;&amp;nbsp;&lt;/strong&gt;असंभव को संभव करना&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;चमड़ी जाए पर दमड़ी न जाए-&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;अत्यधिक कंचूस होना।&amp;nbsp;&lt;/li&gt;
	&lt;li&gt;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;तू डाल-डाल, मैं पात-पात-&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;किसी की चालों को खूब समझना&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;जब कोई पूरा कथन किसी &lt;strong&gt;प्रसंग विशेष में उद्धत &lt;/strong&gt;किया जाता है तो&lt;strong&gt; लोकोक्ति&lt;/strong&gt; कहलाता है।&lt;/li&gt;
	&lt;li&gt;इसी को &lt;strong&gt;कहावत&lt;/strong&gt; कहते है। &lt;strong&gt;लोकोक्ति वाक्यांश&lt;/strong&gt; न होकर &lt;strong&gt;स्वतंत्र &lt;/strong&gt;वाक्य होते हैं।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;कुछ महत्वपूर्ण&amp;nbsp;लोकोक्ति और उनके अर्थ:-&lt;/span&gt;&lt;/p&gt;

&lt;ul style=&quot;&quot;&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;आँख का अन्धा नाम नयनसुख -&amp;nbsp;&lt;/span&gt;गुण के विरुद्ध नाम होना।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;गुड़ खाए गुलगुलों से परहेज -&amp;nbsp;&lt;/span&gt;कोई बड़ी बुराई करना और छोटी से बचना&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;उतर गई लोई तो क्या करेगा कोई -&amp;nbsp;&lt;/span&gt;&amp;nbsp;बेशर्म व्यक्ति पर कोई प्रभाव नहीं पड़ता&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;ऊधो का लेना न माधो का देना -&amp;nbsp;&lt;/span&gt;केवल अपने काम से काम रखना&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;गुड़ खाए गुलगुलों से परहेज -&lt;/span&gt;&amp;nbsp;कोई बड़ी बुराई करना और छोटी से बचना&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;जिन ढूँढ़ा तिन पाइयाँ गहरे पानी पैठ -&lt;/span&gt;&amp;nbsp;परिश्रम का फल अवश्य मिलता है&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;ढाक के वही तीन पात -&lt;/span&gt;&amp;nbsp;परिणाम कुछ नहीं निकलना, बात वहीं की वहीं रहना&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700;&quot;&gt;तेल देखो, तेल की धार देखो -&lt;/span&gt;&amp;nbsp;किसी कार्य का परिणाम देखने की बात करना&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;Contempt &lt;/strong&gt;के लिए प्रयुक्त पारिभाषिक शब्द होगा-&lt;strong&gt; &amp;#39;अवमानना&amp;#39;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;font-weight: 700; &quot;&gt;अवमानना-&amp;nbsp;&lt;/span&gt;बात न मानने की क्रिया,&amp;nbsp;आदेश का उल्लंघन,&amp;nbsp;तिरस्कार।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/key-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Key Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;Article -&lt;strong&gt;&amp;nbsp;आलेख&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;Consolidated -&amp;nbsp;&lt;strong&gt;&lt;span style=&quot;&quot;&gt;समेकित&lt;/span&gt;&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;Announcement -&lt;strong&gt;&amp;nbsp;&lt;span style=&quot;&quot;&gt;घोषणा&lt;/span&gt;&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/important-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Important Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;strong&gt;कुछ महत्वपूर्ण अग्रेंजी से हिंदी शब्द:-&lt;/strong&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;Spontaneity &lt;strong&gt;-&amp;nbsp;स्वच्छंदता&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;Deviation&lt;strong&gt; -&amp;nbsp;विचलन&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;Displacement&amp;nbsp;&lt;strong&gt;-&amp;nbsp;विस्थापन&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;Hegemony&lt;strong&gt; -&amp;nbsp;आधिपत्य&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;Incontrovertible&lt;strong&gt; -&amp;nbsp;निर्निमेष&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;Profound&lt;strong&gt;&amp;nbsp;-&amp;nbsp;प्रगल्भ&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;Justification&amp;nbsp;&lt;strong&gt;-&amp;nbsp;औचित्य&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;Integrated&amp;nbsp;&lt;strong&gt;-&amp;nbsp;एकीकृत&lt;/strong&gt;&lt;/li&gt;
	&lt;li&gt;Optimum&lt;strong&gt; - इष्टतम&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;&quot;&gt;असंगत विलोम - युग्म है- &lt;strong&gt;&amp;#39;अधम - महान, आज्ञा - अनुज्ञा&amp;#39;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;अधम &lt;/strong&gt;(अशुद्ध):&amp;nbsp;&lt;/span&gt;पापी, दुराचारी।&amp;nbsp;&lt;span style=&quot;&quot;&gt;-&amp;nbsp;&lt;/span&gt;&lt;strong&gt;उत्तम&lt;/strong&gt; (&lt;span style=&quot;&quot;&gt;शुद्ध):&amp;nbsp;&lt;/span&gt;सबसे अच्छा, श्रेष्ठ।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;महान &lt;/strong&gt;(अशुद्ध):&amp;nbsp;&lt;/span&gt;बहुत बड़ा, विशाल।&amp;nbsp;&lt;span style=&quot;&quot;&gt;-&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;strong&gt;क्षुद्र&lt;/strong&gt;&amp;nbsp;&lt;span style=&quot;&quot;&gt;(शुद्ध):&amp;nbsp;&lt;/span&gt;नीच, अधम।&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;आज्ञा&amp;nbsp;&lt;/strong&gt;(अशुद्ध):&lt;/span&gt;&amp;nbsp;आदेश, हुक्म। -&amp;nbsp;&lt;strong&gt;अवज्ञा&lt;/strong&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;(शुद्ध):&amp;nbsp;&lt;/span&gt;अपमान, अनादर, उपेक्षा&lt;span style=&quot;&quot;&gt;।&lt;/span&gt;&lt;/li&gt;
	&lt;li&gt;&lt;span style=&quot;&quot;&gt;&lt;strong&gt;अनुज्ञा&lt;/strong&gt;&amp;nbsp;(अशुद्ध):&amp;nbsp;&lt;/span&gt;अनुमति, स्वीकृति। -&amp;nbsp;&lt;strong&gt;अननुमति&lt;/strong&gt;&lt;span style=&quot;&quot;&gt;&amp;nbsp;(शुद्ध):&amp;nbsp;&lt;/span&gt;स्वीकृति या इजाज़त।&lt;/li&gt;
&lt;/ul&gt;

&lt;p&gt;&lt;span style=&quot;display: flex;gap: 6px;align-items: center;&quot;&gt;&lt;img height=&quot;26px&quot; src=&quot;//cdn.testbook.com/resources/lms_creative_elements/mistake-point-image.png&quot; width=&quot;26px&quot; /&gt;&lt;strong&gt;&lt;span style=&quot;vertical-align: middle;font-size: 21px;&quot;&gt;&lt;u&gt;Mistake Points&lt;/u&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;

