		&lt;/tr&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;span style=&quot;&quot;&gt;तेजस्वी&lt;/span&gt;&lt;/td&gt;
			&lt;td&gt;&lt;span style=&quot;&quot;&gt;निस्तेज&lt;/span&gt;&lt;/td&gt;
		&lt;/tr&gt;
